// 文法速查表資料（草稿，待老師審核）。t=標題 d=說明 ex=例句；k=搜尋用關鍵字（自動產生，不顯示）；簡體由繁體自動轉換（OpenCC tw2s，保留台灣用語）
window.GRAMMAR={"books":{"1":"A1","2":"A2","3":"B1"},"lessons":{"1-1":{"tc":"歡迎你來台灣！","sc":"欢迎你来台湾！"},"1-2":{"tc":"我的家人","sc":"我的家人"},"1-3":{"tc":"週末做什麼？","sc":"周末做什么？"},"1-4":{"tc":"請問一共多少錢？","sc":"请问一共多少钱？"},"1-5":{"tc":"牛肉麵真好吃","sc":"牛肉面真好吃"},"1-6":{"tc":"他們學校在山上","sc":"他们学校在山上"},"1-7":{"tc":"早上九點去 KTV","sc":"早上九点去 KTV"},"1-8":{"tc":"坐火車去台南","sc":"坐火车去台南"},"1-9":{"tc":"放假去哪裡玩？","sc":"放假去哪里玩？"},"1-10":{"tc":"台灣的水果很好吃","sc":"台湾的水果很好吃"},"1-11":{"tc":"我要租房子","sc":"我要租房子"},"1-12":{"tc":"你在台灣學多久的中文？","sc":"你在台湾学多久的中文？"},"1-13":{"tc":"生日快樂","sc":"生日快乐"},"1-14":{"tc":"天氣這麼冷！","sc":"天气这么冷！"},"1-15":{"tc":"我很不舒服","sc":"我很不舒服"},"2-1":{"tc":"請問，到師到怎麼走？","sc":"请问，到师到怎么走？"},"2-2":{"tc":"還是坐捷運吧！","sc":"还是坐捷运吧！"},"2-3":{"tc":"你的中文進步了！","sc":"你的中文进步了！"},"2-4":{"tc":"我打工，我教法文","sc":"我打工，我教法文"},"2-5":{"tc":"吃喜酒","sc":"吃喜酒"},"2-6":{"tc":"我打算搬到學校附近","sc":"我打算搬到学校附近"},"2-7":{"tc":"垃圾車來了！","sc":"垃圾车来了！"},"2-8":{"tc":"學功夫","sc":"学功夫"},"2-9":{"tc":"那個城市好漂亮","sc":"那个城市好漂亮"},"2-10":{"tc":"歡迎到我家來包餃子","sc":"欢迎到我家来包饺子"},"2-11":{"tc":"台灣好玩的地方真多","sc":"台湾好玩的地方真多"},"2-12":{"tc":"怎麼吃才健康？","sc":"怎么吃才健康？"},"2-13":{"tc":"我的手機掉了","sc":"我的手机掉了"},"2-14":{"tc":"我要開始工作了","sc":"我要开始工作了"},"2-15":{"tc":"過春節","sc":"过春节"},"3-1":{"tc":"開學了","sc":"开学了"},"3-2":{"tc":"八折起","sc":"八折起"},"3-3":{"tc":"外套帶了沒有？","sc":"外套带了没有？"},"3-4":{"tc":"我愛台灣的人情味","sc":"我爱台湾的人情味"},"3-5":{"tc":"現在流行什麼？","sc":"现在流行什么？"},"3-6":{"tc":"到鄉下住一晚！","sc":"到乡下住一晚！"},"3-7":{"tc":"我最親的家「人」","sc":"我最亲的家「人」"},"3-8":{"tc":"我想做自己","sc":"我想做自己"},"3-9":{"tc":"網購時代","sc":"网购时代"},"3-10":{"tc":"我住院了","sc":"我住院了"},"3-11":{"tc":"台灣故事","sc":"台湾故事"},"3-12":{"tc":"我要去投票","sc":"我要去投票"}},"points":[{"id":"1-1-0","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Preguntas con 嗎","en":"Ways to Ask Questions in Chinese / Asking Questions with 嗎 ma","ens":"Ways to Ask Questions in Chinese / Asking Questions with 吗 ma","tc":"用「嗎」問問題","sc":"用「吗」问问题"},"d":{"es":"Para preguntas de sí/no: añade 嗎 al final de una oración afirmativa. También puedes usar la forma A-no-A (verbo + 不 + verbo).","en":"For yes/no questions, add 嗎 at the end of a statement. You can also use the A-not-A pattern (verb + 不 + verb).","tc":"問是不是、有沒有的問題時，在句子最後加「嗎」。也可以用「A 不 A」的方式問，例如「是不是」。","sc":"问是不是、有没有的问题时，在句子最后加「吗」。也可以用「A 不 A」的方式问，例如「是不是」。"},"ex":[{"c":"你是學生嗎？","s":"你是学生吗？","es":"¿Eres estudiante?","en":"Are you a student?"},{"c":"你是不是學生？","s":"你是不是学生？","es":"¿Eres o no eres estudiante?","en":"Are you a student or not?"}]},{"id":"1-1-1","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 negación negar negativa negation negative 否定 pregunta preguntar interrogativa question ask 疑问 问句 提问 negación negar negativa negation negative 否定","t":{"es":"Cómo responder: 是 / 不是","en":"Answering Questions in Chinese / Affirmative Answers / Negative Replies with 不 bù","ens":"Answering Questions in Chinese / Affirmative Answers / Negative Replies with 不 bù","tc":"回答問題：是／不是","sc":"回答问题：是／不是"},"d":{"es":"Se responde repitiendo el verbo: 是 / 不是. La negación 不 va justo antes del verbo o adjetivo. No se contesta con un simple «sí/no».","en":"Answer by repeating the verb: 是 / 不是. 不 goes right before the verb or adjective. Don't answer with a bare 'yes' or 'no'.","tc":"回答時重複問句裡的動詞，例如「是」或「不是」。「不」放在動詞或形容詞前面，不要只回答 yes 或 no。","sc":"回答时重复问句里的动词，例如「是」或「不是」。「不」放在动词或形容词前面，不要只回答 yes 或 no。"},"ex":[{"c":"你是老師嗎？——不是，我不是老師。","s":"你是老师吗？——不是，我不是老师。","es":"¿Eres profesor? — No, no soy profesor.","en":"Are you a teacher? — No, I'm not a teacher."}]},{"id":"1-1-2","b":1,"l":1,"k":"","t":{"es":"Adjetivos con 很","en":"Modification Marker 很 hěn","ens":"Modification Marker 很 hěn","tc":"形容詞前面的「很」","sc":"形容词前面的「很」"},"d":{"es":"Con adjetivos (verbos estativos) se pone 很 antes del adjetivo. Aquí 很 casi no significa «muy»; sin él, la oración suena a comparación.","en":"When an adjective is the predicate, put 很 before it. Here 很 usually doesn't mean 'very'; without it the sentence sounds like a comparison.","tc":"形容詞當謂語時，前面通常要加「很」。這裡的「很」不一定是「非常」的意思，沒有它句子會像在做比較。","sc":"形容词当谓语时，前面通常要加「很」。这里的「很」不一定是「非常」的意思，没有它句子会像在做比较。"},"ex":[{"c":"我很忙。","s":"我很忙。","es":"Estoy ocupado.","en":"I'm busy."}]},{"id":"1-1-3","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Y tú? con 呢","en":"Contrastive Questions with 呢 ne","ens":"Contrastive Questions with 呢 ne","tc":"用「呢」反問","sc":"用「呢」反问"},"d":{"es":"呢 devuelve la misma pregunta al otro: «¿y tú?», «¿y …?».","en":"呢 turns the same question back to the other person: 'And you?', 'What about …?'.","tc":"「呢」可以把同樣的問題丟給對方，意思是「那你呢？」「那……呢？」。","sc":"「呢」可以把同样的问题丢给对方，意思是「那你呢？」「那……呢？」。"},"ex":[{"c":"我很好，你呢？","s":"我很好，你呢？","es":"Yo estoy bien, ¿y tú?","en":"I'm fine, and you?"}]},{"id":"1-2-0","b":1,"l":2,"k":"","t":{"es":"Posesión con 的","en":"的 de possessive","ens":"的 de possessive","tc":"表示擁有的「的」","sc":"表示拥有的「的」"},"d":{"es":"Sustantivo/pronombre + 的 + sustantivo expresa posesión. Con familiares o personas muy cercanas se suele omitir 的.","en":"Noun/pronoun + 的 + noun shows possession. With family or very close people, 的 is often left out.","tc":"「名詞或代名詞＋的＋名詞」表示誰的東西。家人或很親近的人，常常可以省略「的」。","sc":"「名词或代名词＋的＋名词」表示谁的东西。家人或很亲近的人，常常可以省略「的」。"},"ex":[{"c":"這是我的書。","s":"这是我的书。","es":"Este es mi libro.","en":"This is my book."},{"c":"我媽媽很忙。","s":"我妈妈很忙。","es":"Mi mamá está ocupada.","en":"My mom is very busy."}]},{"id":"1-2-1","b":1,"l":2,"k":"","t":{"es":"Modificador + 的","en":"Modifier Marker 的 de","ens":"Modifier Marker 的 de","tc":"修飾名詞的「的」","sc":"修饰名词的「的」"},"d":{"es":"的 une un modificador (adjetivo o frase) con el sustantivo que describe. El modificador siempre va delante del sustantivo.","en":"的 links a modifier (an adjective or a phrase) to the noun it describes. The modifier always comes before the noun.","tc":"「的」連接修飾語（形容詞或一段話）和它說明的名詞。修飾語一定放在名詞前面。","sc":"「的」连接修饰语（形容词或一段话）和它说明的名词。修饰语一定放在名词前面。"},"ex":[{"c":"她是一個很好的老師。","s":"她是一个很好的老师。","es":"Ella es una muy buena profesora.","en":"She is a very good teacher."}]},{"id":"1-2-2","b":1,"l":2,"k":"","t":{"es":"Tener con 有","en":"有 yǒu possessive","ens":"有 yǒu possessive","tc":"「有」：擁有","sc":"「有」：拥有"},"d":{"es":"有 = tener. Su negación es 沒有 (nunca 不有).","en":"有 means 'to have'. Its negation is 沒有 (never 不有).","tc":"「有」是「擁有」的意思。否定要說「沒有」，不能說「不有」。","sc":"「有」是「拥有」的意思。否定要说「没有」，不能说「不有」。"},"ex":[{"c":"我有兩個姐姐，沒有哥哥。","s":"我有两个姐姐，没有哥哥。","es":"Tengo dos hermanas mayores y ningún hermano mayor.","en":"I have two older sisters and no older brother."}]},{"id":"1-2-3","b":1,"l":2,"k":"","t":{"es":"Todos con 都","en":"都 dōu totality","ens":"都 dōu totality","tc":"「都」：全部","sc":"「都」：全部"},"d":{"es":"都 = todos / ambos. Va antes del verbo y se refiere a lo que aparece antes de él.","en":"都 means 'all' or 'both'. It goes before the verb and refers to what comes before it.","tc":"「都」是「全部」「都是」的意思。放在動詞前面，指的是它前面提到的人或事。","sc":"「都」是「全部」「都是」的意思。放在动词前面，指的是它前面提到的人或事。"},"ex":[{"c":"我們都是學生。","s":"我们都是学生。","es":"Todos somos estudiantes.","en":"We are all students."}]},{"id":"1-2-4","b":1,"l":2,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores 個 y 張","en":"Measures 個 ge and 張 zhāng","ens":"Measures 个 ge and 张 zhāng","tc":"量詞：個、張","sc":"量词：个、张"},"d":{"es":"Estructura: número + clasificador + sustantivo. 個 es el clasificador más general; 張 se usa para cosas planas (papel, mesa, boleto, foto).","en":"Pattern: number + measure word + noun. 個 is the most general measure word; 張 is for flat things (paper, tables, tickets, photos).","tc":"句型是「數字＋量詞＋名詞」。「個」最常用；「張」用在平平的東西，例如紙、桌子、票、照片。","sc":"句型是「数字＋量词＋名词」。「个」最常用；「张」用在平平的东西，例如纸、桌子、票、照片。"},"ex":[{"c":"三個人、一張桌子","s":"三个人、一张桌子","es":"tres personas, una mesa","en":"three people, one table"}]},{"id":"1-3-0","b":1,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Palabras de tiempo","en":"Placement of Time Words","ens":"Placement of Time Words","tc":"時間詞的位置","sc":"时间词的位置"},"d":{"es":"Las palabras de tiempo van antes del verbo (después del sujeto o al inicio de la oración), nunca al final.","en":"Time words go before the verb (after the subject or at the start of the sentence), never at the end.","tc":"時間詞放在動詞前面（主詞後面或句首），不放在句尾。","sc":"时间词放在动词前面（主词后面或句首），不放在句尾。"},"ex":[{"c":"我明天去台北。","s":"我明天去台北。","es":"Mañana voy a Taipéi.","en":"I'm going to Taipei tomorrow."}]},{"id":"1-3-1","b":1,"l":3,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Ir a hacer algo con 去","en":"To Go Do Something with 去 qù","ens":"To Go Do Something with 去 qù","tc":"「去」＋地方＋動作","sc":"「去」＋地方＋动作"},"d":{"es":"去 + lugar + verbo: ir a un lugar para hacer algo.","en":"去 + place + verb means going somewhere to do something.","tc":"「去＋地方＋動詞」表示到某個地方做某件事。","sc":"「去＋地方＋动词」表示到某个地方做某件事。"},"ex":[{"c":"我去圖書館看書。","s":"我去图书馆看书。","es":"Voy a la biblioteca a leer.","en":"I'm going to the library to read."}]},{"id":"1-3-2","b":1,"l":3,"k":"","t":{"es":"Oraciones con tema","en":"Topic Sentences","ens":"Topic Sentences","tc":"主題句","sc":"主题句"},"d":{"es":"Se puede poner primero el tema (algo ya conocido) y luego comentarlo. El objeto pasa al inicio de la oración.","en":"You can start with the topic (something already known) and then comment on it. The object moves to the front of the sentence.","tc":"可以先說出大家已經知道的話題，再說明它。這時受詞會移到句子前面。","sc":"可以先说出大家已经知道的话题，再说明它。这时受词会移到句子前面。"},"ex":[{"c":"中文我會說，日文我不會說。","s":"中文我会说，日文我不会说。","es":"El chino sí sé hablarlo; el japonés no.","en":"Chinese I can speak; Japanese I can't."}]},{"id":"1-3-3","b":1,"l":3,"k":"","t":{"es":"Orden de 也, 都, 常","en":"The Word Order of Adverbs 也 yě,都 dōu and 常 cháng","ens":"The Word Order of Adverbs 也 yě,都 dōu and 常 cháng","tc":"副詞順序：也、都、常","sc":"副词顺序：也、都、常"},"d":{"es":"Los adverbios 也, 都 y 常 van después del sujeto y antes del verbo. Si aparecen 也 y 都 juntos, 也 va primero.","en":"The adverbs 也, 都 and 常 go after the subject and before the verb. When 也 and 都 appear together, 也 comes first.","tc":"「也」「都」「常」放在主詞後面、動詞前面。「也」和「都」一起用時，「也」在前面。","sc":"「也」「都」「常」放在主词后面、动词前面。「也」和「都」一起用时，「也」在前面。"},"ex":[{"c":"我們也都喜歡吃麵。","s":"我们也都喜欢吃面。","es":"A nosotros también nos gusta a todos comer fideos.","en":"We all like eating noodles too."}]},{"id":"1-3-4","b":1,"l":3,"k":"sugerencia proposición suggestion 建議 sugerencia proposición suggestion 建议","t":{"es":"Sugerencias con 吧","en":"Making Suggestions 吧 ba","ens":"Making Suggestions 吧 ba","tc":"用「吧」提出建議","sc":"用「吧」提出建议"},"d":{"es":"吧 al final de la oración hace una sugerencia o invitación suave: «vamos a…», «¿qué tal si…?».","en":"Adding 吧 at the end makes a gentle suggestion or invitation: 'let's …', 'how about …?'.","tc":"句尾加「吧」，語氣比較輕，是在提議或邀請：「我們……吧」。","sc":"句尾加「吧」，语气比较轻，是在提议或邀请：「我们……吧」。"},"ex":[{"c":"我們去吃飯吧。","s":"我们去吃饭吧。","es":"Vamos a comer.","en":"Let's go eat."}]},{"id":"1-4-0","b":1,"l":4,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores 塊, 杯, 支, 種","en":"Measures 塊 kuài, 杯 bēi,支 zhī and 種 zhǒng","ens":"Measures 块 kuài, 杯 bēi,支 zhī and 种 zhǒng","tc":"量詞：塊、杯、支、種","sc":"量词：块、杯、支、种"},"d":{"es":"塊 para dinero; 杯 para bebidas en vaso o taza; 支 para objetos largos y delgados (lápiz, bolígrafo); 種 = tipo, clase.","en":"塊 is for money; 杯 for drinks in a cup or glass; 支 for long, thin objects (pens, pencils); 種 means 'kind, type'.","tc":"「塊」用在錢；「杯」用在杯子裝的飲料；「支」用在細長的東西（筆）；「種」是「種類」。","sc":"「块」用在钱；「杯」用在杯子装的饮料；「支」用在细长的东西（笔）；「种」是「种类」。"},"ex":[{"c":"一杯咖啡、兩支筆、三種水果、五十塊","s":"一杯咖啡、两支笔、三种水果、五十块","es":"una taza de café, dos bolígrafos, tres tipos de fruta, cincuenta dólares","en":"a cup of coffee, two pens, three kinds of fruit, fifty dollars"}]},{"id":"1-4-1","b":1,"l":4,"k":"","t":{"es":"Hacer algo por alguien: 幫","en":"Preposition 幫 bāng on behalf of","ens":"Preposition 帮 bāng on behalf of","tc":"「幫」：替別人做","sc":"「帮」：替别人做"},"d":{"es":"幫 + persona + verbo = hacer algo por alguien / en su lugar.","en":"幫 + person + verb means doing something for someone.","tc":"「幫＋人＋動詞」表示替某人做某件事。","sc":"「帮＋人＋动词」表示替某人做某件事。"},"ex":[{"c":"我幫你買咖啡。","s":"我帮你买咖啡。","es":"Te compro el café.","en":"I'll buy you a coffee."}]},{"id":"1-4-2","b":1,"l":4,"k":"","t":{"es":"Omitir el sustantivo: …的","en":"的 De-phrase with the Head Noun Omitted","ens":"的 De-phrase with the Head Noun Omitted","tc":"省略名詞的「的」","sc":"省略名词的「的」"},"d":{"es":"Cuando ya se sabe de qué sustantivo se habla, se omite y queda «modificador + 的»: «el/la/los de…».","en":"When it's clear what noun is meant, you can drop it and keep 'modifier + 的': 'the one that is …'.","tc":"已經知道在說什麼東西時，可以把名詞省略，只留下「修飾語＋的」，意思是「……的那個」。","sc":"已经知道在说什么东西时，可以把名词省略，只留下「修饰语＋的」，意思是「……的那个」。"},"ex":[{"c":"這杯是我的。","s":"这杯是我的。","es":"Esta taza es la mía.","en":"This cup is mine."},{"c":"紅色的比較貴。","s":"红色的比较贵。","es":"El rojo es más caro.","en":"The red one is more expensive."}]},{"id":"1-4-3","b":1,"l":4,"k":"","t":{"es":"Demasiado: 太…了","en":"太…了 tài…le overly","ens":"太…了 tài…le overly","tc":"太……了","sc":"太……了"},"d":{"es":"太 + adjetivo + 了 = demasiado… (a veces solo exclamación: «¡qué… !»).","en":"太 + adjective + 了 means 'too …' (sometimes just an exclamation: 'so …!').","tc":"「太＋形容詞＋了」是「太……了」，有時只是感嘆，意思是「真是……啊」。","sc":"「太＋形容词＋了」是「太……了」，有时只是感叹，意思是「真是……啊」。"},"ex":[{"c":"這個太貴了！","s":"这个太贵了！","es":"¡Esto es demasiado caro!","en":"This is too expensive!"}]},{"id":"1-4-4","b":1,"l":4,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Poder con 能","en":"能 néng capability","ens":"能 néng capability","tc":"「能」：可以、有能力","sc":"「能」：可以、有能力"},"d":{"es":"能 expresa capacidad o posibilidad: «puedo», «es posible». Negación: 不能.","en":"能 expresses ability or possibility ('can'). The negative is 不能.","tc":"「能」表示有能力或有可能做某件事。否定是「不能」。","sc":"「能」表示有能力或有可能做某件事。否定是「不能」。"},"ex":[{"c":"你明天能來嗎？","s":"你明天能来吗？","es":"¿Puedes venir mañana?","en":"Can you come tomorrow?"}]},{"id":"1-4-5","b":1,"l":4,"k":"","t":{"es":"Y pico: 多","en":"多 duō …and more","ens":"多 duō …and more","tc":"數字後面的「多」","sc":"数字后面的「多」"},"d":{"es":"Después de un número, 多 significa «y pico, más de». También se usa en preguntas de grado: 多大, 多高, 多久.","en":"After a number, 多 means 'more than'. It is also used in degree questions: 多大, 多高, 多久.","tc":"數字後面加「多」，意思是「超過」。也用在問程度的問句：多大、多高、多久。","sc":"数字后面加「多」，意思是「超过」。也用在问程度的问句：多大、多高、多久。"},"ex":[{"c":"我有三十多本書。","s":"我有三十多本书。","es":"Tengo más de treinta libros.","en":"I have more than thirty books."}]},{"id":"1-5-0","b":1,"l":5,"k":"","t":{"es":"Un poco: 有一點","en":"有一點 yǒu yìdiǎn slightly","ens":"有一点 yǒu yìdiǎn slightly","tc":"有一點","sc":"有一点"},"d":{"es":"有一點 + adjetivo = un poco, algo. Suele expresar algo que no es del todo agradable.","en":"有一點 + adjective means 'a little, somewhat', usually about something not quite pleasant.","tc":"「有一點＋形容詞」是「有點……」，通常表示不太滿意的感覺。","sc":"「有一点＋形容词」是「有点……」，通常表示不太满意的感觉。"},"ex":[{"c":"今天有一點冷。","s":"今天有一点冷。","es":"Hoy hace un poco de frío.","en":"It's a little cold today."}]},{"id":"1-5-1","b":1,"l":5,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Verbo + 得 + adjetivo","en":"Complement Marker 得 de","ens":"Complement Marker 得 de","tc":"程度補語「得」","sc":"程度补语「得」"},"d":{"es":"Verbo + 得 + adjetivo describe cómo se hace la acción. Si hay objeto, se repite el verbo.","en":"Verb + 得 + adjective describes how an action is done. If there is an object, the verb is repeated.","tc":"「動詞＋得＋形容詞」說明動作做得怎麼樣。如果有受詞，要先重複一次動詞。","sc":"「动词＋得＋形容词」说明动作做得怎么样。如果有受词，要先重复一次动词。"},"ex":[{"c":"他跑得很快。","s":"他跑得很快。","es":"Corre muy rápido.","en":"He runs very fast."},{"c":"他說中文說得很好。","s":"他说中文说得很好。","es":"Habla muy bien el chino.","en":"He speaks Chinese very well."}]},{"id":"1-5-2","b":1,"l":5,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Saber hacer: 會","en":"Acquired Skills 會 huì","ens":"Acquired Skills 会 huì","tc":"「會」：學會的能力","sc":"「会」：学会的能力"},"d":{"es":"會 = saber hacer algo (habilidad aprendida). Negación: 不會.","en":"會 means knowing how to do something (a learned skill). The negative is 不會.","tc":"「會」表示學過、懂得怎麼做。否定是「不會」。","sc":"「会」表示学过、懂得怎么做。否定是「不会」。"},"ex":[{"c":"我會說中文。","s":"我会说中文。","es":"Sé hablar chino.","en":"I can speak Chinese."}]},{"id":"1-5-3","b":1,"l":5,"k":"","t":{"es":"Destino con 到","en":"Destination Marker 到 dào","ens":"Destination Marker 到 dào","tc":"「到」：到達的地方","sc":"「到」：到达的地方"},"d":{"es":"Verbo de movimiento + 到 + lugar: llegar hasta / ir hasta. 到 marca el destino.","en":"Movement verb + 到 + place means reaching or going as far as a place; 到 marks the destination.","tc":"「移動動詞＋到＋地方」表示去到、走到某個地方，「到」標示目的地。","sc":"「移动动词＋到＋地方」表示去到、走到某个地方，「到」标示目的地。"},"ex":[{"c":"他們開車到高雄。","s":"他们开车到高雄。","es":"Ellos van en coche hasta Kaohsiung.","en":"They drive to Kaohsiung."}]},{"id":"1-6-0","b":1,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Ubicación con 在","en":"Locative Marker 在 zài","ens":"Locative Marker 在 zài","tc":"「在」：在哪裡","sc":"「在」：在哪里"},"d":{"es":"Sujeto + 在 + lugar indica dónde está algo o alguien (algo que ya se conoce).","en":"Subject + 在 + place tells where someone or something is (something already known).","tc":"「主詞＋在＋地方」說明某人或某物在哪裡（說的是已經知道的人或東西）。","sc":"「主词＋在＋地方」说明某人或某物在哪里（说的是已经知道的人或东西）。"},"ex":[{"c":"我的手機在桌子上。","s":"我的手机在桌子上。","es":"Mi celular está sobre la mesa.","en":"My phone is on the table."}]},{"id":"1-6-1","b":1,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Hay: lugar + 有","en":"Existential Sentence with 有 yǒu","ens":"Existential Sentence with 有 yǒu","tc":"「有」：存在句","sc":"「有」：存在句"},"d":{"es":"Lugar + 有 + cosa/persona = en ese lugar hay algo. Contraste: 在 (algo conocido está en…) vs. 有 (en un lugar hay algo).","en":"Place + 有 + thing/person means 'there is …' in that place. Contrast: 在 (a known thing is at …) vs. 有 (a place has …).","tc":"「地方＋有＋東西／人」表示那裡有什麼。比較：「在」是已知的東西在哪裡；「有」是某個地方有什麼。","sc":"「地方＋有＋东西／人」表示那里有什么。比较：「在」是已知的东西在哪里；「有」是某个地方有什么。"},"ex":[{"c":"桌子上有一本書。","s":"桌子上有一本书。","es":"Sobre la mesa hay un libro.","en":"There is a book on the table."}]},{"id":"1-6-2","b":1,"l":6,"k":"","t":{"es":"Suavizar: V(一)V","en":"Softened Action V（一）V","ens":"Softened Action V（一）V","tc":"動詞重複：V(一)V","sc":"动词重复：V(一)V"},"d":{"es":"Repetir el verbo (V一V / VV) suaviza la acción: «un poquito», «probar». Se usa con acciones cortas.","en":"Repeating the verb (V一V / VV) softens the action: 'a little', 'give it a try'. It is used with short actions.","tc":"動詞重複（V一V、VV）讓語氣變輕，意思是「稍微做一下」「試試看」，多用在短短的動作。","sc":"动词重复（V一V、VV）让语气变轻，意思是「稍微做一下」「试试看」，多用在短短的动作。"},"ex":[{"c":"你看(一)看。","s":"你看(一)看。","es":"Echa un vistazo.","en":"Take a look."},{"c":"讓我想一想。","s":"让我想一想。","es":"Déjame pensarlo un momento.","en":"Let me think about it for a moment."}]},{"id":"1-6-3","b":1,"l":6,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Negar con 不是","en":"不是 búshì Negation","ens":"不是 búshì Negation","tc":"「不是」：否定名詞","sc":"「不是」：否定名词"},"d":{"es":"不是 niega 是 y sirve para corregir: «no es X (sino Y)». Se usa para negar sustantivos.","en":"不是 negates 是 and is used to correct: 'it's not X, it's Y'. It negates nouns.","tc":"「不是」否定「是」，也用來更正：「不是 X，是 Y」。用來否定名詞。","sc":"「不是」否定「是」，也用来更正：「不是 X，是 Y」。用来否定名词。"},"ex":[{"c":"我不是老師，我是學生。","s":"我不是老师，我是学生。","es":"No soy profesor, soy estudiante.","en":"I'm not a teacher, I'm a student."}]},{"id":"1-6-4","b":1,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Lugar de la actividad","en":"Location of an Activity","ens":"Location of an Activity","tc":"動作發生的地點","sc":"动作发生的地点"},"d":{"es":"El lugar donde ocurre la actividad va con 在 antes del verbo: 在 + lugar + verbo.","en":"The place where an activity happens is marked with 在 + place, before the verb.","tc":"動作發生的地點用「在＋地方」，放在動詞前面。","sc":"动作发生的地点用「在＋地方」，放在动词前面。"},"ex":[{"c":"我在家看書。","s":"我在家看书。","es":"Leo en casa.","en":"I read at home."}]},{"id":"1-7-0","b":1,"l":7,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Tiempo y lugar","en":"Time and Place of Events","ens":"Time and Place of Events","tc":"時間和地點的順序","sc":"时间和地点的顺序"},"d":{"es":"Orden básico: sujeto + tiempo + lugar + verbo.","en":"Basic order: subject + time + place + verb.","tc":"基本順序是：主詞＋時間＋地點＋動詞。","sc":"基本顺序是：主词＋时间＋地点＋动词。"},"ex":[{"c":"我昨天在家看電影。","s":"我昨天在家看电影。","es":"Ayer vi una película en casa.","en":"I watched a movie at home yesterday."}]},{"id":"1-7-1","b":1,"l":7,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"De A a B: 從…到…","en":"從 cóng…到 dào… from A to B","ens":"从 cóng…到 dào… from A to B","tc":"從……到……","sc":"从……到……"},"d":{"es":"從 A 到 B = de A a B (para lugares o tiempos).","en":"從 A 到 B means 'from A to B', for places or times.","tc":"「從 A 到 B」表示從 A 到 B，可以用在地點或時間。","sc":"「从 A 到 B」表示从 A 到 B，可以用在地点或时间。"},"ex":[{"c":"從台北到高雄","s":"从台北到高雄","es":"de Taipéi a Kaohsiung","en":"from Taipei to Kaohsiung"},{"c":"我從九點到十二點上課。","s":"我从九点到十二点上课。","es":"Tengo clase de nueve a doce.","en":"I have class from nine to twelve."}]},{"id":"1-7-2","b":1,"l":7,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Acción en curso: 在","en":"Progressive, On-going Actions 在 zài","ens":"Progressive, On-going Actions 在 zài","tc":"正在做：在","sc":"正在做：在"},"d":{"es":"(正)在 + verbo = estar haciendo algo (acción en curso). Puede terminar con 呢.","en":"(正)在 + verb shows an action in progress ('be doing'). 呢 can be added at the end.","tc":"「(正)在＋動詞」表示動作正在進行。句尾可以加「呢」。","sc":"「(正)在＋动词」表示动作正在进行。句尾可以加「呢」。"},"ex":[{"c":"我在吃飯。","s":"我在吃饭。","es":"Estoy comiendo.","en":"I'm eating."}]},{"id":"1-7-3","b":1,"l":7,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Cada: 每","en":"每 měi each and every","ens":"每 měi each and every","tc":"「每」：每一個","sc":"「每」：每一个"},"d":{"es":"每 + clasificador / palabra de tiempo = cada, todos los. Suele ir con 都 antes del verbo.","en":"每 + measure word/time word means 'every, each'. It often goes with 都 before the verb.","tc":"「每＋量詞／時間詞」是「每一……」。常常和「都」一起放在動詞前面。","sc":"「每＋量词／时间词」是「每一……」。常常和「都」一起放在动词前面。"},"ex":[{"c":"我每天都喝咖啡。","s":"我每天都喝咖啡。","es":"Tomo café todos los días.","en":"I drink coffee every day."}]},{"id":"1-7-4","b":1,"l":7,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Permiso con 可以","en":"可以 kěyǐ permission","ens":"可以 kěyǐ permission","tc":"「可以」：許可","sc":"「可以」：许可"},"d":{"es":"可以 = permiso: «se puede / puedo». Para pedir permiso: 可以…嗎？ Prohibición: 不可以.","en":"可以 expresses permission ('may, can'). To ask for permission: 可以…嗎？ Prohibition: 不可以.","tc":"「可以」表示可以做某事（許可）。問許可：「可以……嗎？」。不可以：「不可以」。","sc":"「可以」表示可以做某事（许可）。问许可：「可以……吗？」。不可以：「不可以」。"},"ex":[{"c":"這裡可以拍照嗎？","s":"这里可以拍照吗？","es":"¿Se pueden tomar fotos aquí?","en":"Can we take photos here?"}]},{"id":"1-8-0","b":1,"l":8,"k":"","t":{"es":"Compañía con 跟","en":"Companionship with 跟 gēn","ens":"Companionship with 跟 gēn","tc":"「跟」：一起做","sc":"「跟」：一起做"},"d":{"es":"A 跟 B 一起 + verbo = hacer algo con B.","en":"A 跟 B 一起 + verb means doing something together with B.","tc":"「A 跟 B 一起＋動詞」表示和 B 一起做某件事。","sc":"「A 跟 B 一起＋动词」表示和 B 一起做某件事。"},"ex":[{"c":"我跟朋友一起去看電影。","s":"我跟朋友一起去看电影。","es":"Voy al cine con mis amigos.","en":"I go to the movies with my friends."}]},{"id":"1-8-1","b":1,"l":8,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Cómo con 怎麼","en":"Asking How with 怎麼 zěnme","ens":"Asking How with 怎么 zěnme","tc":"「怎麼」：怎樣做","sc":"「怎么」：怎样做"},"d":{"es":"怎麼 + verbo pregunta por la manera o el método de hacer algo.","en":"怎麼 + verb asks how to do something (the method).","tc":"「怎麼＋動詞」問做某件事的方法或方式。","sc":"「怎么＋动词」问做某件事的方法或方式。"},"ex":[{"c":"這個字怎麼念？","s":"这个字怎么念？","es":"¿Cómo se pronuncia este carácter?","en":"How do you pronounce this character?"},{"c":"去台北車站怎麼走？","s":"去台北车站怎么走？","es":"¿Cómo se va a la estación de Taipéi?","en":"How do I get to Taipei Main Station?"}]},{"id":"1-8-2","b":1,"l":8,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Comparación con 比較","en":"Implicit Comparison with 比較 bǐjiào","ens":"Implicit Comparison with 比较 bǐjiào","tc":"「比較」：比較級","sc":"「比较」：比较级"},"d":{"es":"比較 + adjetivo/verbo = «más» o «relativamente»; es una comparación implícita, sin decir con qué se compara.","en":"比較 + adjective/verb means 'more …' or 'relatively …'. It is an implicit comparison; you don't say what it's compared to.","tc":"「比較＋形容詞／動詞」是「比較……」，不用說出跟誰比，是隱含的比較。","sc":"「比较＋形容词／动词」是「比较……」，不用说出跟谁比，是隐含的比较。"},"ex":[{"c":"我比較喜歡喝茶。","s":"我比较喜欢喝茶。","es":"Prefiero tomar té.","en":"I prefer drinking tea."}]},{"id":"1-8-3","b":1,"l":8,"k":"","t":{"es":"Ambas cualidades: 又…又…","en":"又 yòu…又 yòu…… both A and B","ens":"又 yòu…又 yòu…… both A and B","tc":"又……又……","sc":"又……又……"},"d":{"es":"又 A 又 B = a la vez A y B (dos cualidades juntas).","en":"又 A 又 B means both A and B at the same time (two qualities together).","tc":"「又 A 又 B」表示同時有 A 和 B 兩個特點。","sc":"「又 A 又 B」表示同时有 A 和 B 两个特点。"},"ex":[{"c":"這家的菜又好吃又便宜。","s":"这家的菜又好吃又便宜。","es":"La comida de este lugar es rica y barata.","en":"The food at this place is both tasty and cheap."}]},{"id":"1-8-4","b":1,"l":8,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Comparar con 比","en":"Comparison with 比 bǐ","ens":"Comparison with 比 bǐ","tc":"比較句：A 比 B","sc":"比较句：A 比 B"},"d":{"es":"A 比 B + adjetivo = A es más… que B. Con 比 no se usa 很. Para indicar la diferencia: 一點 / 多了 / 三歲, etc.","en":"A 比 B + adjective means A is more … than B. Don't use 很 with 比. To say how much the difference is, add 一點 / 多了 / an amount.","tc":"「A 比 B＋形容詞」表示 A 比 B 更……。用「比」的時候不加「很」。要說差多少，可以加「一點」「多了」或數量。","sc":"「A 比 B＋形容词」表示 A 比 B 更……。用「比」的时候不加「很」。要说差多少，可以加「一点」「多了」或数量。"},"ex":[{"c":"哥哥比我高。","s":"哥哥比我高。","es":"Mi hermano mayor es más alto que yo.","en":"My older brother is taller than I am."},{"c":"他比我大三歲。","s":"他比我大三岁。","es":"Es tres años mayor que yo.","en":"He is three years older than I am."}]},{"id":"1-9-0","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Momento vs. duración","en":"Time-When vs. Time-Duration","ens":"Time-When vs. Time-Duration","tc":"時間點和時間長度","sc":"时间点和时间长度"},"d":{"es":"El momento (cuándo) va antes del verbo; la duración (cuánto tiempo) va después del verbo.","en":"When something happens (a point in time) goes before the verb; how long it lasts (duration) goes after the verb.","tc":"「什麼時候」（時間點）放在動詞前面；「多久」（時間長度）放在動詞後面。","sc":"「什么时候」（时间点）放在动词前面；「多久」（时间长度）放在动词后面。"},"ex":[{"c":"我八點上課。","s":"我八点上课。","es":"Tengo clase a las ocho.","en":"I have class at eight."},{"c":"我每天睡八個小時。","s":"我每天睡八个小时。","es":"Duermo ocho horas al día.","en":"I sleep eight hours a day."}]},{"id":"1-9-1","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Duración de la acción","en":"Time-Duration ‘for a period of time’","ens":"Time-Duration ‘for a period of time’","tc":"動作持續的時間","sc":"动作持续的时间"},"d":{"es":"Verbo + duración (+ 的 + objeto) indica cuánto tiempo dura la acción.","en":"Verb + duration (+ 的 + object) tells how long the action lasts.","tc":"「動詞＋時間長度（＋的＋受詞）」表示動作持續多久。","sc":"「动词＋时间长度（＋的＋受词）」表示动作持续多久。"},"ex":[{"c":"我想在台灣住三個月。","s":"我想在台湾住三个月。","es":"Quiero vivir tres meses en Taiwán.","en":"I'd like to live in Taiwan for three months."}]},{"id":"1-9-2","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando: …的時候","en":"…的時候 de shíhòu when","ens":"…的时候 de shíhòu when","tc":"「……的時候」","sc":"「……的时候」"},"d":{"es":"Frase + 的時候 = cuando… (en el momento en que ocurre algo).","en":"Clause + 的時候 means 'when …' (at the time the action happens).","tc":"「一段話＋的時候」表示「當……的時候」，說明動作發生的那段時間。","sc":"「一段话＋的时候」表示「当……的时候」，说明动作发生的那段时间。"},"ex":[{"c":"我吃飯的時候不看手機。","s":"我吃饭的时候不看手机。","es":"Cuando como no miro el celular.","en":"I don't look at my phone when I eat."}]},{"id":"1-9-3","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"A veces… a veces…","en":"有時候 yǒu shíhòu…有時候 yǒu shíhòu… sometimes … sometimes …","ens":"有时候 yǒu shíhòu…有时候 yǒu shíhòu… sometimes … sometimes …","tc":"有時候……有時候……","sc":"有时候……有时候……"},"d":{"es":"有時候 A，有時候 B = a veces A, a veces B.","en":"有時候 A，有時候 B means 'sometimes A, sometimes B'.","tc":"「有時候 A，有時候 B」表示有時候做 A，有時候做 B。","sc":"「有时候 A，有时候 B」表示有时候做 A，有时候做 B。"},"ex":[{"c":"我有時候喝茶，有時候喝咖啡。","s":"我有时候喝茶，有时候喝咖啡。","es":"A veces tomo té y a veces café.","en":"Sometimes I drink tea and sometimes coffee."}]},{"id":"1-9-4","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Si…, entonces: 要是…就","en":"Condition and Consequence with 要是 yaoshi…就 jiu…","ens":"Condition and Consequence with 要是 yaoshi…就 jiu…","tc":"要是……就……","sc":"要是……就……"},"d":{"es":"要是 + condición，就 + resultado = si…, entonces…. 就 va antes del verbo.","en":"要是 + condition, 就 + result means 'if …, then …'. 就 goes before the verb.","tc":"「要是＋條件，就＋結果」表示「如果……就……」。「就」放在動詞前面。","sc":"「要是＋条件，就＋结果」表示「如果……就……」。「就」放在动词前面。"},"ex":[{"c":"要是下雨，我就不去。","s":"要是下雨，我就不去。","es":"Si llueve, no voy.","en":"If it rains, I won't go."}]},{"id":"1-10-0","b":1,"l":10,"k":"","t":{"es":"Probar: V V 看","en":"V V 看 kàn to try and see","ens":"V V 看 kàn to try and see","tc":"動詞重複＋「看」","sc":"动词重复＋「看」"},"d":{"es":"Verbo repetido + 看 = probar a hacer algo para ver qué tal.","en":"Repeated verb + 看 means 'try doing it and see how it goes'.","tc":"「動詞重複＋看」表示試試看，看看會怎麼樣。","sc":"「动词重复＋看」表示试试看，看看会怎么样。"},"ex":[{"c":"這個很好吃，你吃吃看。","s":"这个很好吃，你吃吃看。","es":"Esto está muy rico, pruébalo.","en":"This is very tasty, try it."}]},{"id":"1-10-1","b":1,"l":10,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Adjetivos duplicados","en":"Intensification with Reduplicated State Verbs","ens":"Intensification with Reduplicated State Verbs","tc":"形容詞重疊","sc":"形容词重叠"},"d":{"es":"Duplicar un adjetivo (AA) lo hace más vívido; ya no se le pone 很. Para adjetivos de dos sílabas se usa AABB.","en":"Doubling an adjective (AA) makes it more vivid and no 很 is added. Two-syllable adjectives are doubled as AABB.","tc":"形容詞重疊（AA）會更生動，不再加「很」。兩個字的形容詞要重疊成 AABB。","sc":"形容词重叠（AA）会更生动，不再加「很」。两个字的形容词要重叠成 AABB。"},"ex":[{"c":"她的眼睛大大的。","s":"她的眼睛大大的。","es":"Tiene los ojos bien grandes.","en":"Her eyes are big and round."}]},{"id":"1-10-2","b":1,"l":10,"k":"","t":{"es":"Oración como modificador","en":"Clause as Modifiers of Nouns","ens":"Clause as Modifiers of Nouns","tc":"用一句話修飾名詞","sc":"用一句话修饰名词"},"d":{"es":"Una frase u oración + 的 + sustantivo: la descripción siempre va antes del sustantivo (como una cláusula de relativo).","en":"Clause + 的 + noun: the description always comes before the noun (like a relative clause).","tc":"「一句話＋的＋名詞」，說明的話一定放在名詞前面（像關係子句）。","sc":"「一句话＋的＋名词」，说明的话一定放在名词前面（像关系子句）。"},"ex":[{"c":"我喜歡的老師很年輕。","s":"我喜欢的老师很年轻。","es":"El profesor que me gusta es muy joven.","en":"The teacher I like is very young."}]},{"id":"1-10-3","b":1,"l":10,"k":"","t":{"es":"Cambio con 了","en":"Change in Situation with Sentential 了 le","ens":"Change in Situation with Sentential 了 le","tc":"句尾「了」：新的狀況","sc":"句尾「了」：新的状况"},"d":{"es":"了 al final de la oración indica un cambio de situación o un estado nuevo: «ya», «ahora ya».","en":"了 at the end of a sentence shows a change of situation or a new state: 'now …', 'already …'.","tc":"句尾的「了」表示情況改變、出現新的狀態：「已經……了」「現在……了」。","sc":"句尾的「了」表示情况改变、出现新的状态：「已经……了」「现在……了」。"},"ex":[{"c":"我現在不累了。","s":"我现在不累了。","es":"Ya no estoy cansado.","en":"I'm not tired anymore."},{"c":"天黑了。","s":"天黑了。","es":"Ya oscureció.","en":"It's gotten dark."}]},{"id":"1-10-4","b":1,"l":10,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Causa y efecto","en":"Cause and Effect with 因為 yīnwèi，所以 suǒyǐ","ens":"Cause and Effect with 因为 yīnwèi，所以 suǒyǐ","tc":"因為……所以……","sc":"因为……所以……"},"d":{"es":"因為 introduce la causa y 所以 el resultado. En chino se suelen usar juntos.","en":"因為 gives the reason and 所以 the result. In Chinese the two are often used together.","tc":"「因為」說原因，「所以」說結果。中文常常兩個一起用。","sc":"「因为」说原因，「所以」说结果。中文常常两个一起用。"},"ex":[{"c":"因為下雨，所以我不去。","s":"因为下雨，所以我不去。","es":"Como llueve, no voy.","en":"Because it's raining, I'm not going."}]},{"id":"1-11-0","b":1,"l":11,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Venir a hacer: 來","en":"To Come to Do Something with 來 lái","ens":"To Come to Do Something with 来 lái","tc":"「來」＋動作","sc":"「来」＋动作"},"d":{"es":"來 + verbo = venir a hacer algo (desde el punto de vista del lugar donde se habla).","en":"來 + verb means coming (to where the speaker is) to do something.","tc":"「來＋動詞」表示來到說話的人所在的地方做某件事。","sc":"「来＋动词」表示来到说话的人所在的地方做某件事。"},"ex":[{"c":"他來台灣學中文。","s":"他来台湾学中文。","es":"Él viene a Taiwán a estudiar chino.","en":"He comes to Taiwan to study Chinese."}]},{"id":"1-11-1","b":1,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Más pronto: 就","en":"Sooner Than Expected with 就 jiù","ens":"Sooner Than Expected with 就 jiù","tc":"「就」：比預期早","sc":"「就」：比预期早"},"d":{"es":"Tiempo + 就 + verbo = la acción ocurre más temprano o más rápido de lo esperado.","en":"Time + 就 + verb shows the action happens earlier or sooner than expected.","tc":"「時間＋就＋動詞」表示動作比預期更早或更快發生。","sc":"「时间＋就＋动词」表示动作比预期更早或更快发生。"},"ex":[{"c":"我六點就起床了。","s":"我六点就起床了。","es":"Me levanté ya a las seis.","en":"I was already up at six."}]},{"id":"1-11-2","b":1,"l":11,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Hay alguien que…","en":"Existential Subject with 有 yǒu","ens":"Existential Subject with 有 yǒu","tc":"「有」＋不確定的主詞","sc":"「有」＋不确定的主词"},"d":{"es":"有 + sujeto indefinido al inicio: «hay alguien/algo que…».","en":"Starting a sentence with 有 + an indefinite subject means 'there is someone/something that …'.","tc":"句首用「有＋不確定的人或東西」，意思是「有人／有東西……」。","sc":"句首用「有＋不确定的人或东西」，意思是「有人／有东西……」。"},"ex":[{"c":"有人找你。","s":"有人找你。","es":"Alguien te busca.","en":"Someone is looking for you."}]},{"id":"1-11-3","b":1,"l":11,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Usos de 會","en":"Different Types of 會 huì","ens":"Different Types of 会 huì","tc":"「會」的不同用法","sc":"「会」的不同用法"},"d":{"es":"會 también expresa probabilidad o futuro: «seguramente», «va a». No solo significa «saber hacer».","en":"Besides 'knowing how to', 會 also expresses probability or the future: 'will, is likely to'.","tc":"「會」除了「學會做某事」，也表示可能或將來：「應該會」「一定會」。","sc":"「会」除了「学会做某事」，也表示可能或将来：「应该会」「一定会」。"},"ex":[{"c":"明天會下雨。","s":"明天会下雨。","es":"Mañana va a llover.","en":"It will rain tomorrow."},{"c":"他會來嗎？","s":"他会来吗？","es":"¿Vendrá él?","en":"Will he come?"}]},{"id":"1-11-4","b":1,"l":11,"k":"","t":{"es":"Omitir sustantivos","en":"Omitting Nouns at 2nd mention","ens":"Omitting Nouns at 2nd mention","tc":"第二次提到時省略名詞","sc":"第二次提到时省略名词"},"d":{"es":"Cuando el sustantivo ya se mencionó, la segunda vez se puede omitir.","en":"A noun that has already been mentioned can be omitted the second time.","tc":"已經提過的名詞，第二次說的時候可以省略。","sc":"已经提过的名词，第二次说的时候可以省略。"},"ex":[{"c":"這件太大了，有小的嗎？","s":"这件太大了，有小的吗？","es":"Esta es demasiado grande, ¿tiene una más pequeña?","en":"This one is too big. Do you have a smaller one?"}]},{"id":"1-12-0","b":1,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Primero… luego: 先…再…","en":"先 xiān…再 zài… first…, and then …","ens":"先 xiān…再 zài… first…, and then …","tc":"先……再……","sc":"先……再……"},"d":{"es":"先 A，再 B = primero A, luego B.","en":"先 A，再 B means 'first A, then B'.","tc":"「先 A，再 B」表示先做 A，然後做 B。","sc":"「先 A，再 B」表示先做 A，然后做 B。"},"ex":[{"c":"我們先吃飯，再看電影。","s":"我们先吃饭，再看电影。","es":"Primero comemos y luego vemos una película.","en":"Let's eat first and then watch a movie."}]},{"id":"1-12-1","b":1,"l":12,"k":"","t":{"es":"Enfatizar con 是…的","en":"To Focus with 是 shì…的 de…","ens":"To Focus with 是 shì…的 de…","tc":"是……的","sc":"是……的"},"d":{"es":"是…的 destaca el cuándo, dónde, cómo o con quién de una acción que ya ocurrió.","en":"是…的 emphasizes the time, place, manner or companion of an action that has already happened.","tc":"「是……的」用來強調已經發生的動作的時間、地點、方式或一起去的人。","sc":"「是……的」用来强调已经发生的动作的时间、地点、方式或一起去的人。"},"ex":[{"c":"我是昨天來的。","s":"我是昨天来的。","es":"Vine ayer.","en":"I came yesterday."},{"c":"我是坐高鐵來的。","s":"我是坐高铁来的。","es":"Vine en el tren de alta velocidad.","en":"I came by high-speed rail."}]},{"id":"1-12-2","b":1,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Después de: 以後","en":"以後 yǐhòu after…","ens":"以后 yǐhòu after…","tc":"「以後」","sc":"「以后」"},"d":{"es":"Tiempo / frase + 以後 = después de…. Solo, 以後 significa «en el futuro».","en":"Time/clause + 以後 means 'after …'. Used alone, 以後 means 'in the future'.","tc":"「時間／一段話＋以後」表示「在……之後」。單獨說「以後」是「未來」。","sc":"「时间／一段话＋以后」表示「在……之后」。单独说「以后」是「未来」。"},"ex":[{"c":"下課以後，我去吃飯。","s":"下课以后，我去吃饭。","es":"Después de clase voy a comer.","en":"After class, I'm going to eat."}]},{"id":"1-12-3","b":1,"l":12,"k":"","t":{"es":"好 / 難 + verbo","en":"Special Meanings of 好 hǎo/難 nán +Verbs","ens":"Special Meanings of 好 hǎo/难 nán +Verbs","tc":"「好／難＋動詞」","sc":"「好／难＋动词」"},"d":{"es":"好 + verbo = fácil / agradable de…: 好吃, 好看, 好用. 難 + verbo = difícil / desagradable de…: 難吃, 難看, 難用.","en":"好 + verb means easy or pleasant to … (好吃, 好看, 好用); 難 + verb means hard or unpleasant to … (難吃, 難看, 難用).","tc":"「好＋動詞」表示容易、好用或令人愉快（好吃、好看、好用）；「難＋動詞」表示不容易或不好（難吃、難看、難用）。","sc":"「好＋动词」表示容易、好用或令人愉快（好吃、好看、好用）；「难＋动词」表示不容易或不好（难吃、难看、难用）。"},"ex":[{"c":"這個手機很好用。","s":"这个手机很好用。","es":"Este celular es muy fácil de usar.","en":"This phone is very easy to use."},{"c":"這道菜很難吃。","s":"这道菜很难吃。","es":"Este platillo sabe mal.","en":"This dish tastes bad."}]},{"id":"1-13-0","b":1,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"En cuanto: 一…就…","en":"一 yī…就 jiù… …as soon as…","ens":"一 yī…就 jiù… …as soon as…","tc":"一……就……","sc":"一……就……"},"d":{"es":"一 A 就 B = en cuanto A, B.","en":"一 A 就 B means 'as soon as A, B'.","tc":"「一 A 就 B」表示一做完 A，馬上就 B。","sc":"「一 A 就 B」表示一做完 A，马上就 B。"},"ex":[{"c":"他一下課就回家。","s":"他一下课就回家。","es":"En cuanto termina la clase, se va a casa.","en":"He goes home as soon as class ends."}]},{"id":"1-13-1","b":1,"l":13,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Acción completada: 了","en":"Completed Action with Verbal 了 le","ens":"Completed Action with Verbal 了 le","tc":"動作完成：「了」","sc":"动作完成：「了」"},"d":{"es":"Verbo + 了 indica que la acción se completó (no equivale a «pasado»). Suele haber una cantidad o complemento después.","en":"Verb + 了 shows the action is completed (it is not simply 'past tense'). It is usually followed by a quantity or other information.","tc":"「動詞＋了」表示動作已經完成，不等於過去式。後面通常有數量或其他補充說明。","sc":"「动词＋了」表示动作已经完成，不等于过去式。后面通常有数量或其他补充说明。"},"ex":[{"c":"我買了一本書。","s":"我买了一本书。","es":"Compré un libro.","en":"I bought a book."}]},{"id":"1-13-2","b":1,"l":13,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"不 vs. 沒","en":"不 Negation vs.沒 Negation","ens":"不 Negation vs.没 Negation","tc":"「不」和「沒」的差別","sc":"「不」和「没」的差别"},"d":{"es":"不 niega hábitos, presente, futuro y voluntad. 沒(有) niega que una acción haya ocurrido, y niega 有. Con 沒 no se usa 了.","en":"不 negates habits, the present, the future and will. 沒(有) negates that an action took place, and negates 有. Don't use 了 with 沒.","tc":"「不」用在習慣、現在、未來和意願；「沒(有)」用在否定過去沒發生的事，也否定「有」。用「沒」的時候不加「了」。","sc":"「不」用在习惯、现在、未来和意愿；「没(有)」用在否定过去没发生的事，也否定「有」。用「没」的时候不加「了」。"},"ex":[{"c":"我不喝咖啡。","s":"我不喝咖啡。","es":"No tomo café.","en":"I don't drink coffee."},{"c":"我昨天沒去學校。","s":"我昨天没去学校。","es":"Ayer no fui a la escuela.","en":"I didn't go to school yesterday."}]},{"id":"1-13-3","b":1,"l":13,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Pregunta + 都: cualquiera","en":"All-inclusive with Question Words","ens":"All-inclusive with Question Words","tc":"疑問詞＋都：全部","sc":"疑问词＋都：全部"},"d":{"es":"Pregunta + 都 / 也: «cualquiera, todo, nadie…». Con negación: 誰都不 / 什麼都沒.","en":"Question word + 都/也 means 'any, every, no one…'. Negative: 誰都不 / 什麼都沒.","tc":"「疑問詞＋都／也」表示「任何……都」。否定用「誰都不」「什麼都沒」。","sc":"「疑问词＋都／也」表示「任何……都」。否定用「谁都不」「什么都没」。"},"ex":[{"c":"誰都知道。","s":"谁都知道。","es":"Todo el mundo lo sabe.","en":"Everyone knows."},{"c":"我什麼都吃。","s":"我什么都吃。","es":"Como de todo.","en":"I eat anything."}]},{"id":"1-13-4","b":1,"l":13,"k":"","t":{"es":"Más / menos de lo planeado","en":"More/less…Than Planned with 多 duō /少 shǎo＋ Verb…","ens":"More/less…Than Planned with 多 duō /少 shǎo＋ Verb…","tc":"多／少＋動詞","sc":"多／少＋动词"},"d":{"es":"多 / 少 + verbo + cantidad = más / menos de lo planeado (acción ya realizada).","en":"多/少 + verb + quantity means more/less than planned (the action has already happened).","tc":"「多／少＋動詞＋數量」表示比原本計畫的更多／更少（動作已經發生）。","sc":"「多／少＋动词＋数量」表示比原本计划的更多／更少（动作已经发生）。"},"ex":[{"c":"我多買了兩個。","s":"我多买了两个。","es":"Compré dos de más.","en":"I bought two extra."}]},{"id":"1-13-5","b":1,"l":13,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 negación negar negativa negation negative 否定 pregunta preguntar interrogativa question ask 疑问 问句 提问 negación negar negativa negation negative 否定","t":{"es":"¿Verdad? con 是不是","en":"是不是 shìbú shì is it true?","ens":"是不是 shìbú shì is it true?","tc":"是不是","sc":"是不是"},"d":{"es":"是不是 sirve para confirmar algo que se supone: «¿verdad que…?». Va antes del verbo o al final de la oración.","en":"是不是 is used to confirm something you assume: 'is it true that …?'. It goes before the verb or at the end.","tc":"「是不是」用來確認自己猜的事：「是不是……？」放在動詞前面或句尾。","sc":"「是不是」用来确认自己猜的事：「是不是……？」放在动词前面或句尾。"},"ex":[{"c":"你是不是累了？","s":"你是不是累了？","es":"¿Estás cansado, verdad?","en":"You're tired, aren't you?"}]},{"id":"1-13-6","b":1,"l":13,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Igual que: 跟…一樣","en":"Comparison with 跟 gēn…一樣 yíyàng","ens":"Comparison with 跟 gēn…一样 yíyàng","tc":"跟……一樣","sc":"跟……一样"},"d":{"es":"A 跟 B 一樣 (+ adjetivo) = A es igual que B.","en":"A 跟 B 一樣 (+ adjective) means A is the same as B.","tc":"「A 跟 B 一樣（＋形容詞）」表示 A 和 B 一樣。","sc":"「A 跟 B 一样（＋形容词）」表示 A 和 B 一样。"},"ex":[{"c":"我的手機跟你的一樣。","s":"我的手机跟你的一样。","es":"Mi celular es igual al tuyo.","en":"My phone is the same as yours."},{"c":"我跟他一樣高。","s":"我跟他一样高。","es":"Soy tan alto como él.","en":"I'm as tall as he is."}]},{"id":"1-14-0","b":1,"l":14,"k":"tiempo momento orden secuencia time order sequence 時間 順序 pasado completado terminado past completed finished perfective 完成 過去 tiempo momento orden secuencia time order sequence 时间 顺序 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Duración tras 了","en":"Time-Duration after Verbal 了 le","ens":"Time-Duration after Verbal 了 le","tc":"「了」後面的時間長度","sc":"「了」后面的时间长度"},"d":{"es":"Verbo + 了 + duración (+ 的 + objeto) = cuánto tiempo duró una acción ya terminada.","en":"Verb + 了 + duration (+ 的 + object) tells how long a finished action lasted.","tc":"「動詞＋了＋時間長度（＋的＋受詞）」表示已經做完的動作持續了多久。","sc":"「动词＋了＋时间长度（＋的＋受词）」表示已经做完的动作持续了多久。"},"ex":[{"c":"我昨天睡了八個小時。","s":"我昨天睡了八个小时。","es":"Ayer dormí ocho horas.","en":"I slept eight hours yesterday."}]},{"id":"1-14-1","b":1,"l":14,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Doble 了: hasta ahora","en":"Completion-to-date with Double 了 le","ens":"Completion-to-date with Double 了 le","tc":"雙「了」：到現在","sc":"双「了」：到现在"},"d":{"es":"Verbo + 了 + cantidad + 了 = la acción lleva esa cantidad hasta ahora y todavía continúa.","en":"Verb + 了 + quantity + 了 means 'up to now' the action has lasted/amounted to that much, and it is still going on.","tc":"「動詞＋了＋數量＋了」表示到現在為止做了這麼久、這麼多，而且還在繼續。","sc":"「动词＋了＋数量＋了」表示到现在为止做了这么久、这么多，而且还在继续。"},"ex":[{"c":"我學中文學了兩年了。","s":"我学中文学了两年了。","es":"Llevo dos años estudiando chino.","en":"I've been studying Chinese for two years."}]},{"id":"1-14-2","b":1,"l":14,"k":"","t":{"es":"Casi: 快…了","en":"快 kuài…了 le about to","ens":"快 kuài…了 le about to","tc":"快……了","sc":"快……了"},"d":{"es":"快 + verbo / adjetivo / hora + 了 = a punto de, ya casi.","en":"快 + verb/adjective/time + 了 means 'about to', 'almost'.","tc":"「快＋動詞／形容詞／時間＋了」表示快要、差不多了。","sc":"「快＋动词／形容词／时间＋了」表示快要、差不多了。"},"ex":[{"c":"快下雨了。","s":"快下雨了。","es":"Ya casi llueve.","en":"It's about to rain."},{"c":"快十二點了。","s":"快十二点了。","es":"Ya casi son las doce.","en":"It's almost twelve o'clock."}]},{"id":"1-14-3","b":1,"l":14,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Aún más: 更","en":"Comparison 更 gèng even more so","ens":"Comparison 更 gèng even more so","tc":"「更」：更加","sc":"「更」：更加"},"d":{"es":"更 + adjetivo = todavía más. Se compara con algo ya mencionado.","en":"更 + adjective means 'even more …'. It compares with something already mentioned.","tc":"「更＋形容詞」是「更加……」，是跟前面提過的事物比較。","sc":"「更＋形容词」是「更加……」，是跟前面提过的事物比较。"},"ex":[{"c":"這家比那家更好吃。","s":"这家比那家更好吃。","es":"Este lugar es todavía más rico que aquel.","en":"This place is even tastier than that one."}]},{"id":"1-14-4","b":1,"l":14,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"No tan…: 沒有","en":"Inferior Comparison 沒有 méiyǒu…","ens":"Inferior Comparison 没有 méiyǒu…","tc":"A 沒有 B（那麼）……","sc":"A 没有 B（那么）……"},"d":{"es":"A 沒有 B (那麼) + adjetivo = A no es tan… como B.","en":"A 沒有 B (那麼) + adjective means A is not as … as B.","tc":"「A 沒有 B（那麼）＋形容詞」表示 A 不如 B。","sc":"「A 没有 B（那么）＋形容词」表示 A 不如 B。"},"ex":[{"c":"我沒有哥哥那麼高。","s":"我没有哥哥那么高。","es":"No soy tan alto como mi hermano.","en":"I'm not as tall as my brother."}]},{"id":"1-15-0","b":1,"l":15,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Postura libre: lo que sea","en":"Non-committal Stance with Question Words","ens":"Non-committal Stance with Question Words","tc":"疑問詞：隨你喜歡","sc":"疑问词：随你喜欢"},"d":{"es":"Con pronombres interrogativos se expresa «lo que quieras»: 什麼…就 + verbo. Es una postura sin compromiso.","en":"Question words can express 'whatever you like': 什麼…就…. It signals no particular restriction.","tc":"用疑問詞可以表示「你想……就……」，是沒有特別限制的說法：什麼……就……。","sc":"用疑问词可以表示「你想……就……」，是没有特别限制的说法：什么……就……。"},"ex":[{"c":"你想喝什麼就點什麼。","s":"你想喝什么就点什么。","es":"Pide lo que quieras beber.","en":"Order whatever you'd like to drink."}]},{"id":"1-15-1","b":1,"l":15,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Disponer con 把","en":"To Dispose of Something with 把 bǎ","ens":"To Dispose of Something with 把 bǎ","tc":"「把」字句","sc":"「把」字句"},"d":{"es":"把 + objeto (ya conocido) + verbo + complemento: se «dispone» del objeto y se dice qué se hace con él. El verbo no puede ir solo.","en":"把 + object (already known) + verb + complement means 'dealing with' the object, saying what is done to it. The verb can't stand alone.","tc":"「把＋受詞（已知的）＋動詞＋補充說明」表示處理某個東西、對它做什麼。動詞後面不能單獨出現。","sc":"「把＋受词（已知的）＋动词＋补充说明」表示处理某个东西、对它做什么。动词后面不能单独出现。"},"ex":[{"c":"請你把窗戶打開。","s":"请你把窗户打开。","es":"Por favor abre la ventana.","en":"Please open the window."}]},{"id":"1-15-2","b":1,"l":15,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Apenas hice… : V了…就…","en":"V 了 le…就 jiù… do…right after doing…","ens":"V 了 le…就 jiù… do…right after doing…","tc":"V 了……就……","sc":"V 了……就……"},"d":{"es":"V 了 A 就 B = en cuanto terminé A, hago B.","en":"V 了 A 就 B means 'right after finishing A, do B'.","tc":"「V 了 A 就 B」表示做完 A 以後，馬上做 B。","sc":"「V 了 A 就 B」表示做完 A 以后，马上做 B。"},"ex":[{"c":"我下了課就回家。","s":"我下了课就回家。","es":"En cuanto termine la clase me voy a casa.","en":"I'll go home right after class."}]},{"id":"1-15-3","b":1,"l":15,"k":"","t":{"es":"Un poco: 一點","en":"一點 yìdiǎn a bit","ens":"一点 yìdiǎn a bit","tc":"「一點」：一些","sc":"「一点」：一些"},"d":{"es":"Adjetivo + 一點 = un poco más (suaviza una petición). Verbo + 一點 = un poco de.","en":"Adjective + 一點 means 'a bit more …' and softens a request. Verb + 一點 means 'a little more'.","tc":"「形容詞＋一點」是「更……一些」，讓請求更客氣。「動詞＋一點」是「做多一些」。","sc":"「形容词＋一点」是「更……一些」，让请求更客气。「动词＋一点」是「做多一些」。"},"ex":[{"c":"這個便宜一點好嗎？","s":"这个便宜一点好吗？","es":"¿Podría ser un poco más barato?","en":"Could it be a little cheaper?"},{"c":"你多吃一點。","s":"你多吃一点。","es":"Come un poco más.","en":"Eat a little more."}]},{"id":"1-15-4","b":1,"l":15,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 complemento resultado potencial complement result potential 補語 結果補語 可能補語 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Comparar acciones con 得","en":"Comparing Actions with a 得 de Complement","ens":"Comparing Actions with a 得 de Complement","tc":"用「得」比較動作","sc":"用「得」比较动作"},"d":{"es":"Para comparar acciones con 得: A + verbo + 得 + 比 B + adjetivo, o A 比 B + verbo + 得 + adjetivo.","en":"To compare actions with 得: A + verb + 得 + 比 B + adjective, or A 比 B + verb + 得 + adjective.","tc":"比較動作時：「A＋動詞＋得＋比 B＋形容詞」，或「A 比 B＋動詞＋得＋形容詞」。","sc":"比较动作时：「A＋动词＋得＋比 B＋形容词」，或「A 比 B＋动词＋得＋形容词」。"},"ex":[{"c":"他比我跑得快。","s":"他比我跑得快。","es":"Corre más rápido que yo.","en":"He runs faster than I do."}]},{"id":"1-15-5","b":1,"l":15,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 complemento resultado potencial complement result potential 補語 結果補語 可能補語 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Grado en comparaciones","en":"Complements of Degree in Comparison Structures","ens":"Complements of Degree in Comparison Structures","tc":"比較句的程度補語","sc":"比较句的程度补语"},"d":{"es":"En la comparación con complemento de grado se puede añadir la diferencia: 一點 (un poco) o 多了 / 得多 (mucho más).","en":"In comparisons with 得 you can add the size of the difference: 一點 (a little) or 多了 / 得多 (much more).","tc":"用「得」比較時，可以再加差別：「一點」（差一些）或「多了／得多」（差很多）。","sc":"用「得」比较时，可以再加差别：「一点」（差一些）或「多了／得多」（差很多）。"},"ex":[{"c":"他說得比我好多了。","s":"他说得比我好多了。","es":"Habla mucho mejor que yo.","en":"He speaks much better than I do."}]},{"id":"1-15-6","b":1,"l":15,"k":"","t":{"es":"Verbos separables","en":"Separable Verbs","ens":"Separable Verbs","tc":"離合詞","sc":"离合词"},"d":{"es":"Los verbos separables (吃飯, 睡覺, 游泳, 見面) son verbo + objeto: se pueden separar y la duración o cantidad va en medio. No llevan otro objeto directo.","en":"Separable verbs (吃飯, 睡覺, 游泳, 見面) are verb + object; other words can go in between, such as a duration or quantity. They cannot take another object.","tc":"離合詞（吃飯、睡覺、游泳、見面）是「動詞＋受詞」，中間可以放別的詞，時間長度或數量放在中間。後面不能再接受詞。","sc":"离合词（吃饭、睡觉、游泳、见面）是「动词＋受词」，中间可以放别的词，时间长度或数量放在中间。后面不能再接受词。"},"ex":[{"c":"我們見了三次面。","s":"我们见了三次面。","es":"Nos vimos tres veces.","en":"We met three times."},{"c":"他游了一個小時的泳。","s":"他游了一个小时的泳。","es":"Nadó una hora.","en":"He swam for an hour."}]},{"id":"2-1-0","b":2,"l":1,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Desde… hacia con 從…往","en":"從 cóng…往 wǎng… go…from…","ens":"从 cóng…往 wǎng… go…from…","tc":"從…往…","sc":"从…往…"},"d":{"es":"從 + lugar + 往 + dirección + verbo: desde… hacia… (se usa mucho para dar indicaciones).","en":"從 + place + 往 + direction + verb means 'from… toward…'. It is often used to give directions.","tc":"「從＋地點＋往＋方向＋動詞」表示從哪裡往哪個方向去，常用來指路。","sc":"「从＋地点＋往＋方向＋动词」表示从哪里往哪个方向去，常用来指路。"},"ex":[{"c":"從這裡往前走，再往右轉。","s":"从这里往前走，再往右转。","es":"Desde aquí sigue derecho y luego gira a la derecha.","en":"From here go straight, then turn right."}]},{"id":"2-1-1","b":2,"l":1,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Juicio con V起來","en":"Judgmental V-起來 qǐlái It’s my assessment that…","ens":"Judgmental V-起来 qǐlái It’s my assessment that…","tc":"V＋起來（看起來、聽起來）","sc":"V＋起来（看起来、听起来）"},"d":{"es":"V + 起來 expresa una evaluación subjetiva: «a juzgar por cómo se ve / se oye / sabe / se siente».","en":"V + 起來 expresses a subjective judgment: 'judging by how it looks / sounds / tastes / feels'.","tc":"「V＋起來」表示說話的人根據看到、聽到、吃到的感覺所做的判斷：從……來看。","sc":"「V＋起来」表示说话的人根据看到、听到、吃到的感觉所做的判断：从……来看。"},"ex":[{"c":"這個菜看起來很好吃。","s":"这个菜看起来很好吃。","es":"Este platillo se ve muy rico.","en":"This dish looks delicious."}]},{"id":"2-1-2","b":2,"l":1,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Estado continuo con 著","en":"Ongoing Action with -著 zhe","ens":"Ongoing Action with -着 zhe","tc":"V＋著（狀態持續）","sc":"V＋着（状态持续）"},"d":{"es":"V + 著 indica un estado que continúa (resultado de una acción que permanece). Negación: 沒 + V + 著.","en":"V + 著 shows a state that continues (the result of an action that stays). Negation: 沒 + V + 著.","tc":"「V＋著」表示動作的結果或狀態一直持續著。否定時用「沒＋V＋著」。","sc":"「V＋着」表示动作的结果或状态一直持续着。否定时用「没＋V＋着」。"},"ex":[{"c":"門開著。","s":"门开着。","es":"La puerta está abierta.","en":"The door is open."},{"c":"他穿著一件藍色的外套。","s":"他穿着一件蓝色的外套。","es":"Lleva puesta una chaqueta azul.","en":"He is wearing a blue jacket."}]},{"id":"2-1-3","b":2,"l":1,"k":"","t":{"es":"Dos acciones con 一邊…一邊","en":"Two Simultaneously Actions with 一邊 yìbiān…一邊 yìbiān…","ens":"Two Simultaneously Actions with 一边 yìbiān…一边 yìbiān…","tc":"一邊…一邊…","sc":"一边…一边…"},"d":{"es":"一邊 A 一邊 B = hacer A y B al mismo tiempo (el mismo sujeto).","en":"一邊 A 一邊 B means doing A and B at the same time (same subject).","tc":"「一邊 A 一邊 B」表示同一個人同時做 A 和 B 兩件事。","sc":"「一边 A 一边 B」表示同一个人同时做 A 和 B 两件事。"},"ex":[{"c":"他一邊走路一邊聽音樂。","s":"他一边走路一边听音乐。","es":"Camina mientras escucha música.","en":"He listens to music while walking."}]},{"id":"2-1-4","b":2,"l":1,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Distancia con 離","en":"Distance from with 離 lí…","ens":"Distance from with 离 lí…","tc":"離（距離）","sc":"离（距离）"},"d":{"es":"A 離 B + (很) 遠 / 近 = A está lejos / cerca de B. 離 indica distancia; 從 indica punto de partida.","en":"A 離 B + (很) 遠 / 近 means A is far from / near B. 離 shows distance; 從 shows a starting point.","tc":"「A 離 B ＋（很）遠／近」表示 A 和 B 之間的距離。「離」說的是距離，「從」說的是起點。","sc":"「A 离 B ＋（很）远／近」表示 A 和 B 之间的距离。「离」说的是距离，「从」说的是起点。"},"ex":[{"c":"我家離學校很近。","s":"我家离学校很近。","es":"Mi casa está muy cerca de la escuela.","en":"My home is very close to the school."}]},{"id":"2-2-0","b":2,"l":2,"k":"negación negar negativa negation negative 否定 énfasis enfático incluso emphasis emphatic even 強調 甚至 negación negar negativa negation negative 否定 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Negación enfática 一點也不","en":"Emphatic Negation with 一點也不 yìdiǎn yě bù V …","ens":"Emphatic Negation with 一点也不 yìdiǎn yě bù V …","tc":"一點也不／一點也沒","sc":"一点也不／一点也没"},"d":{"es":"一點也不 / 一點也沒 + verbo o adjetivo = en absoluto, nada. Es una negación enfática.","en":"一點也不 / 一點也沒 + verb or adjective is an emphatic negation: 'not at all'.","tc":"「一點也不／一點也沒＋動詞或形容詞」是加強語氣的否定，意思是完全不、一點都不。","sc":"「一点也不／一点也没＋动词或形容词」是加强语气的否定，意思是完全不、一点都不。"},"ex":[{"c":"我一點也不累。","s":"我一点也不累。","es":"No estoy nada cansado.","en":"I am not tired at all."}]},{"id":"2-2-1","b":2,"l":2,"k":"además adición también addition also besides 另外 而且 sugerencia proposición suggestion 建議 además adición también addition also besides 另外 而且 sugerencia proposición suggestion 建议","t":{"es":"Sugerencia con 還是…吧","en":"還是 háishì…吧 ba！ It would be better if …","ens":"还是 háishì…吧 ba！ It would be better if …","tc":"還是…吧","sc":"还是…吧"},"d":{"es":"還是 + sugerencia + 吧 = mejor + (hagamos algo). Se compara y se recomienda una opción.","en":"還是 + suggestion + 吧 means 'it would be better to…' after comparing options.","tc":"「還是＋建議＋吧」表示比較過後，覺得這樣做比較好。","sc":"「还是＋建议＋吧」表示比较过后，觉得这样做比较好。"},"ex":[{"c":"太晚了，我們還是搭計程車吧。","s":"太晚了，我们还是搭计程车吧。","es":"Es muy tarde, mejor tomemos un taxi.","en":"It's too late; we'd better take a taxi."}]},{"id":"2-2-2","b":2,"l":2,"k":"","t":{"es":"Petición con 一點","en":"Form Adverbials with 一點 yìdiǎn","ens":"Form Adverbials with 一点 yìdiǎn","tc":"形容詞＋一點（說慢一點）","sc":"形容词＋一点（说慢一点）"},"d":{"es":"Adjetivo + 一點 + verbo (o verbo + adjetivo + 一點) forma una petición suave: «hazlo un poco más…».","en":"Adjective + 一點 + verb (or verb + adjective + 一點) makes a soft request: 'a little more…'.","tc":"「形容詞＋一點＋動詞」或「動詞＋形容詞＋一點」用來客氣地請對方再怎麼樣一點，語氣比較柔和。","sc":"「形容词＋一点＋动词」或「动词＋形容词＋一点」用来客气地请对方再怎么样一点，语气比较柔和。"},"ex":[{"c":"請你說慢一點。","s":"请你说慢一点。","es":"Por favor habla un poco más despacio.","en":"Please speak a little slower."},{"c":"你早一點來。","s":"你早一点来。","es":"Llega un poco más temprano.","en":"Come a little earlier."}]},{"id":"2-2-3","b":2,"l":2,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Reduplicación AABB","en":"Reduplication of Disyllabic Adjectives","ens":"Reduplication of Disyllabic Adjectives","tc":"雙音節形容詞重疊（AABB）","sc":"双音节形容词重叠（AABB）"},"d":{"es":"Los adjetivos de dos sílabas AB se duplican como AABB; resultan más vívidos y ya no llevan 很.","en":"A two-syllable adjective AB can be doubled as AABB to be more vivid. 很 is no longer needed.","tc":"雙音節形容詞 AB 可以重疊成 AABB，讓描述更生動，前面不用再加「很」。","sc":"双音节形容词 AB 可以重叠成 AABB，让描述更生动，前面不用再加「很」。"},"ex":[{"c":"房間乾乾淨淨的。","s":"房间干干净净的。","es":"El cuarto está muy limpio.","en":"The room is nice and clean."}]},{"id":"2-2-4","b":2,"l":2,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Negación suave con 不太","en":"不太 bútài not very","ens":"不太 bútài not very","tc":"不太","sc":"不太"},"d":{"es":"不太 + adjetivo / verbo = no muy, no demasiado. Es una negación suave.","en":"不太 + adjective / verb means 'not very, not so much'. It is a softer negation.","tc":"「不太＋形容詞／動詞」表示不是很、不怎麼，語氣比「不」柔和。","sc":"「不太＋形容词／动词」表示不是很、不怎么，语气比「不」柔和。"},"ex":[{"c":"我不太喜歡吃辣。","s":"我不太喜欢吃辣。","es":"No me gusta mucho el picante.","en":"I don't really like spicy food."}]},{"id":"2-2-5","b":2,"l":2,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Ubicación con 部 y 邊","en":"Locations with 部 bù /邊 biān","ens":"Locations with 部 bù /边 biān","tc":"方位詞：部、邊","sc":"方位词：部、边"},"d":{"es":"部 se usa para regiones (北部, 南部, 東部, 西部); 邊 para posiciones (上邊, 裡邊, 旁邊, 左邊, 右邊).","en":"部 is used for regions (北部, 南部, 東部, 西部); 邊 for positions (上邊, 裡邊, 旁邊, 左邊, 右邊).","tc":"「部」用在地區，例如北部、南部、東部；「邊」用在位置，例如上邊、旁邊、左邊、右邊。","sc":"「部」用在地区，例如北部、南部、东部；「边」用在位置，例如上边、旁边、左边、右边。"},"ex":[{"c":"台北在台灣的北部。","s":"台北在台湾的北部。","es":"Taipéi está en el norte de Taiwán.","en":"Taipei is in northern Taiwan."},{"c":"銀行在郵局的旁邊。","s":"银行在邮局的旁边。","es":"El banco está al lado del correo.","en":"The bank is next to the post office."}]},{"id":"2-3-0","b":2,"l":3,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Usos de 差不多","en":"Various Functions of 差不 chàbùduō","ens":"Various Functions of 差不 chàbùduō","tc":"差不多","sc":"差不多"},"d":{"es":"差不多 puede ser adjetivo («casi igual»), adverbio («casi») o «más o menos».","en":"差不多 can be an adjective ('almost the same'), an adverb ('almost') or mean 'more or less'.","tc":"「差不多」可以當形容詞（幾乎一樣）、副詞（快要）或表示大概。","sc":"「差不多」可以当形容词（几乎一样）、副词（快要）或表示大概。"},"ex":[{"c":"我們差不多高。","s":"我们差不多高。","es":"Somos casi igual de altos.","en":"We are about the same height."},{"c":"差不多十二點了。","s":"差不多十二点了。","es":"Son casi las doce.","en":"It is almost twelve o'clock."}]},{"id":"2-3-1","b":2,"l":3,"k":"experiencia alguna vez haber experience ever 經驗 經歷 experiencia alguna vez haber experience ever 经验 经历","t":{"es":"Experiencia con 過","en":"Experience Particle 過 guò","ens":"Experience Particle 过 guò","tc":"經驗：V＋過","sc":"经验：V＋过"},"d":{"es":"V + 過 indica experiencia: «alguna vez». Negación: 沒 + V + 過.","en":"V + 過 shows past experience: 'have ever done'. Negation: 沒 + V + 過.","tc":"「V＋過」表示有過這樣的經驗。否定時用「沒＋V＋過」。","sc":"「V＋过」表示有过这样的经验。否定时用「没＋V＋过」。"},"ex":[{"c":"我去過日本。","s":"我去过日本。","es":"He ido a Japón.","en":"I have been to Japan."},{"c":"我沒吃過臭豆腐。","s":"我没吃过臭豆腐。","es":"Nunca he comido tofu apestoso.","en":"I have never eaten stinky tofu."}]},{"id":"2-3-2","b":2,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Apenas con 才","en":"才 cái merely, only","ens":"才 cái merely, only","tc":"才（只有、剛剛）","sc":"才（只有、刚刚）"},"d":{"es":"才 + cantidad pequeña = apenas, solo.","en":"才 + a small amount means 'only, just'.","tc":"「才＋數量少」表示只有、才剛剛。","sc":"「才＋数量少」表示只有、才刚刚。"},"ex":[{"c":"現在才八點。","s":"现在才八点。","es":"Apenas son las ocho.","en":"It's only eight o'clock now."},{"c":"我才學了三個月。","s":"我才学了三个月。","es":"Solo llevo tres meses estudiando.","en":"I have only studied for three months."}]},{"id":"2-3-3","b":2,"l":3,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Recordar con 想起來","en":"想起來 xiǎngqǐlái to have remembered","ens":"想起来 xiǎngqǐlái to have remembered","tc":"想起來","sc":"想起来"},"d":{"es":"想起來 = recordar de repente algo que se había olvidado.","en":"想起來 means to suddenly remember something that had been forgotten.","tc":"「想起來」表示突然想到、記起原本忘記的事。","sc":"「想起来」表示突然想到、记起原本忘记的事。"},"ex":[{"c":"我想起來了，他叫王明。","s":"我想起来了，他叫王明。","es":"Ya recordé, se llama Wang Ming.","en":"I remember now, his name is Wang Ming."}]},{"id":"2-3-4","b":2,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Más tarde de lo esperado con 才","en":"Longer/Later Than Expected with 才 cái","ens":"Longer/Later Than Expected with 才 cái","tc":"時間＋才（比預期晚）","sc":"时间＋才（比预期晚）"},"d":{"es":"Tiempo + 才 + verbo = más tarde de lo esperado. Contrasta con 就 (más temprano de lo esperado).","en":"Time + 才 + verb shows something happens later than expected. It is the opposite of 就 (earlier than expected).","tc":"「時間＋才＋動詞」表示比預期的晚。跟「就」相反，「就」表示比預期的早。","sc":"「时间＋才＋动词」表示比预期的晚。跟「就」相反，「就」表示比预期的早。"},"ex":[{"c":"他十點才起床。","s":"他十点才起床。","es":"Se levanta hasta las diez.","en":"He doesn't get up until ten."}]},{"id":"2-3-5","b":2,"l":3,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Acción suave con ABAB","en":"Tentative Action with Reduplicated Disyllabic Verbs ABAB","ens":"Tentative Action with Reduplicated Disyllabic Verbs ABAB","tc":"雙音節動詞重疊（ABAB）","sc":"双音节动词重叠（ABAB）"},"d":{"es":"Los verbos de dos sílabas AB duplicados como ABAB suavizan la acción: «un poco, para ver».","en":"A two-syllable verb AB can be doubled as ABAB to soften the action: 'do it a little'.","tc":"雙音節動詞 AB 可以重疊成 ABAB，讓動作比較輕鬆，意思是稍微做一下、試試看。","sc":"双音节动词 AB 可以重叠成 ABAB，让动作比较轻松，意思是稍微做一下、试试看。"},"ex":[{"c":"我們討論討論吧。","s":"我们讨论讨论吧。","es":"Hablemos un poco de esto.","en":"Let's discuss it a bit."}]},{"id":"2-4-0","b":2,"l":4,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además de con 除了…還","en":"除了 chúle…，還 hái… in addition to…","ens":"除了 chúle…，还 hái… in addition to…","tc":"除了…，還…","sc":"除了…，还…"},"d":{"es":"除了 A，還 B = además de A, también B.","en":"除了 A，還 B means 'in addition to A, also B'.","tc":"「除了 A，還 B」表示 A 之外，也有 B。","sc":"「除了 A，还 B」表示 A 之外，也有 B。"},"ex":[{"c":"除了英文，他還會說中文。","s":"除了英文，他还会说中文。","es":"Además de inglés, también habla chino.","en":"Besides English, he also speaks Chinese."}]},{"id":"2-4-1","b":2,"l":4,"k":"","t":{"es":"Según con 按照","en":"按照…ànzhào… in accordance with","ens":"按照…ànzhào… in accordance with","tc":"按照","sc":"按照"},"d":{"es":"按照 + norma / plan / indicación = según, conforme a.","en":"按照 + rule / plan / instruction means 'according to, in accordance with'.","tc":"「按照＋規定／計畫／說法」表示依照某個標準去做。","sc":"「按照＋规定／计划／说法」表示依照某个标准去做。"},"ex":[{"c":"請按照老師說的做。","s":"请按照老师说的做。","es":"Por favor haz lo que dijo el profesor.","en":"Please do as the teacher said."}]},{"id":"2-4-2","b":2,"l":4,"k":"","t":{"es":"Usos de 跟","en":"Various Meaning of the Preposition 跟 gēn","ens":"Various Meaning of the Preposition 跟 gēn","tc":"跟（多種意思）","sc":"跟（多种意思）"},"d":{"es":"跟 tiene varios usos: «con» (compañía), «de» en 跟…學 / 跟…借, «igual que» en 跟…一樣, y «y» entre sustantivos.","en":"跟 has several uses: 'with' (company), 'from' in 跟…學 / 跟…借, 'the same as' in 跟…一樣, and 'and' between nouns.","tc":"「跟」有很多用法：跟誰一起（陪伴）、跟誰學／借（對象）、跟……一樣（比較），也可以像「和」連接兩個名詞。","sc":"「跟」有很多用法：跟谁一起（陪伴）、跟谁学／借（对象）、跟……一样（比较），也可以像「和」连接两个名词。"},"ex":[{"c":"我跟老師學中文。","s":"我跟老师学中文。","es":"Aprendo chino con el profesor.","en":"I learn Chinese from my teacher."}]},{"id":"2-4-3","b":2,"l":4,"k":"","t":{"es":"Usos de 給","en":"Various Meanings of 給 gěi","ens":"Various Meanings of 给 gěi","tc":"給（多種意思）","sc":"给（多种意思）"},"d":{"es":"給 puede ser verbo («dar»), preposición («para») o marcar al destinatario después del verbo (寄給你).","en":"給 can be a verb ('give'), a preposition ('for') or follow a verb to mark the receiver (寄給你).","tc":"「給」可以是動詞（給我一本書）、介詞（給你的禮物），也可以放在動詞後面表示給誰，例如「寄給他」。","sc":"「给」可以是动词（给我一本书）、介词（给你的礼物），也可以放在动词后面表示给谁，例如「寄给他」。"},"ex":[{"c":"我給你一個禮物。","s":"我给你一个礼物。","es":"Te doy un regalo.","en":"I give you a gift."},{"c":"我寄給他一封信。","s":"我寄给他一封信。","es":"Le envié una carta.","en":"I sent him a letter."}]},{"id":"2-4-4","b":2,"l":4,"k":"","t":{"es":"Hacia con 對","en":"對 duì… towards…","ens":"对 duì… towards…","tc":"對（對於）","sc":"对（对于）"},"d":{"es":"對 + persona / cosa + adjetivo o verbo = hacia, con respecto a. Es común en 對…有興趣 y 對…很好.","en":"對 + person / thing + adjective or verb means 'toward, regarding'. Common in 對…有興趣 and 對…很好.","tc":"「對＋人／事＋形容詞或動詞」表示針對某個對象，常見的有「對……有興趣」「對……很好」。","sc":"「对＋人／事＋形容词或动词」表示针对某个对象，常见的有「对……有兴趣」「对……很好」。"},"ex":[{"c":"我對台灣文化很有興趣。","s":"我对台湾文化很有兴趣。","es":"Me interesa mucho la cultura de Taiwán.","en":"I am very interested in Taiwanese culture."}]},{"id":"2-5-0","b":2,"l":5,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Todavía con 還","en":"還 hái still","ens":"还 hái still","tc":"還（仍然）","sc":"还（仍然）"},"d":{"es":"還 = todavía, aún (continúa una situación). 還沒 + verbo = todavía no.","en":"還 means 'still' (the situation continues). 還沒 + verb means 'not yet'.","tc":"「還」表示情況持續，意思是仍然、還在。「還沒＋動詞」表示到現在還沒有。","sc":"「还」表示情况持续，意思是仍然、还在。「还没＋动词」表示到现在还没有。"},"ex":[{"c":"他還在睡覺。","s":"他还在睡觉。","es":"Todavía está durmiendo.","en":"He is still sleeping."},{"c":"我還沒吃飯。","s":"我还没吃饭。","es":"Todavía no he comido.","en":"I haven't eaten yet."}]},{"id":"2-5-1","b":2,"l":5,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Manera con V著","en":"Manner of an Action with V 著 zhe","ens":"Manner of an Action with V 着 zhe","tc":"V1＋著＋V2（方式）","sc":"V1＋着＋V2（方式）"},"d":{"es":"V1 + 著 + V2: V1 describe la manera en que se realiza V2.","en":"In V1 + 著 + V2, V1 describes the manner in which V2 is done.","tc":"「V1＋著＋V2」中，V1 說明做 V2 時的方式或狀態。","sc":"「V1＋着＋V2」中，V1 说明做 V2 时的方式或状态。"},"ex":[{"c":"他笑著說話。","s":"他笑着说话。","es":"Habla sonriendo.","en":"He speaks with a smile."}]},{"id":"2-5-2","b":2,"l":5,"k":"","t":{"es":"Varios verbos en una oración","en":"Multiple Verb Phrases in a Sentence","ens":"Multiple Verb Phrases in a Sentence","tc":"連動句（多個動詞）","sc":"连动句（多个动词）"},"d":{"es":"En una oración se pueden encadenar varios verbos en el orden en que ocurren.","en":"A sentence can chain several verbs in the order the actions happen.","tc":"一個句子裡可以依照動作發生的順序，連續放好幾個動詞。","sc":"一个句子里可以依照动作发生的顺序，连续放好几个动词。"},"ex":[{"c":"她下班回家做飯。","s":"她下班回家做饭。","es":"Ella sale del trabajo, vuelve a casa y cocina.","en":"She gets off work, goes home and cooks."}]},{"id":"2-5-3","b":2,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando… entonces con 等…就","en":"When A Comes, Then B…with 等 děng 就…jiù…","ens":"When A Comes, Then B…with 等 děng 就…jiù…","tc":"等…就…","sc":"等…就…"},"d":{"es":"等 A 就 B = cuando ocurra A, entonces B.","en":"等 A 就 B means 'when A happens, then B'.","tc":"「等 A 就 B」表示等 A 發生之後，就做 B。","sc":"「等 A 就 B」表示等 A 发生之后，就做 B。"},"ex":[{"c":"等你來了，我們就出發。","s":"等你来了，我们就出发。","es":"Cuando llegues, salimos.","en":"When you arrive, we'll set off."}]},{"id":"2-5-4","b":2,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 tiempo momento orden secuencia time order sequence 时间 顺序 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"De pronto con V著V著就…了","en":"While Doing A, B Happens with V 著 zhe V 著 zhe， 就 jiù…了 le","ens":"While Doing A, B Happens with V 着 zhe V 着 zhe， 就 jiù…了 le","tc":"V著V著就…了","sc":"V着V着就…了"},"d":{"es":"V著V著就…了 = mientras hacía algo, de pronto ocurrió otra cosa.","en":"V著V著就…了 means 'while doing something, suddenly something else happened'.","tc":"「V著V著就…了」表示做著做著，突然出現了另一個情況。","sc":"「V着V着就…了」表示做着做着，突然出现了另一个情况。"},"ex":[{"c":"他看著看著就睡著了。","s":"他看着看着就睡着了。","es":"Mientras miraba, se quedó dormido.","en":"He was watching and fell asleep."}]},{"id":"2-6-0","b":2,"l":6,"k":"","t":{"es":"Destino con 到","en":"Destination Marker 到 dào","ens":"Destination Marker 到 dào","tc":"V＋到＋地點","sc":"V＋到＋地点"},"d":{"es":"V + 到 + lugar: la acción llega hasta ese lugar. 到 marca el destino.","en":"V + 到 + place means the action reaches that place. 到 marks the destination.","tc":"「V＋到＋地點」表示動作到達某個地方，「到」標示終點。","sc":"「V＋到＋地点」表示动作到达某个地方，「到」标示终点。"},"ex":[{"c":"我們走到公園吧。","s":"我们走到公园吧。","es":"Caminemos hasta el parque.","en":"Let's walk to the park."}]},{"id":"2-6-1","b":2,"l":6,"k":"","t":{"es":"Dar a alguien con 給","en":"Indirect Object Marker 給 gěi","ens":"Indirect Object Marker 给 gěi","tc":"V＋給＋人","sc":"V＋给＋人"},"d":{"es":"V + 給 + persona: dar o transferir algo a alguien (送給, 寄給, 交給, 借給).","en":"V + 給 + person means giving or passing something to someone (送給, 寄給, 交給, 借給).","tc":"「V＋給＋人」表示把東西送、寄、交給某個人，例如送給、寄給、交給、借給。","sc":"「V＋给＋人」表示把东西送、寄、交给某个人，例如送给、寄给、交给、借给。"},"ex":[{"c":"他送給我一本書。","s":"他送给我一本书。","es":"Me regaló un libro.","en":"He gave me a book as a present."}]},{"id":"2-6-2","b":2,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Lugar resultante con V在","en":"Resultant Location with V+在 zài…","ens":"Resultant Location with V+在 zài…","tc":"V＋在＋地點","sc":"V＋在＋地点"},"d":{"es":"V + 在 + lugar: como resultado de la acción, algo o alguien queda en ese lugar.","en":"V + 在 + place means that, as a result of the action, something or someone ends up in that place.","tc":"「V＋在＋地點」表示動作之後，東西或人留在那個地方。","sc":"「V＋在＋地点」表示动作之后，东西或人留在那个地方。"},"ex":[{"c":"我把車停在學校。","s":"我把车停在学校。","es":"Estaciono el coche en la escuela.","en":"I park my car at the school."}]},{"id":"2-6-3","b":2,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 disposición objeto complemento disposal object ba 處置 把字句 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Mover con 把","en":"Moving an Object to a Location with 把 bǎ","ens":"Moving an Object to a Location with 把 bǎ","tc":"把＋物＋V＋到／在／給","sc":"把＋物＋V＋到／在／给"},"d":{"es":"把 + objeto + V + 到 / 在 / 給 + lugar o persona: mover un objeto a otro lugar.","en":"把 + object + V + 到 / 在 / 給 + place or person means moving an object somewhere.","tc":"「把＋東西＋動詞＋到／在／給＋地點或人」表示把東西移到某個地方。","sc":"「把＋东西＋动词＋到／在／给＋地点或人」表示把东西移到某个地方。"},"ex":[{"c":"請把書放在桌子上。","s":"请把书放在桌子上。","es":"Por favor pon el libro sobre la mesa.","en":"Please put the book on the table."}]},{"id":"2-6-4","b":2,"l":6,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además con 而且","en":"而且 érqiě furthermore","ens":"而且 érqiě furthermore","tc":"而且","sc":"而且"},"d":{"es":"而且 = además. Añade información que refuerza lo anterior.","en":"而且 means 'furthermore'. It adds information that reinforces the previous point.","tc":"「而且」表示再加上另一個更進一步的情況。","sc":"「而且」表示再加上另一个更进一步的情况。"},"ex":[{"c":"這家餐廳很好吃，而且很便宜。","s":"这家餐厅很好吃，而且很便宜。","es":"Este restaurante es rico y además barato.","en":"This restaurant is delicious, and cheap too."}]},{"id":"2-7-0","b":2,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Dirección con 來／去","en":"Directional ConstructionsV1V2 and V1V2V3","ens":"Directional ConstructionsV1V2 and V1V2V3","tc":"複合趨向補語（V＋進來、V＋出去）","sc":"复合趋向补语（V＋进来、V＋出去）"},"d":{"es":"Verbo + dirección (上, 下, 進, 出, 回, 過, 起) + 來 / 去: movimiento hacia (來) o lejos (去) del hablante. También V1V2V3.","en":"A verb plus a direction (上, 下, 進, 出, 回, 過, 起) plus 來 or 去 shows movement toward (來) or away from (去) the speaker. V1V2V3 also exists.","tc":"動詞後面加上、下、進、出、回、過、起，再加「來」或「去」，表示動作的方向：朝說話的人是「來」，離開說話的人是「去」。","sc":"动词后面加上、下、进、出、回、过、起，再加「来」或「去」，表示动作的方向：朝说话的人是「来」，离开说话的人是「去」。"},"ex":[{"c":"他走進來了。","s":"他走进来了。","es":"Entró caminando.","en":"He walked in."},{"c":"她跑出去了。","s":"她跑出去了。","es":"Salió corriendo.","en":"She ran out."}]},{"id":"2-7-1","b":2,"l":7,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"把 con dirección","en":"把 bǎ with V1V2V3","ens":"把 bǎ with V1V2V3","tc":"把＋物＋V＋趨向補語","sc":"把＋物＋V＋趋向补语"},"d":{"es":"把 + objeto + verbo + dirección + 來 / 去: mover el objeto en esa dirección.","en":"把 + object + verb + direction + 來 / 去 means moving the object in that direction.","tc":"「把＋東西＋動詞＋方向＋來／去」表示把東西往某個方向移動。","sc":"「把＋东西＋动词＋方向＋来／去」表示把东西往某个方向移动。"},"ex":[{"c":"請把椅子搬到樓上去。","s":"请把椅子搬到楼上去。","es":"Por favor lleva la silla al piso de arriba.","en":"Please carry the chair upstairs."}]},{"id":"2-7-2","b":2,"l":7,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Reproche con 嗎","en":"Confrontation with 嗎?","ens":"Confrontation with 吗?","tc":"用「嗎」表示責備","sc":"用「吗」表示责备"},"d":{"es":"Una pregunta con 嗎 puede expresar reproche o confrontación: «¿no ves que…?».","en":"A question with 嗎 can express reproach or confrontation rather than a real question: 'Can't you see…?'","tc":"用「嗎」的問句有時不是真的在問，而是在責備或表示不滿：你沒看到……嗎？","sc":"用「吗」的问句有时不是真的在问，而是在责备或表示不满：你没看到……吗？"},"ex":[{"c":"你沒看到我在忙嗎？","s":"你没看到我在忙吗？","es":"¿No ves que estoy ocupado?","en":"Can't you see that I'm busy?"}]},{"id":"2-7-3","b":2,"l":7,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Posición con V著","en":"Existential Sentence with Posture Verbs","ens":"Existential Sentence with Posture Verbs","tc":"存在句：地點＋V著＋物","sc":"存在句：地点＋V着＋物"},"d":{"es":"Lugar + verbo de posición (坐, 站, 躺, 放, 掛, 貼) + 著 + persona o cosa: así está colocado.","en":"Place + posture verb (坐, 站, 躺, 放, 掛, 貼) + 著 + person or thing describes how something is placed there.","tc":"「地點＋姿勢動詞（坐、站、躺、放、掛、貼）＋著＋人或東西」表示那裡擺放或存在的狀態。","sc":"「地点＋姿势动词（坐、站、躺、放、挂、贴）＋着＋人或东西」表示那里摆放或存在的状态。"},"ex":[{"c":"桌子上放著一本書。","s":"桌子上放着一本书。","es":"Sobre la mesa hay un libro (puesto).","en":"There is a book lying on the table."}]},{"id":"2-7-4","b":2,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Para con 為了","en":"為了 wèile in order to","ens":"为了 wèile in order to","tc":"為了","sc":"为了"},"d":{"es":"為了 + objetivo, + acción = para, con el fin de.","en":"為了 + goal, + action means 'in order to'.","tc":"「為了＋目的，＋動作」表示做某件事的目的。","sc":"「为了＋目的，＋动作」表示做某件事的目的。"},"ex":[{"c":"為了學好中文，我每天聽廣播。","s":"为了学好中文，我每天听广播。","es":"Para aprender bien chino escucho la radio todos los días.","en":"To learn Chinese well, I listen to the radio every day."}]},{"id":"2-8-0","b":2,"l":8,"k":"","t":{"es":"Percepción con 見","en":"見 jiàn as a Perceptual Result","ens":"见 jiàn as a Perceptual Result","tc":"V＋見（看見、聽見）","sc":"V＋见（看见、听见）"},"d":{"es":"V + 見 expresa que la percepción se logró: 看見 (ver), 聽見 (oír).","en":"V + 見 shows a successful perception: 看見 (see), 聽見 (hear).","tc":"「V＋見」表示感官的結果，例如看見、聽見，真的看到或聽到了。","sc":"「V＋见」表示感官的结果，例如看见、听见，真的看到或听到了。"},"ex":[{"c":"我聽見有人在叫我。","s":"我听见有人在叫我。","es":"Oí que alguien me llamaba.","en":"I heard someone calling me."}]},{"id":"2-8-1","b":2,"l":8,"k":"","t":{"es":"Comprender con 懂","en":"懂 dǒng as a Cognitive Result","ens":"懂 dǒng as a Cognitive Result","tc":"V＋懂（聽懂、看懂）","sc":"V＋懂（听懂、看懂）"},"d":{"es":"V + 懂 = comprender lo que se escucha o lee: 聽懂, 看懂.","en":"V + 懂 means understanding what you hear or read: 聽懂, 看懂.","tc":"「V＋懂」表示聽或看之後理解了，例如聽懂、看懂。","sc":"「V＋懂」表示听或看之后理解了，例如听懂、看懂。"},"ex":[{"c":"老師說的話我聽得懂。","s":"老师说的话我听得懂。","es":"Entiendo lo que dice el profesor.","en":"I can understand what the teacher says."}]},{"id":"2-8-2","b":2,"l":8,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Aprender con 會","en":"會 huìas an Achievement Result","ens":"会 huìas an Achievement Result","tc":"V＋會（學會、教會）","sc":"V＋会（学会、教会）"},"d":{"es":"V + 會 = aprender a hacer algo (logro): 學會, 教會.","en":"V + 會 means to have learned how to do something: 學會, 教會.","tc":"「V＋會」表示學習之後學會了，例如學會、教會。","sc":"「V＋会」表示学习之后学会了，例如学会、教会。"},"ex":[{"c":"我學會了做蛋糕。","s":"我学会了做蛋糕。","es":"Aprendí a hacer pasteles.","en":"I learned how to make a cake."}]},{"id":"2-8-3","b":2,"l":8,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Potencial con 得／不","en":"Potential Capability with -得 de- or -不 bù-","ens":"Potential Capability with -得 de- or -不 bù-","tc":"可能補語（V得＋補語／V不＋補語）","sc":"可能补语（V得＋补语／V不＋补语）"},"d":{"es":"V + 得 + complemento = se puede; V + 不 + complemento = no se puede (por las circunstancias).","en":"V + 得 + complement means can; V + 不 + complement means cannot, depending on the circumstances.","tc":"「V＋得＋補語」表示可以，「V＋不＋補語」表示不能，指在條件上做不做得到。","sc":"「V＋得＋补语」表示可以，「V＋不＋补语」表示不能，指在条件上做不做得到。"},"ex":[{"c":"我看得懂，他看不懂。","s":"我看得懂，他看不懂。","es":"Yo sí lo entiendo al leerlo; él no.","en":"I can understand it, but he can't."},{"c":"這麼多菜，我吃不完。","s":"这么多菜，我吃不完。","es":"Con tanta comida, no puedo terminarla.","en":"With so many dishes, I can't finish them."}]},{"id":"2-8-4","b":2,"l":8,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 complemento resultado potencial complement result potential 补语 结果补语 可能补语 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Capacidad con 了 (liǎo)","en":"Capability Complement 了 liǎo","ens":"Capability Complement 了 liǎo","tc":"V＋得了／不了","sc":"V＋得了／不了"},"d":{"es":"V + 得了 / 不了 = poder / no poder completar o soportar algo. Aquí 了 se lee liǎo.","en":"V + 得了 / 不了 means being able / unable to finish or endure something. Here 了 is read liǎo.","tc":"「V＋得了／不了」表示能不能完成或承受。這裡的「了」唸 liǎo。","sc":"「V＋得了／不了」表示能不能完成或承受。这里的「了」念 liǎo。"},"ex":[{"c":"太多了，我吃不了。","s":"太多了，我吃不了。","es":"Es demasiado, no puedo con todo.","en":"It's too much, I can't finish it."}]},{"id":"2-8-5","b":2,"l":8,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Resultado con 得","en":"Vs +得 de + complement so …that…","ens":"Vs +得 de + complement so …that…","tc":"形容詞／動詞＋得＋結果","sc":"形容词／动词＋得＋结果"},"d":{"es":"Adjetivo / verbo + 得 + resultado = tan… que…","en":"Adjective / verb + 得 + result means 'so… that…'.","tc":"「形容詞或動詞＋得＋結果」表示程度很高，高到出現某個結果：……得……。","sc":"「形容词或动词＋得＋结果」表示程度很高，高到出现某个结果：……得……。"},"ex":[{"c":"他高興得跳起來。","s":"他高兴得跳起来。","es":"Estaba tan contento que saltó.","en":"He was so happy that he jumped up."}]},{"id":"2-8-6","b":2,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Continuar con 下去","en":"To Keep on Doing Something with 下去 xiàqù","ens":"To Keep on Doing Something with 下去 xiàqù","tc":"V＋下去","sc":"V＋下去"},"d":{"es":"V + 下去 = seguir haciendo algo (de ahora en adelante).","en":"V + 下去 means to keep on doing something from now on.","tc":"「V＋下去」表示從現在開始繼續做下去。","sc":"「V＋下去」表示从现在开始继续做下去。"},"ex":[{"c":"你說下去，我在聽。","s":"你说下去，我在听。","es":"Sigue, te estoy escuchando.","en":"Go on, I'm listening."}]},{"id":"2-8-7","b":2,"l":8,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Terminar con 完","en":"Completion of an Action with V+完 wán","ens":"Completion of an Action with V+完 wán","tc":"V＋完","sc":"V＋完"},"d":{"es":"V + 完 = terminar de hacer algo. Negación: 沒 + V + 完.","en":"V + 完 means to finish doing something. Negation: 沒 + V + 完.","tc":"「V＋完」表示把某件事做完。否定時用「沒＋V＋完」。","sc":"「V＋完」表示把某件事做完。否定时用「没＋V＋完」。"},"ex":[{"c":"我寫完功課了。","s":"我写完功课了。","es":"Terminé la tarea.","en":"I finished my homework."}]},{"id":"2-9-0","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Listo con 好","en":"All Set and Ready with Verb Complement 好 hǎo","ens":"All Set and Ready with Verb Complement 好 hǎo","tc":"V＋好","sc":"V＋好"},"d":{"es":"V + 好 = quedar listo o hecho bien: 準備好, 做好, 洗好.","en":"V + 好 means something is done or ready: 準備好, 做好, 洗好.","tc":"「V＋好」表示事情做好了、準備好了，例如準備好、做好、洗好。","sc":"「V＋好」表示事情做好了、准备好了，例如准备好、做好、洗好。"},"ex":[{"c":"飯做好了。","s":"饭做好了。","es":"La comida ya está lista.","en":"The meal is ready."}]},{"id":"2-9-1","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lograr con 到","en":"To Be Successful in …with Verb Complement 到 dào","ens":"To Be Successful in …with Verb Complement 到 dào","tc":"V＋到（達成結果）","sc":"V＋到（达成结果）"},"d":{"es":"V + 到 = lograr el resultado esperado: 買到, 找到, 看到.","en":"V + 到 means achieving the intended result: 買到, 找到, 看到.","tc":"「V＋到」表示達到想要的結果，例如買到、找到、看到。","sc":"「V＋到」表示达到想要的结果，例如买到、找到、看到。"},"ex":[{"c":"我買到票了。","s":"我买到票了。","es":"Conseguí el boleto.","en":"I got the ticket."}]},{"id":"2-9-2","b":2,"l":9,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 dirección movimiento direction movement 方向 趨向 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 dirección movimiento direction movement 方向 趋向","t":{"es":"Comparar con 比起來","en":"Comparison with 比起來 bǐ qǐlái","ens":"Comparison with 比起来 bǐ qǐlái","tc":"跟…比起來","sc":"跟…比起来"},"d":{"es":"跟 B 比起來，A… / 比起 B，A… = en comparación con B, A…","en":"跟 B 比起來，A… / 比起 B，A… means 'compared with B, A…'.","tc":"「跟 B 比起來，A……」或「比起 B，A……」表示拿 A 跟 B 做比較。","sc":"「跟 B 比起来，A……」或「比起 B，A……」表示拿 A 跟 B 做比较。"},"ex":[{"c":"跟台北比起來，高雄比較熱。","s":"跟台北比起来，高雄比较热。","es":"Comparado con Taipéi, Kaohsiung es más caluroso.","en":"Compared with Taipei, Kaohsiung is hotter."}]},{"id":"2-9-3","b":2,"l":9,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Semejanza con 像…一樣","en":"像 xiàng…一樣 yí yàng … is just like…","ens":"像 xiàng…一样 yí yàng … is just like…","tc":"像…一樣","sc":"像…一样"},"d":{"es":"A 像 B 一樣 (+ adjetivo / verbo) = A es como B.","en":"A 像 B 一樣 (+ adjective / verb) means A is like B.","tc":"「A 像 B 一樣（＋形容詞／動詞）」表示 A 跟 B 很相似。","sc":"「A 像 B 一样（＋形容词／动词）」表示 A 跟 B 很相似。"},"ex":[{"c":"他像小孩子一樣愛玩。","s":"他像小孩子一样爱玩。","es":"Le gusta jugar como a un niño.","en":"He loves to play just like a child."}]},{"id":"2-9-4","b":2,"l":9,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Extremo con 極了","en":"Adverbial Complements 極了 jíle、得不得了 de bùdéliǎo、得很 de hěn terribly, extremely","ens":"Adverbial Complements 极了 jíle、得不得了 de bùdéliǎo、得很 de hěn terribly, extremely","tc":"形容詞＋極了／得不得了／得很","sc":"形容词＋极了／得不得了／得很"},"d":{"es":"Adjetivo + 極了 / 得不得了 / 得很 = extremadamente. Van después del adjetivo.","en":"Adjective + 極了 / 得不得了 / 得很 goes after the adjective and means 'extremely'.","tc":"「形容詞＋極了／得不得了／得很」放在形容詞後面，表示非常、程度很高。","sc":"「形容词＋极了／得不得了／得很」放在形容词后面，表示非常、程度很高。"},"ex":[{"c":"今天熱極了。","s":"今天热极了。","es":"Hoy hace muchísimo calor.","en":"It is extremely hot today."},{"c":"她高興得不得了。","s":"她高兴得不得了。","es":"Está contentísima.","en":"She is overjoyed."}]},{"id":"2-9-5","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Poder permitirse con 起","en":"Verb Complement 起 qǐ to be able to afford","ens":"Verb Complement 起 qǐ to be able to afford","tc":"V＋得起／不起","sc":"V＋得起／不起"},"d":{"es":"V + 得起 / 不起 = poder / no poder permitirse algo (por dinero o categoría).","en":"V + 得起 / 不起 means being able / unable to afford something (usually money).","tc":"「V＋得起／不起」表示有沒有能力負擔，通常指錢夠不夠。","sc":"「V＋得起／不起」表示有没有能力负担，通常指钱够不够。"},"ex":[{"c":"這個包包太貴了，我買不起。","s":"这个包包太贵了，我买不起。","es":"Esta bolsa es muy cara, no me la puedo permitir.","en":"This bag is too expensive; I can't afford it."}]},{"id":"2-10-0","b":2,"l":10,"k":"dirección movimiento direction movement 方向 趨向 complemento resultado potencial complement result potential 補語 結果補語 可能補語 dirección movimiento direction movement 方向 趋向 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Descubrir con 出來","en":"To Figure out with the Complement 出來 chūlái","ens":"To Figure out with the Complement 出来 chūlái","tc":"V＋出來","sc":"V＋出来"},"d":{"es":"V + 出來 = descubrir, distinguir o llegar a darse cuenta (sacar a la luz).","en":"V + 出來 means to figure out, make out or discover something.","tc":"「V＋出來」表示把原本不清楚的事情找出來、分辨出來或想出來。","sc":"「V＋出来」表示把原本不清楚的事情找出来、分辨出来或想出来。"},"ex":[{"c":"你聽得出來他是誰嗎？","s":"你听得出来他是谁吗？","es":"¿Puedes reconocer quién es por la voz?","en":"Can you tell who he is from his voice?"}]},{"id":"2-10-1","b":2,"l":10,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Caber con 下","en":"Enough Space to Accommodate with Verb Complement 下 xià","ens":"Enough Space to Accommodate with Verb Complement 下 xià","tc":"V＋得下／不下","sc":"V＋得下／不下"},"d":{"es":"V + 得下 / 不下 = hay / no hay espacio suficiente para acomodar algo.","en":"V + 得下 / 不下 means whether there is enough space to hold something.","tc":"「V＋得下／不下」表示空間夠不夠容納。","sc":"「V＋得下／不下」表示空间够不够容纳。"},"ex":[{"c":"這個房間坐得下十個人。","s":"这个房间坐得下十个人。","es":"En este cuarto caben diez personas sentadas.","en":"This room can seat ten people."}]},{"id":"2-10-2","b":2,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 reduplicación repetición reduplication repetition 重疊 disposición objeto complemento disposal object ba 处置 把字句 reduplicación repetición reduplication repetition 重叠","t":{"es":"把…V(一)V","en":"Disposal Construction 把 bǎ with Verb Reduplication 把 bǎ…V(一)V","ens":"Disposal Construction 把 bǎ with Verb Reduplication 把 bǎ…V(一)V","tc":"把＋物＋V(一)V","sc":"把＋物＋V(一)V"},"d":{"es":"把 + objeto + V(一)V = hacer algo con el objeto de forma breve o ligera.","en":"把 + object + V(一)V means to do something to the object briefly or lightly.","tc":"「把＋東西＋V(一)V」表示稍微處理一下那個東西，語氣輕鬆。","sc":"「把＋东西＋V(一)V」表示稍微处理一下那个东西，语气轻松。"},"ex":[{"c":"請你把房間整理整理。","s":"请你把房间整理整理。","es":"Por favor ordena un poco el cuarto.","en":"Please tidy up the room a bit."}]},{"id":"2-10-3","b":2,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 complemento resultado potencial complement result potential 補語 結果補語 可能補語 disposición objeto complemento disposal object ba 处置 把字句 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"把 con resultado","en":"Disposal Construction 把 bǎ with Resultative Complements","ens":"Disposal Construction 把 bǎ with Resultative Complements","tc":"把＋物＋V＋結果補語","sc":"把＋物＋V＋结果补语"},"d":{"es":"把 + objeto + V + complemento de resultado (完, 好, 乾淨, 壞…): el objeto queda en ese estado.","en":"把 + object + verb + result complement (完, 好, 乾淨, 壞…) shows the state the object ends up in.","tc":"「把＋東西＋動詞＋結果補語（完、好、乾淨、壞……）」表示東西因為這個動作變成某種結果。","sc":"「把＋东西＋动词＋结果补语（完、好、干净、坏……）」表示东西因为这个动作变成某种结果。"},"ex":[{"c":"我把衣服洗乾淨了。","s":"我把衣服洗干净了。","es":"Lavé la ropa y quedó limpia.","en":"I washed the clothes clean."}]},{"id":"2-10-4","b":2,"l":10,"k":"","t":{"es":"Aprovechar con 趁","en":"趁 chèn seize the moment","ens":"趁 chèn seize the moment","tc":"趁","sc":"趁"},"d":{"es":"趁 + oportunidad + verbo = aprovechar el momento para…","en":"趁 + opportunity + verb means 'take advantage of the moment to…'.","tc":"「趁＋機會＋動詞」表示利用某個機會或時間去做事。","sc":"「趁＋机会＋动词」表示利用某个机会或时间去做事。"},"ex":[{"c":"趁天氣好，我們去爬山吧。","s":"趁天气好，我们去爬山吧。","es":"Aprovechemos que hace buen tiempo para ir a la montaña.","en":"Let's go hiking while the weather is nice."}]},{"id":"2-11-0","b":2,"l":11,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"其他的 vs 別的","en":"The Others 其他 qítā de vs. Other 別的 biéde vs.","ens":"The Others 其他 qítā de vs. Other 别的 biéde vs.","tc":"其他的、別的","sc":"其他的、别的"},"d":{"es":"其他的 = los demás (el resto de un grupo). 別的 = otro, diferente (otra cosa u opción).","en":"其他的 means 'the rest' of a group; 別的 means 'another / something different'.","tc":"「其他的」是一群裡面剩下的人或東西；「別的」是另外不同的東西或選擇。","sc":"「其他的」是一群里面剩下的人或东西；「别的」是另外不同的东西或选择。"},"ex":[{"c":"其他的同學都走了。","s":"其他的同学都走了。","es":"Los demás compañeros ya se fueron.","en":"The other classmates have all left."},{"c":"這個我不要，我要別的。","s":"这个我不要，我要别的。","es":"Esto no lo quiero, quiero otra cosa.","en":"I don't want this one; I want something else."}]},{"id":"2-11-1","b":2,"l":11,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores verbales","en":"Verbal Classifiers 下 xià , 趟 tàng ,遍 biàn , and 次 cì","ens":"Verbal Classifiers 下 xià , 趟 tàng ,遍 biàn , and 次 cì","tc":"動量詞：下、趟、遍、次","sc":"动量词：下、趟、遍、次"},"d":{"es":"Clasificadores verbales: 次 = veces; 遍 = de principio a fin; 趟 = viaje de ida y vuelta; 下 = acción breve.","en":"Verbal measure words count actions: 次 = times; 遍 = once from start to finish; 趟 = a round trip; 下 = a short action.","tc":"動量詞用來算動作的次數：「次」是回數；「遍」是從頭到尾一次；「趟」是去一次再回來；「下」是很短的動作。","sc":"动量词用来算动作的次数：「次」是回数；「遍」是从头到尾一次；「趟」是去一次再回来；「下」是很短的动作。"},"ex":[{"c":"我去過兩次。","s":"我去过两次。","es":"He ido dos veces.","en":"I have been there twice."},{"c":"請你再說一遍。","s":"请你再说一遍。","es":"Por favor dilo una vez más.","en":"Please say it once more."}]},{"id":"2-11-2","b":2,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 dirección movimiento direction movement 方向 趨向 tiempo momento orden secuencia time order sequence 时间 顺序 dirección movimiento direction movement 方向 趋向","t":{"es":"然後、後來、以後","en":"Expressing Next in Sequence with 然後 ránhòu, 後來 hòulái, and 以後 yǐhòu","ens":"Expressing Next in Sequence with 然后 ránhòu, 后来 hòulái, and 以后 yǐhòu","tc":"然後、後來、以後","sc":"然后、后来、以后"},"d":{"es":"然後 = luego (secuencia); 後來 = más tarde (solo para el pasado); 以後 = después (pasado o futuro).","en":"然後 means 'and then' (sequence); 後來 means 'later' (only for the past); 以後 means 'after' (past or future).","tc":"「然後」表示接著；「後來」只能說過去的事；「以後」可以說過去或未來。","sc":"「然后」表示接着；「后来」只能说过去的事；「以后」可以说过去或未来。"},"ex":[{"c":"我先吃飯，然後看電視。","s":"我先吃饭，然后看电视。","es":"Primero como y luego veo televisión.","en":"First I eat, then I watch TV."},{"c":"後來他搬家了。","s":"后来他搬家了。","es":"Más tarde se mudó.","en":"Later he moved house."}]},{"id":"2-11-3","b":2,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Solo entonces con 才","en":"才 cái then and only then","ens":"才 cái then and only then","tc":"A才B（先後條件）","sc":"A才B（先后条件）"},"d":{"es":"A 才 B = solo después de A ocurre B (A es condición previa).","en":"A 才 B means B happens only after A. A is a prerequisite.","tc":"「A 才 B」表示要先有 A，才會有 B，A 是前提。","sc":"「A 才 B」表示要先有 A，才会有 B，A 是前提。"},"ex":[{"c":"吃了飯才可以玩。","s":"吃了饭才可以玩。","es":"Solo después de comer puedes jugar.","en":"You can play only after you eat."}]},{"id":"2-11-4","b":2,"l":11,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Pasiva con 被","en":"Passive Sentences with 被 bèi","ens":"Passive Sentences with 被 bèi","tc":"被字句","sc":"被字句"},"d":{"es":"A 被 B + verbo + complemento = A es afectado por B (pasiva, suele tener sentido negativo).","en":"A 被 B + verb + complement means A is affected by B (passive). It often describes something unfortunate.","tc":"「A 被 B ＋動詞＋補語」表示 A 受到 B 的影響，常常是不好的事。","sc":"「A 被 B ＋动词＋补语」表示 A 受到 B 的影响，常常是不好的事。"},"ex":[{"c":"我的手機被偷了。","s":"我的手机被偷了。","es":"Me robaron el celular.","en":"My phone was stolen."}]},{"id":"2-11-5","b":2,"l":11,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"V了V","en":"Verb Reduplication in V 了 le V","ens":"Verb Reduplication in V 了 le V","tc":"V了V","sc":"V了V"},"d":{"es":"V 了 V = hacer algo un ratito o un poco (acción ya realizada).","en":"V了V means doing something for a little while (an action already carried out).","tc":"「V了V」表示做了一下子，是已經做過的動作。","sc":"「V了V」表示做了一下子，是已经做过的动作。"},"ex":[{"c":"我想了想，決定不去。","s":"我想了想，决定不去。","es":"Lo pensé un poco y decidí no ir.","en":"I thought about it for a moment and decided not to go."}]},{"id":"2-11-6","b":2,"l":11,"k":"","t":{"es":"Contacto con 上","en":"Verb Particle 上 shàng coming into contact","ens":"Verb Particle 上 shàng coming into contact","tc":"V＋上","sc":"V＋上"},"d":{"es":"V + 上 expresa contacto o cierre: 關上 (cerrar), 穿上 (ponerse), 考上 (ser admitido), 愛上 (enamorarse).","en":"V + 上 shows contact or closing: 關上 (close), 穿上 (put on), 考上 (get admitted), 愛上 (fall in love with).","tc":"「V＋上」表示接觸或閉合，例如關上、穿上、考上、愛上。","sc":"「V＋上」表示接触或闭合，例如关上、穿上、考上、爱上。"},"ex":[{"c":"請關上門。","s":"请关上门。","es":"Por favor cierra la puerta.","en":"Please close the door."},{"c":"他考上大學了。","s":"他考上大学了。","es":"Entró a la universidad.","en":"He got into university."}]},{"id":"2-12-0","b":2,"l":12,"k":"","t":{"es":"Dejar con 讓","en":"讓 ràng to let someone do something","ens":"让 ràng to let someone do something","tc":"讓","sc":"让"},"d":{"es":"A 讓 B + verbo = A deja / hace que B haga algo (permiso o causa).","en":"A 讓 B + verb means A lets / makes B do something (permission or cause).","tc":"「A 讓 B ＋動詞」表示 A 允許或使 B 去做某件事。","sc":"「A 让 B ＋动词」表示 A 允许或使 B 去做某件事。"},"ex":[{"c":"媽媽讓我去玩。","s":"妈妈让我去玩。","es":"Mi mamá me deja ir a jugar.","en":"Mom lets me go play."}]},{"id":"2-12-1","b":2,"l":12,"k":"","t":{"es":"Apúrate con 快一點","en":"快一點 kuài yìdiǎn hurry up","ens":"快一点 kuài yìdiǎn hurry up","tc":"快一點","sc":"快一点"},"d":{"es":"快一點 = ¡date prisa! (petición o mandato suave).","en":"快一點 is a gentle urging: 'hurry up'.","tc":"「快一點」是催促的說法，語氣比較柔和，意思是動作快一點。","sc":"「快一点」是催促的说法，语气比较柔和，意思是动作快一点。"},"ex":[{"c":"快一點，我們要遲到了。","s":"快一点，我们要迟到了。","es":"Apúrate, vamos a llegar tarde.","en":"Hurry up, we're going to be late."}]},{"id":"2-12-2","b":2,"l":12,"k":"","t":{"es":"Mencionar con 起","en":"Verb Particle 起 qǐ to touch upon","ens":"Verb Particle 起 qǐ to touch upon","tc":"V＋起（談起、提起）","sc":"V＋起（谈起、提起）"},"d":{"es":"V + 起 (談起, 提起, 說起, 想起) = empezar a mencionar un tema.","en":"V + 起 (談起, 提起, 說起) means to begin mentioning a topic.","tc":"「V＋起」，例如談起、提起、說起，表示開始提到某個話題。","sc":"「V＋起」，例如谈起、提起、说起，表示开始提到某个话题。"},"ex":[{"c":"他常常談起他的家人。","s":"他常常谈起他的家人。","es":"Habla a menudo de su familia.","en":"He often talks about his family."}]},{"id":"2-12-3","b":2,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Con tal de que 只要…就","en":"只要 zhǐyào……就 jiù… …as long as…","ens":"只要 zhǐyào……就 jiù… …as long as…","tc":"只要…就…","sc":"只要…就…"},"d":{"es":"只要 A 就 B = con tal de que A, B (A es condición suficiente).","en":"只要 A 就 B means 'as long as A, then B' (A is a sufficient condition).","tc":"「只要 A 就 B」表示只需要 A 這個條件，就會有 B。","sc":"「只要 A 就 B」表示只需要 A 这个条件，就会有 B。"},"ex":[{"c":"只要你努力，就會成功。","s":"只要你努力，就会成功。","es":"Con tal de que te esfuerces, tendrás éxito.","en":"As long as you work hard, you will succeed."}]},{"id":"2-12-4","b":2,"l":12,"k":"","t":{"es":"Cuanto más… con 越…越","en":"越 yuè…越 yuè…the more…, the more…","ens":"越 yuè…越 yuè…the more…, the more…","tc":"越…越…","sc":"越…越…"},"d":{"es":"越 A 越 B = cuanto más A, más B.","en":"越 A 越 B means 'the more A, the more B'.","tc":"「越 A 越 B」表示 A 的程度增加，B 也跟著增加。","sc":"「越 A 越 B」表示 A 的程度增加，B 也跟着增加。"},"ex":[{"c":"他越說越快。","s":"他越说越快。","es":"Cuanto más habla, más rápido habla.","en":"The more he talks, the faster he gets."}]},{"id":"2-12-5","b":2,"l":12,"k":"","t":{"es":"Tema de contraste","en":"Topic as Contrastive","ens":"Topic as Contrastive","tc":"對比的主題","sc":"对比的主题"},"d":{"es":"Un tema al inicio sirve para contrastar con otro: «en cuanto a A…, pero B…».","en":"Putting a topic at the start of the sentence sets up a contrast: 'as for A…, but B…'.","tc":"把一個主題放在句子開頭，用來和另一件事對比：就 A 來說……，可是 B……。","sc":"把一个主题放在句子开头，用来和另一件事对比：就 A 来说……，可是 B……。"},"ex":[{"c":"中文我會說，可是不會寫。","s":"中文我会说，可是不会写。","es":"El chino sí sé hablarlo, pero no sé escribirlo.","en":"I can speak Chinese, but I can't write it."}]},{"id":"2-13-0","b":2,"l":13,"k":"pasado completado terminado past completed finished perfective 完成 過去 experiencia alguna vez haber experience ever 經驗 經歷 pasado completado terminado past completed finished perfective 完成 过去 experiencia alguna vez haber experience ever 经验 经历","t":{"es":"Haber terminado con 過","en":"Completion of Action with V+過 guò","ens":"Completion of Action with V+过 guò","tc":"V＋過（完成）","sc":"V＋过（完成）"},"d":{"es":"V + 過 también indica que ya terminó de hacer algo (acción completada). Se usa sobre todo en preguntas: 吃過飯了嗎？","en":"V + 過 can also mean that an action has already been completed, mostly in questions: 吃過飯了嗎？","tc":"「V＋過」也可以表示已經做完某件事，多用在問句，例如「吃過飯了嗎？」","sc":"「V＋过」也可以表示已经做完某件事，多用在问句，例如「吃过饭了吗？」"},"ex":[{"c":"你吃過飯了嗎？","s":"你吃过饭了吗？","es":"¿Ya comiste?","en":"Have you eaten yet?"}]},{"id":"2-13-1","b":2,"l":13,"k":"","t":{"es":"Alejarse con 走","en":"Verb Particle 走 zǒu away","ens":"Verb Particle 走 zǒu away","tc":"V＋走","sc":"V＋走"},"d":{"es":"V + 走 = llevarse, irse (alejarse): 拿走, 帶走, 開走.","en":"V + 走 means taking away or leaving: 拿走, 帶走, 開走.","tc":"「V＋走」表示離開或被帶走，例如拿走、帶走、開走。","sc":"「V＋走」表示离开或被带走，例如拿走、带走、开走。"},"ex":[{"c":"他把我的書拿走了。","s":"他把我的书拿走了。","es":"Se llevó mi libro.","en":"He took my book away."}]},{"id":"2-13-2","b":2,"l":13,"k":"","t":{"es":"Mandar con 叫","en":"Imperative Sentences with 叫 jiào","ens":"Imperative Sentences with 叫 jiào","tc":"叫（命令、要求）","sc":"叫（命令、要求）"},"d":{"es":"A 叫 B + verbo = A manda o pide a B que haga algo.","en":"A 叫 B + verb means A tells / asks B to do something.","tc":"「A 叫 B ＋動詞」表示 A 要求或命令 B 去做某件事。","sc":"「A 叫 B ＋动词」表示 A 要求或命令 B 去做某件事。"},"ex":[{"c":"老師叫我們寫作業。","s":"老师叫我们写作业。","es":"El profesor nos pide hacer la tarea.","en":"The teacher asks us to do the homework."}]},{"id":"2-13-3","b":2,"l":13,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Dejar de con 別再…了","en":"別再 bié zài…了 le stop doing it","ens":"别再 bié zài…了 le stop doing it","tc":"別再…了","sc":"别再…了"},"d":{"es":"別再 + verbo + 了 = no lo vuelvas a hacer / deja de hacerlo.","en":"別再 + verb + 了 means 'don't do it again / stop doing it'.","tc":"「別再＋動詞＋了」表示不要再重複做，或叫對方停止。","sc":"「别再＋动词＋了」表示不要再重复做，或叫对方停止。"},"ex":[{"c":"你別再玩手機了。","s":"你别再玩手机了。","es":"Deja de jugar con el celular.","en":"Stop playing with your phone."}]},{"id":"2-13-4","b":2,"l":13,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Seguridad con 會…的","en":"To offer assurance with 會 huì…的 de…","ens":"To offer assurance with 会 huì…的 de…","tc":"會…的（保證）","sc":"会…的（保证）"},"d":{"es":"會…的 expresa seguridad o promesa sobre el futuro: «seguro que…».","en":"會…的 expresses confidence about the future, with a reassuring tone: 'surely…'.","tc":"「會……的」表示說話的人很確定未來會發生，有保證、安慰的語氣。","sc":"「会……的」表示说话的人很确定未来会发生，有保证、安慰的语气。"},"ex":[{"c":"你放心，他會來的。","s":"你放心，他会来的。","es":"Tranquilo, seguro que viene.","en":"Don't worry, he will come."}]},{"id":"2-13-5","b":2,"l":13,"k":"","t":{"es":"Por medio de 透過","en":"透過 tòuguò… by means of…","ens":"透过 tòuguò… by means of…","tc":"透過","sc":"透过"},"d":{"es":"透過 + medio o persona = por medio de, a través de.","en":"透過 + means or person means 'through, by means of'.","tc":"「透過＋方法或人」表示經由某個管道或人。","sc":"「透过＋方法或人」表示经由某个管道或人。"},"ex":[{"c":"我是透過朋友認識他的。","s":"我是透过朋友认识他的。","es":"Lo conocí por medio de un amigo.","en":"I met him through a friend."}]},{"id":"2-13-6","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"才…就…","en":"才 cái…就 jiù… only just…, and…already","ens":"才 cái…就 jiù… only just…, and…already","tc":"才…就…","sc":"才…就…"},"d":{"es":"A 才 B 就 C = apenas A y ya B: algo ocurrió muy pronto.","en":"A 才 B 就 C means 'barely A and already B': something happened very soon.","tc":"「A 才 B 就 C」表示剛剛 A，很快就 B，表示事情發生得很快。","sc":"「A 才 B 就 C」表示刚刚 A，很快就 B，表示事情发生得很快。"},"ex":[{"c":"他才來一個月就學會了。","s":"他才来一个月就学会了。","es":"Apenas llevaba un mes y ya aprendió.","en":"He had been here only a month and had already learned it."}]},{"id":"2-13-7","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 siempre nunca frecuencia always never frequency 經常 從來 tiempo momento orden secuencia time order sequence 时间 顺序 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Frecuencia con 每","en":"Frequency with 每 měi + Time Expression","ens":"Frequency with 每 měi + Time Expression","tc":"每＋時間＋次數","sc":"每＋时间＋次数"},"d":{"es":"每 + tiempo + frecuencia = tantas veces cada…","en":"每 + time + frequency means how many times something happens in each period.","tc":"「每＋時間＋次數」表示在固定的時間裡做幾次。","sc":"「每＋时间＋次数」表示在固定的时间里做几次。"},"ex":[{"c":"我每個星期游泳兩次。","s":"我每个星期游泳两次。","es":"Nado dos veces por semana.","en":"I swim twice a week."}]},{"id":"2-13-8","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Solo si con 只有…才","en":"只有 zhǐyǒu…，才 cái… cannot …, unless…","ens":"只有 zhǐyǒu…，才 cái… cannot …, unless…","tc":"只有…才…","sc":"只有…才…"},"d":{"es":"只有 A 才 B = solo si A, B (A es condición necesaria).","en":"只有 A 才 B means 'only if A, then B' (A is a necessary condition).","tc":"「只有 A 才 B」表示 A 是唯一的條件，沒有 A 就不會有 B。","sc":"「只有 A 才 B」表示 A 是唯一的条件，没有 A 就不会有 B。"},"ex":[{"c":"只有多練習，才能說得好。","s":"只有多练习，才能说得好。","es":"Solo practicando mucho se puede hablar bien.","en":"Only with lots of practice can you speak well."}]},{"id":"2-14-0","b":2,"l":14,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"A punto de con 就要…了","en":"就要 jiù yào…了 le will soon…","ens":"就要 jiù yào…了 le will soon…","tc":"就要…了","sc":"就要…了"},"d":{"es":"就要 + verbo + 了 = estar a punto de. Es más cercano que 快…了.","en":"就要 + verb + 了 means 'about to happen', closer in time than 快…了.","tc":"「就要＋動詞＋了」表示馬上就要發生，比「快……了」更近。","sc":"「就要＋动词＋了」表示马上就要发生，比「快……了」更近。"},"ex":[{"c":"火車就要開了。","s":"火车就要开了。","es":"El tren está por salir.","en":"The train is about to leave."}]},{"id":"2-14-1","b":2,"l":14,"k":"","t":{"es":"Hablando de con 說到","en":"說到 shuōdào/談到 tándào… talking of…","ens":"说到 shuōdào/谈到 tándào… talking of…","tc":"說到／談到","sc":"说到／谈到"},"d":{"es":"說到 / 談到 + tema = hablando de…, cuando se trata de…","en":"說到 / 談到 + topic means 'speaking of…, when it comes to…'.","tc":"「說到／談到＋話題」表示說起某個話題的時候。","sc":"「说到／谈到＋话题」表示说起某个话题的时候。"},"ex":[{"c":"說到台灣小吃，我最喜歡滷肉飯。","s":"说到台湾小吃，我最喜欢卤肉饭。","es":"Hablando de comida callejera de Taiwán, lo que más me gusta es el lu rou fan.","en":"Speaking of Taiwanese street food, my favorite is braised pork rice."}]},{"id":"2-14-2","b":2,"l":14,"k":"","t":{"es":"對A有B","en":"對 duìA 有 yǒu B to be B in A","ens":"对 duìA 有 yǒu B to be B in A","tc":"對…有…","sc":"对…有…"},"d":{"es":"對 A 有 B = hacia A hay B (efecto o sentimiento): 對…有幫助 / 有興趣 / 有信心.","en":"對 A 有 B means B (an effect or feeling) toward A: 對…有幫助 / 有興趣 / 有信心.","tc":"「對 A 有 B」表示對 A 有某種影響或感覺，例如對……有幫助、有興趣、有信心。","sc":"「对 A 有 B」表示对 A 有某种影响或感觉，例如对……有帮助、有兴趣、有信心。"},"ex":[{"c":"運動對身體有幫助。","s":"运动对身体有帮助。","es":"Hacer ejercicio ayuda al cuerpo.","en":"Exercise is good for your body."}]},{"id":"2-14-3","b":2,"l":14,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Incluso con 連…都","en":"連 lián…都 dōu… even","ens":"连 lián…都 dōu… even","tc":"連…都…","sc":"连…都…"},"d":{"es":"連 A 都 B = incluso A también B. A es el caso extremo.","en":"連 A 都 B means 'even A is B'. A is the extreme case.","tc":"「連 A 都 B」表示連 A 這麼極端的情況也是 B。","sc":"「连 A 都 B」表示连 A 这么极端的情况也是 B。"},"ex":[{"c":"他連飯都沒吃就走了。","s":"他连饭都没吃就走了。","es":"Se fue sin siquiera comer.","en":"He left without even eating."}]},{"id":"2-14-4","b":2,"l":14,"k":"negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo con 不但…而且","en":"不但 búdàn…，而且 érqiě… not only…but also…","ens":"不但 búdàn…，而且 érqiě… not only…but also…","tc":"不但…，而且…","sc":"不但…，而且…"},"d":{"es":"不但 A，而且 B = no solo A sino también B.","en":"不但 A，而且 B means 'not only A but also B'.","tc":"「不但 A，而且 B」表示不只 A，還有 B。","sc":"「不但 A，而且 B」表示不只 A，还有 B。"},"ex":[{"c":"他不但會說中文，而且說得很好。","s":"他不但会说中文，而且说得很好。","es":"No solo habla chino, sino que lo habla muy bien.","en":"Not only can he speak Chinese, he speaks it very well."}]},{"id":"2-14-5","b":2,"l":14,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"把 sin querer","en":"Unintentional 把 bǎ Construction","ens":"Unintentional 把 bǎ Construction","tc":"把（非故意）","sc":"把（非故意）"},"d":{"es":"把 + objeto + verbo + complemento puede expresar algo hecho sin querer (un accidente): 弄丟, 弄壞, 忘.","en":"把 + object + verb + complement can also describe something done unintentionally, such as 弄丟, 弄壞, 忘.","tc":"「把＋東西＋動詞＋補語」也可以表示不是故意做的事，例如弄丟、弄壞、忘了。","sc":"「把＋东西＋动词＋补语」也可以表示不是故意做的事，例如弄丢、弄坏、忘了。"},"ex":[{"c":"我把鑰匙弄丟了。","s":"我把钥匙弄丢了。","es":"Perdí las llaves.","en":"I lost my keys."}]},{"id":"2-15-0","b":2,"l":15,"k":"","t":{"es":"Hasta con 到","en":"Post-verbal Preposition 到 dào upto, till","ens":"Post-verbal Preposition 到 dào upto, till","tc":"V＋到（時間、地點）","sc":"V＋到（时间、地点）"},"d":{"es":"V + 到 + tiempo / lugar = hasta (el límite de una acción).","en":"V + 到 + time / place means 'until / up to' (the limit of the action).","tc":"「V＋到＋時間或地點」表示動作持續到某個時間或地點為止。","sc":"「V＋到＋时间或地点」表示动作持续到某个时间或地点为止。"},"ex":[{"c":"我昨天工作到十二點。","s":"我昨天工作到十二点。","es":"Ayer trabajé hasta las doce.","en":"I worked until twelve o'clock yesterday."}]},{"id":"2-15-1","b":2,"l":15,"k":"","t":{"es":"De uno en uno con 一M一M","en":"Manner 一 M 一 M one at a time","ens":"Manner 一 M 一 M one at a time","tc":"一M一M","sc":"一M一M"},"d":{"es":"一 + clasificador + 一 + clasificador = de uno en uno, poco a poco (manera).","en":"一 + measure word + 一 + measure word means 'one by one' or 'bit by bit'.","tc":"「一＋量詞＋一＋量詞」表示一個接著一個，例如一個一個、一口一口。","sc":"「一＋量词＋一＋量词」表示一个接着一个，例如一个一个、一口一口。"},"ex":[{"c":"請大家一個一個說。","s":"请大家一个一个说。","es":"Por favor hablen uno por uno.","en":"Please speak one by one."}]},{"id":"2-15-2","b":2,"l":15,"k":"","t":{"es":"Cada vez más con 一M比一M","en":"Intensifying a State with 一 M 一 M more and more X; more X than the last…","ens":"Intensifying a State with 一 M 一 M more and more X; more X than the last…","tc":"一M比一M＋形容詞","sc":"一M比一M＋形容词"},"d":{"es":"一 + clasificador + 比 + 一 + clasificador + adjetivo = cada vez más…","en":"一 + measure word + 比 + 一 + measure word + adjective means 'more and more…'.","tc":"「一＋量詞＋比＋一＋量詞＋形容詞」表示越來越……。","sc":"「一＋量词＋比＋一＋量词＋形容词」表示越来越……。"},"ex":[{"c":"天氣一天比一天冷。","s":"天气一天比一天冷。","es":"Cada día hace más frío.","en":"It gets colder day by day."}]},{"id":"2-15-3","b":2,"l":15,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Empezar con 起來","en":"Inchoative Meaning with 起來 qǐlái","ens":"Inchoative Meaning with 起来 qǐlái","tc":"V／形容詞＋起來（開始）","sc":"V／形容词＋起来（开始）"},"d":{"es":"V / adjetivo + 起來 = empezar a (inicio de una acción o estado).","en":"Verb / adjective + 起來 means starting an action or a state.","tc":"「動詞或形容詞＋起來」表示開始出現某個動作或狀態。","sc":"「动词或形容词＋起来」表示开始出现某个动作或状态。"},"ex":[{"c":"她突然哭起來。","s":"她突然哭起来。","es":"De pronto se puso a llorar.","en":"She suddenly started to cry."},{"c":"天氣冷起來了。","s":"天气冷起来了。","es":"Empezó a hacer frío.","en":"It is getting cold."}]},{"id":"2-15-4","b":2,"l":15,"k":"","t":{"es":"Frases de cuatro caracteres","en":"Four-character Phrases 四字格 sìzìgé","ens":"Four-character Phrases 四字格 sìzìgé","tc":"四字格","sc":"四字格"},"d":{"es":"Las expresiones de cuatro caracteres (四字格) condensan una idea y se usan como una unidad fija.","en":"Four-character phrases (四字格) are fixed expressions that express an idea concisely. Learn them as a unit.","tc":"四字格是由四個字組成的固定說法，用來簡短表達一個意思，要當成一個整體來記。","sc":"四字格是由四个字组成的固定说法，用来简短表达一个意思，要当成一个整体来记。"},"ex":[{"c":"這次考試我考得馬馬虎虎。","s":"这次考试我考得马马虎虎。","es":"En este examen me fue así así.","en":"I did so-so on this exam."}]},{"id":"3-1-0","b":3,"l":1,"k":"condicional condición si conditional condition if 條件 假設 如果 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Si…: …的話","en":"…的話 if, supposing","ens":"…的话 if, supposing","tc":"…的話","sc":"…的话"},"d":{"es":"A 的話，B = si A, entonces B (condicional coloquial). Se combina con 如果 / 要是.","en":"A 的話，B = if A, then B (colloquial conditional). Often used with 如果 or 要是.","tc":"A 的話，B：如果 A 發生，就 B。口語常和「如果」「要是」一起用。","sc":"A 的话，B：如果 A 发生，就 B。口语常和「如果」「要是」一起用。"},"ex":[{"c":"如果你有空的話，我們一起去吧。","s":"如果你有空的话，我们一起去吧。","es":"Si tienes tiempo, vamos juntos.","en":"If you have time, let's go together."}]},{"id":"3-1-1","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Menos de: 不到","en":"不到 less than","ens":"不到 less than","tc":"不到","sc":"不到"},"d":{"es":"不到 + cantidad = menos de.","en":"不到 + quantity = less than that amount.","tc":"不到＋數量：比那個數量還少。","sc":"不到＋数量：比那个数量还少。"},"ex":[{"c":"我等了不到十分鐘。","s":"我等了不到十分钟。","es":"Esperé menos de diez minutos.","en":"I waited less than ten minutes."}]},{"id":"3-1-2","b":3,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por poco: 差一點","en":"差一點（就）… almost","ens":"差一点（就）… almost","tc":"差一點","sc":"差一点"},"d":{"es":"差一點(就) + verbo = por poco ocurre (pero no ocurrió).","en":"差一點(就) + verb = almost happened, but in the end did not.","tc":"差一點(就)＋動詞：幾乎發生，但最後沒發生。","sc":"差一点(就)＋动词：几乎发生，但最后没发生。"},"ex":[{"c":"我差一點就遲到了。","s":"我差一点就迟到了。","es":"Por poco llego tarde.","en":"I almost was late."}]},{"id":"3-1-3","b":3,"l":1,"k":"","t":{"es":"Me temo que: 恐怕","en":"恐怕… probably","ens":"恐怕… probably","tc":"恐怕","sc":"恐怕"},"d":{"es":"恐怕 = me temo que, probablemente (sobre algo desfavorable).","en":"恐怕 = I'm afraid that…, probably (about something undesirable).","tc":"恐怕：擔心或推測不太好的事情可能會發生，意思是「我怕…」。","sc":"恐怕：担心或推测不太好的事情可能会发生，意思是「我怕…」。"},"ex":[{"c":"恐怕要下雨了。","s":"恐怕要下雨了。","es":"Me temo que va a llover.","en":"I'm afraid it's going to rain."}]},{"id":"3-1-4","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Por fin: 好不容易","en":"好不容易 finally managed to","ens":"好不容易 finally managed to","tc":"好不容易","sc":"好不容易"},"d":{"es":"好不容易 = con mucha dificultad, por fin logró.","en":"好不容易(才) = after great difficulty, finally managed to.","tc":"好不容易（才）：經過很多困難，終於做到。","sc":"好不容易（才）：经过很多困难，终于做到。"},"ex":[{"c":"我好不容易才買到票。","s":"我好不容易才买到票。","es":"Con mucho trabajo por fin conseguí el boleto.","en":"After a lot of trouble I finally managed to get the ticket."}]},{"id":"3-1-5","b":3,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Decir y hacer: 說…就…","en":"Instantly without Prior Warning with 說…就…","ens":"Instantly without Prior Warning with 说…就…","tc":"說…就…","sc":"说…就…"},"d":{"es":"說 A 就 A = hacer algo en cuanto se dice, sin previo aviso.","en":"說 A 就 A = does it right away as soon as it's said, with no warning.","tc":"說 A 就 A：一說就馬上做，沒有任何預告。","sc":"说 A 就 A：一说就马上做，没有任何预告。"},"ex":[{"c":"他說走就走。","s":"他说走就走。","es":"Dijo que se iba y se fue de inmediato.","en":"He said he was leaving and left right away."}]},{"id":"3-1-6","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No importa: 不管…都","en":"不管…都 … regardless of whether or not","ens":"不管…都 … regardless of whether or not","tc":"不管…都…","sc":"不管…都…"},"d":{"es":"不管 + pregunta u opciones，都… = no importa…, siempre…","en":"不管 + question or alternatives, 都 + result = no matter what, the result is the same.","tc":"不管＋疑問或選項，都＋結果：不論情況怎麼樣，結果都一樣。","sc":"不管＋疑问或选项，都＋结果：不论情况怎么样，结果都一样。"},"ex":[{"c":"不管天氣好不好，他都去爬山。","s":"不管天气好不好，他都去爬山。","es":"Haga o no haga buen tiempo, él va a la montaña.","en":"Whether the weather is good or not, he goes hiking."}]},{"id":"3-2-0","b":3,"l":2,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"En general: 一般來說","en":"一般來說 generally speaking","ens":"一般来说 generally speaking","tc":"一般來說","sc":"一般来说"},"d":{"es":"一般來說 = en general, por lo común.","en":"一般來說 = generally, usually (not necessarily every time).","tc":"一般來說：通常的情況是…，不一定每次都這樣。","sc":"一般来说：通常的情况是…，不一定每次都这样。"},"ex":[{"c":"一般來說，學生都很忙。","s":"一般来说，学生都很忙。","es":"En general, los estudiantes están ocupados.","en":"Generally speaking, students are all busy."}]},{"id":"3-2-1","b":3,"l":2,"k":"","t":{"es":"Verbo comodín: 弄","en":"General Verb 弄","ens":"General Verb 弄","tc":"弄","sc":"弄"},"d":{"es":"弄 es un verbo comodín: «hacer, arreglar, estropear» según el complemento: 弄壞, 弄髒, 弄好.","en":"弄 is an all-purpose verb; its meaning depends on the complement: 弄壞 (break), 弄髒 (dirty), 弄好 (fix).","tc":"「弄」是萬用動詞，意思會跟著後面的補語變，例如弄壞、弄髒、弄好。","sc":"「弄」是万用动词，意思会跟着后面的补语变，例如弄坏、弄脏、弄好。"},"ex":[{"c":"我把手機弄壞了。","s":"我把手机弄坏了。","es":"Descompuse mi celular.","en":"I broke my phone."}]},{"id":"3-2-2","b":3,"l":2,"k":"tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"Además: 再說","en":"再說 besides, moreover","ens":"再说 besides, moreover","tc":"再說","sc":"再说"},"d":{"es":"再說 = además, y por si fuera poco (añade otra razón).","en":"再說 = besides, what's more (adds another reason).","tc":"再說：再補充一個理由，意思是「而且」「何況」。","sc":"再说：再补充一个理由，意思是「而且」「何况」。"},"ex":[{"c":"太晚了，再說我也累了，明天再去吧。","s":"太晚了，再说我也累了，明天再去吧。","es":"Es muy tarde, además estoy cansado; vamos mañana.","en":"It's too late, and besides I'm tired too; let's go tomorrow."}]},{"id":"3-2-3","b":3,"l":2,"k":"","t":{"es":"Convertir en: V成","en":"V+成 to become, to turn into","ens":"V+成 to become, to turn into","tc":"V成","sc":"V成"},"d":{"es":"V + 成 = convertir, resultar en: 變成, 寫成, 翻成.","en":"Verb + 成 = turn into, convert to: 變成, 寫成, 翻成.","tc":"動詞＋成：表示變成、轉換成另一種東西，例如變成、寫成、翻成。","sc":"动词＋成：表示变成、转换成另一种东西，例如变成、写成、翻成。"},"ex":[{"c":"請把這句話翻成中文。","s":"请把这句话翻成中文。","es":"Por favor traduce esta frase al chino.","en":"Please translate this sentence into Chinese."}]},{"id":"3-2-4","b":3,"l":2,"k":"","t":{"es":"En realidad no: 並","en":"Contrary to Expectation with 並","ens":"Contrary to Expectation with 并","tc":"並不／並沒有","sc":"并不／并没有"},"d":{"es":"並 + 不 / 沒 = en realidad no. Refuerza una negación contraria a lo que se esperaba.","en":"並 + 不/沒 = actually not; strengthens a negation that goes against expectations.","tc":"並＋不／沒：加強否定，表示事實跟想像或預期不一樣。","sc":"并＋不／没：加强否定，表示事实跟想像或预期不一样。"},"ex":[{"c":"這件事並不難。","s":"这件事并不难。","es":"Este asunto en realidad no es difícil.","en":"This matter is actually not difficult."}]},{"id":"3-2-5","b":3,"l":2,"k":"","t":{"es":"Sobre todo: 尤其是","en":"尤其是 especially","ens":"尤其是 especially","tc":"尤其是","sc":"尤其是"},"d":{"es":"尤其是 = especialmente. Destaca un caso dentro de un grupo.","en":"尤其是 = especially; singles out one case within a group.","tc":"尤其是：在一群裡特別強調其中一個。","sc":"尤其是：在一群里特别强调其中一个。"},"ex":[{"c":"我喜歡水果，尤其是芒果。","s":"我喜欢水果，尤其是芒果。","es":"Me gustan las frutas, sobre todo el mango.","en":"I like fruit, especially mango."}]},{"id":"3-2-6","b":3,"l":2,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No hay remedio: 只好","en":"Concession with 只好 could only, have no choice but to","ens":"Concession with 只好 could only, have no choice but to","tc":"只好","sc":"只好"},"d":{"es":"只好 + verbo = no queda más remedio que…","en":"只好 + verb = have no choice but to.","tc":"只好＋動詞：沒有別的辦法，只能這樣做。","sc":"只好＋动词：没有别的办法，只能这样做。"},"ex":[{"c":"沒有車，我們只好走路去。","s":"没有车，我们只好走路去。","es":"No hay coche, así que no nos queda más que ir caminando.","en":"There's no car, so we have no choice but to walk."}]},{"id":"3-3-0","b":3,"l":3,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Influido por: 受到…影響","en":"受到…的影響 to be influenced by, affected by","ens":"受到…的影响 to be influenced by, affected by","tc":"受到…的影響","sc":"受到…的影响"},"d":{"es":"受到 + X + 的影響 = ser influenciado por X.","en":"受到 + X + 的影響 = to be influenced by X.","tc":"受到＋人事物＋的影響：被某人或某事影響。","sc":"受到＋人事物＋的影响：被某人或某事影响。"},"ex":[{"c":"他受到爸爸的影響，也喜歡音樂。","s":"他受到爸爸的影响，也喜欢音乐。","es":"Influido por su papá, a él también le gusta la música.","en":"Influenced by his dad, he likes music too."}]},{"id":"3-3-1","b":3,"l":3,"k":"","t":{"es":"Menos mal: 幸虧","en":"幸虧… fortunately…","ens":"幸亏… fortunately…","tc":"幸虧","sc":"幸亏"},"d":{"es":"幸虧 A，B = por suerte A, (de lo contrario habría pasado algo malo).","en":"幸虧 A, B = fortunately A (otherwise something bad would have happened).","tc":"幸虧 A，B：因為有 A 這個好運，才沒有發生不好的事。","sc":"幸亏 A，B：因为有 A 这个好运，才没有发生不好的事。"},"ex":[{"c":"幸虧你提醒我，不然我忘了。","s":"幸亏你提醒我，不然我忘了。","es":"Menos mal que me lo recordaste, si no, lo habría olvidado.","en":"Luckily you reminded me, otherwise I would have forgotten."}]},{"id":"3-3-2","b":3,"l":3,"k":"","t":{"es":"Se puede considerar: 算是","en":"算是… can be considered…","ens":"算是… can be considered…","tc":"算是","sc":"算是"},"d":{"es":"算是 = se puede considerar (aunque no del todo).","en":"算是 = can be considered (though not entirely).","tc":"算是：雖然不是百分之百，但可以這樣看。","sc":"算是：虽然不是百分之百，但可以这样看。"},"ex":[{"c":"這家店算是很有名的。","s":"这家店算是很有名的。","es":"Esta tienda se puede considerar muy famosa.","en":"This shop can be considered quite famous."}]},{"id":"3-3-3","b":3,"l":3,"k":"","t":{"es":"Sí que: 是…","en":"是… It is indeed true that…","ens":"是… It is indeed true that…","tc":"是（強調）","sc":"是（强调）"},"d":{"es":"是 acentuado antes de un adjetivo o verbo confirma algo: «sí que», «en efecto».","en":"A stressed 是 before an adjective or verb confirms something: 'indeed', 'it's true that'.","tc":"「是」放在形容詞或動詞前面，要重讀，表示確認、承認「的確如此」。","sc":"「是」放在形容词或动词前面，要重读，表示确认、承认「的确如此」。"},"ex":[{"c":"他是很聰明。","s":"他是很聪明。","es":"Es cierto que es muy inteligente.","en":"He is indeed very smart."}]},{"id":"3-3-4","b":3,"l":3,"k":"","t":{"es":"Con razón: 難怪","en":"難怪 no wonder","ens":"难怪 no wonder","tc":"難怪","sc":"难怪"},"d":{"es":"難怪 = con razón, no es de extrañar (ahora se entiende la causa).","en":"難怪 = no wonder; now the cause is understood, the result makes sense.","tc":"難怪：知道原因後，覺得結果不奇怪了。","sc":"难怪：知道原因后，觉得结果不奇怪了。"},"ex":[{"c":"他是台灣人，難怪中文說得這麼好。","s":"他是台湾人，难怪中文说得这么好。","es":"Es taiwanés, con razón habla tan bien chino.","en":"He's Taiwanese, no wonder he speaks Chinese so well."}]},{"id":"3-3-5","b":3,"l":3,"k":"","t":{"es":"Muchísimo: …死了","en":"A Post-verbal Intensifier 死了 terribly","ens":"A Post-verbal Intensifier 死了 terribly","tc":"…死了","sc":"…死了"},"d":{"es":"Adjetivo / verbo + 死了 = muchísimo (coloquial, para sensaciones intensas).","en":"Adj/verb + 死了 = extremely (colloquial, for strong feelings).","tc":"形容詞或動詞＋死了：非常、極了，口語，多用在強烈的感覺。","sc":"形容词或动词＋死了：非常、极了，口语，多用在强烈的感觉。"},"ex":[{"c":"我累死了。","s":"我累死了。","es":"Estoy muertísimo de cansancio.","en":"I'm dead tired."}]},{"id":"3-3-6","b":3,"l":3,"k":"","t":{"es":"Casi: 幾乎","en":"幾乎 almost","ens":"几乎 almost","tc":"幾乎","sc":"几乎"},"d":{"es":"幾乎 = casi (casi todo, casi siempre, casi ocurre).","en":"幾乎 = almost (almost all, almost every day).","tc":"幾乎：差不多、將近，例如幾乎全部、幾乎每天。","sc":"几乎：差不多、将近，例如几乎全部、几乎每天。"},"ex":[{"c":"他幾乎每天都來。","s":"他几乎每天都来。","es":"Viene casi todos los días.","en":"He comes almost every day."}]},{"id":"3-3-7","b":3,"l":3,"k":"","t":{"es":"Algo, un poco: 多少","en":"多少 somewhat","ens":"多少 somewhat","tc":"多少","sc":"多少"},"d":{"es":"多少 + verbo / adjetivo = en alguna medida, algo, aunque sea un poco.","en":"多少 + verb/adjective = to some extent, at least a little.","tc":"多少＋動詞或形容詞：多多少少、至少有一點。","sc":"多少＋动词或形容词：多多少少、至少有一点。"},"ex":[{"c":"他多少知道一點。","s":"他多少知道一点。","es":"Algo sabe, aunque sea un poco.","en":"He knows a little, at least."}]},{"id":"3-3-8","b":3,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por más que: 再…也","en":"再…也… no matter how…, still…","ens":"再…也… no matter how…, still…","tc":"再…也…","sc":"再…也…"},"d":{"es":"再 + adjetivo / verbo + 也 = por más… que sea, aun así…","en":"再 + adjective/verb + 也 = no matter how…, still…","tc":"再＋形容詞或動詞＋也：就算程度很高，結果還是一樣。","sc":"再＋形容词或动词＋也：就算程度很高，结果还是一样。"},"ex":[{"c":"再忙我也要吃早餐。","s":"再忙我也要吃早餐。","es":"Por muy ocupado que esté, desayuno.","en":"No matter how busy I am, I eat breakfast."}]},{"id":"3-4-0","b":3,"l":4,"k":"negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo…también: 不但…還","en":"不但…，還… not only…, but also","ens":"不但…，还… not only…, but also","tc":"不但…，還…","sc":"不但…，还…"},"d":{"es":"不但 A，還 B = no solo A, también B.","en":"不但 A，還 B = not only A, but also B.","tc":"不但 A，還 B：除了 A 以外，還有 B。","sc":"不但 A，还 B：除了 A 以外，还有 B。"},"ex":[{"c":"他不但會唱歌，還會跳舞。","s":"他不但会唱歌，还会跳舞。","es":"No solo canta, también baila.","en":"He can not only sing but also dance."}]},{"id":"3-4-1","b":3,"l":4,"k":"","t":{"es":"Hablar: 說 vs 談","en":"Speak 說 vs Talk 談","ens":"Speak 说 vs Talk 谈","tc":"說 vs 談","sc":"说 vs 谈"},"d":{"es":"說 = decir o hablar (producir palabras). 談 = conversar o discutir un tema con intercambio.","en":"說 = to say or speak (produce words); 談 = to talk over or discuss a topic back and forth.","tc":"「說」是把話說出口；「談」是就某個主題互相交談、討論。","sc":"「说」是把话说出口；「谈」是就某个主题互相交谈、讨论。"},"ex":[{"c":"他說中文。","s":"他说中文。","es":"Habla chino.","en":"He speaks Chinese."},{"c":"我們談一談這個問題。","s":"我们谈一谈这个问题。","es":"Hablemos de este problema.","en":"Let's talk about this problem."}]},{"id":"3-4-2","b":3,"l":4,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No es…sino: 不是…而是","en":"…不是…，而是… not…; rather…","ens":"…不是…，而是… not…; rather…","tc":"不是…，而是…","sc":"不是…，而是…"},"d":{"es":"不是 A，而是 B = no es A, sino B.","en":"不是 A，而是 B = it's not A, but B.","tc":"不是 A，而是 B：不是 A，真正的是 B。","sc":"不是 A，而是 B：不是 A，真正的是 B。"},"ex":[{"c":"他不是不想去，而是沒時間。","s":"他不是不想去，而是没时间。","es":"No es que no quiera ir, es que no tiene tiempo.","en":"It's not that he doesn't want to go; he has no time."}]},{"id":"3-4-3","b":3,"l":4,"k":"negación negar negativa negation negative 否定 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 dirección movimiento direction movement 方向 趨向 siempre nunca frecuencia always never frequency 經常 從來 negación negar negativa negation negative 否定 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 dirección movimiento direction movement 方向 趋向 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Nunca: 從來","en":"從來+Negation never","ens":"从来+Negation never","tc":"從來","sc":"从来"},"d":{"es":"從來 + 不 / 沒 (有) = nunca, jamás (hasta ahora).","en":"從來 + 不/沒 = never, not once up to now.","tc":"從來＋不／沒：到現在都沒有過。","sc":"从来＋不／没：到现在都没有过。"},"ex":[{"c":"我從來沒吃過榴槤。","s":"我从来没吃过榴梿。","es":"Nunca he comido durián.","en":"I've never eaten durian."}]},{"id":"3-4-4","b":3,"l":4,"k":"","t":{"es":"Verbo 上: 上課, 上班","en":"Various Meanings of the Verb 上","ens":"Various Meanings of the Verb 上","tc":"動詞「上」","sc":"动词「上」"},"d":{"es":"上 tiene varios sentidos como verbo: 上課, 上班, 上網, 上車 (empezar o ir a una actividad, subir).","en":"上 has several senses as a verb: 上課, 上班, 上網, 上車 (start or go to an activity, get on a vehicle).","tc":"「上」有很多用法，像上課、上班、上網、上車，常表示開始或進入某個活動，或是搭上交通工具。","sc":"「上」有很多用法，像上课、上班、上网、上车，常表示开始或进入某个活动，或是搭上交通工具。"},"ex":[{"c":"他每天坐捷運上班。","s":"他每天坐捷运上班。","es":"Va al trabajo en metro todos los días.","en":"He takes the MRT to work every day."}]},{"id":"3-4-5","b":3,"l":4,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Sí o sí: 非…不可","en":"非…不可 it is imperative that…","ens":"非…不可 it is imperative that…","tc":"非…不可","sc":"非…不可"},"d":{"es":"非 A 不可 = es imprescindible A, tiene que ser A.","en":"非 A 不可 = must do A; there's no alternative.","tc":"非 A 不可：一定要 A，不能不。","sc":"非 A 不可：一定要 A，不能不。"},"ex":[{"c":"明天的會，你非來不可。","s":"明天的会，你非来不可。","es":"A la reunión de mañana tienes que venir sí o sí.","en":"You must come to tomorrow's meeting."}]},{"id":"3-4-6","b":3,"l":4,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Para…: 對…來說","en":"對…來說 as far as...is concerned, for","ens":"对…来说 as far as...is concerned, for","tc":"對…來說","sc":"对…来说"},"d":{"es":"對 X 來說 = para X, desde la perspectiva de X.","en":"對 X 來說 = for X, from X's point of view.","tc":"對＋人＋來說：從某人的角度來看。","sc":"对＋人＋来说：从某人的角度来看。"},"ex":[{"c":"對學生來說，睡眠很重要。","s":"对学生来说，睡眠很重要。","es":"Para los estudiantes, dormir es muy importante.","en":"For students, sleep is very important."}]},{"id":"3-4-7","b":3,"l":4,"k":"","t":{"es":"Ser exigente: 講究","en":"對…講究 to be discerning, discriminating, particular about","ens":"对…讲究 to be discerning, discriminating, particular about","tc":"對…講究","sc":"对…讲究"},"d":{"es":"對 X 很講究 = ser exigente o cuidadoso con X.","en":"對 X 很講究 = to be particular or demanding about X.","tc":"對＋事情＋很講究：對這件事要求很高、很在意。","sc":"对＋事情＋很讲究：对这件事要求很高、很在意。"},"ex":[{"c":"他對吃很講究。","s":"他对吃很讲究。","es":"Es muy exigente con la comida.","en":"He's very particular about food."}]},{"id":"3-5-0","b":3,"l":5,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lleno de: V滿","en":"Verb Plus Complement V+滿 crowded with","ens":"Verb Plus Complement V+满 crowded with","tc":"V滿","sc":"V满"},"d":{"es":"V + 滿 = llenar: el espacio queda lleno.","en":"Verb + 滿 = the space gets filled up.","tc":"動詞＋滿：空間被填滿了。","sc":"动词＋满：空间被填满了。"},"ex":[{"c":"教室裡坐滿了人。","s":"教室里坐满了人。","es":"El salón está lleno de gente sentada.","en":"The classroom is full of people sitting."}]},{"id":"3-5-1","b":3,"l":5,"k":"","t":{"es":"Salir/descubrir: V出","en":"Verb Particle 出 to have emerged","ens":"Verb Particle 出 to have emerged","tc":"V出（來）","sc":"V出（来）"},"d":{"es":"V + 出 (來) = salir o aparecer; también descubrir o distinguir: 想出, 做出, 看出.","en":"Verb + 出(來) = come out or make out, discover: 想出, 做出, 看出.","tc":"動詞＋出（來）：出現、發現或分辨出來，例如想出、做出、看出。","sc":"动词＋出（来）：出现、发现或分辨出来，例如想出、做出、看出。"},"ex":[{"c":"我看不出他是外國人。","s":"我看不出他是外国人。","es":"No me doy cuenta de que sea extranjero.","en":"I can't tell that he is a foreigner."}]},{"id":"3-5-2","b":3,"l":5,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"No tan bueno: 不如","en":"不如 not as good as","ens":"不如 not as good as","tc":"不如","sc":"不如"},"d":{"es":"A 不如 B = A no es tan bueno como B (B es mejor).","en":"A 不如 B = A is not as good as B.","tc":"A 不如 B：A 沒有 B 好。","sc":"A 不如 B：A 没有 B 好。"},"ex":[{"c":"坐車不如坐捷運方便。","s":"坐车不如坐捷运方便。","es":"Ir en coche no es tan cómodo como ir en metro.","en":"Going by car is not as convenient as taking the MRT."}]},{"id":"3-5-3","b":3,"l":5,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Si no…ya: 再不…就…了","en":"Urgent Conditional with 再不…就…了","ens":"Urgent Conditional with 再不…就…了","tc":"再不…就…了","sc":"再不…就…了"},"d":{"es":"再不 A 就 B 了 = si no hacemos A ya, ocurrirá B (urgencia).","en":"再不 A 就 B 了 = if we don't do A now, B will happen (urgency).","tc":"再不 A 就 B 了：如果現在還不做 A，馬上就會出問題，有急迫的感覺。","sc":"再不 A 就 B 了：如果现在还不做 A，马上就会出问题，有急迫的感觉。"},"ex":[{"c":"再不走，就來不及了。","s":"再不走，就来不及了。","es":"Si no nos vamos ya, no llegamos.","en":"If we don't leave now, we'll be too late."}]},{"id":"3-5-4","b":3,"l":5,"k":"","t":{"es":"Quitar: V掉","en":"Verb Particle 掉 separated from","ens":"Verb Particle 掉 separated from","tc":"V掉","sc":"V掉"},"d":{"es":"V + 掉 = quitar, eliminar o perder: 丟掉, 吃掉, 忘掉.","en":"Verb + 掉 = get rid of, away, lose: 丟掉, 吃掉, 忘掉.","tc":"動詞＋掉：去掉、消失、失去，例如丟掉、吃掉、忘掉。","sc":"动词＋掉：去掉、消失、失去，例如丢掉、吃掉、忘掉。"},"ex":[{"c":"請把垃圾丟掉。","s":"请把垃圾丢掉。","es":"Por favor tira la basura.","en":"Please throw away the trash."}]},{"id":"3-5-5","b":3,"l":5,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"¡Increíble!: 居然","en":"居然 to one’s surprise","ens":"居然 to one’s surprise","tc":"居然","sc":"居然"},"d":{"es":"居然 = increíblemente, ¡quién lo diría! (sorpresa).","en":"居然 = unexpectedly, surprisingly (expresses surprise).","tc":"居然：沒想到，帶有驚訝的語氣。","sc":"居然：没想到，带有惊讶的语气。"},"ex":[{"c":"他居然忘了今天考試。","s":"他居然忘了今天考试。","es":"¡Increíble, se olvidó del examen de hoy!","en":"He actually forgot there's an exam today!"}]},{"id":"3-5-6","b":3,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Ya que: 既然…就","en":"Concession with 既然…（就）… since…(then)…","ens":"Concession with 既然…（就）… since…(then)…","tc":"既然…（就）…","sc":"既然…（就）…"},"d":{"es":"既然 A (就) B = ya que A, entonces B (A es un hecho aceptado).","en":"既然 A，(就) B = since A is already the case, then B.","tc":"既然 A，（就）B：A 已經是事實，所以接著 B。","sc":"既然 A，（就）B：A 已经是事实，所以接着 B。"},"ex":[{"c":"既然你累了，就早點休息吧。","s":"既然你累了，就早点休息吧。","es":"Ya que estás cansado, descansa temprano.","en":"Since you're tired, get some rest early."}]},{"id":"3-5-7","b":3,"l":5,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No parar: V個不停","en":"V+個不停 keep on…","ens":"V+个不停 keep on…","tc":"V個不停","sc":"V个不停"},"d":{"es":"V + 個不停 = no parar de hacer algo.","en":"Verb + 個不停 = keep doing, can't stop.","tc":"動詞＋個不停：一直做，停不下來。","sc":"动词＋个不停：一直做，停不下来。"},"ex":[{"c":"孩子哭個不停。","s":"孩子哭个不停。","es":"El niño no deja de llorar.","en":"The child keeps crying."}]},{"id":"3-6-0","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 tiempo momento orden secuencia time order sequence 时间 顺序 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Justo por: 因為…才","en":"因為…才… only because…","ens":"因为…才… only because…","tc":"因為…才…","sc":"因为…才…"},"d":{"es":"因為 A 才 B = justamente por A es que B.","en":"因為 A 才 B = it's precisely because of A that B happens.","tc":"因為 A 才 B：正是因為 A，所以 B 才會發生。","sc":"因为 A 才 B：正是因为 A，所以 B 才会发生。"},"ex":[{"c":"就是因為你幫我，我才成功。","s":"就是因为你帮我，我才成功。","es":"Fue justo porque tú me ayudaste que tuve éxito.","en":"It was precisely because you helped me that I succeeded."}]},{"id":"3-6-1","b":3,"l":6,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Y encima: …不說，…也…","en":"Complaining with …S1…不說，S2 也… not merely, but also","ens":"Complaining with …S1…不说，S2 也… not merely, but also","tc":"…不說，…也…","sc":"…不说，…也…"},"d":{"es":"S1 … 不說，S2 也… = no solo S1, además S2 (para quejarse de algo que se suma).","en":"S1 …不說，S2 也… = not to mention S1, S2 too (used to complain).","tc":"S1 不說，S2 也…：除了前面那件事，後面還有另一件，常用來抱怨。","sc":"S1 不说，S2 也…：除了前面那件事，后面还有另一件，常用来抱怨。"},"ex":[{"c":"他遲到不說，也不道歉。","s":"他迟到不说，也不道歉。","es":"Llegó tarde y encima no pidió disculpas.","en":"He was late, and on top of that he didn't apologize."}]},{"id":"3-6-2","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"Sumado a: 再加上","en":"再加上 furthermore","ens":"再加上 furthermore","tc":"再加上","sc":"再加上"},"d":{"es":"再加上 = sumado a, además. Añade otra razón.","en":"再加上 = on top of that, adds another reason.","tc":"再加上：再多加一個原因。","sc":"再加上：再多加一个原因。"},"ex":[{"c":"天氣冷，再加上下雨，我不想出門。","s":"天气冷，再加上下雨，我不想出门。","es":"Hace frío y además llueve, no quiero salir.","en":"It's cold, and it's raining too; I don't want to go out."}]},{"id":"3-6-3","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 contraste pero sin embargo contrast but however 對比 轉折 tiempo momento orden secuencia time order sequence 时间 顺序 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"De todo, pero: 什麼都…就是","en":"什麼都…，就是… everything but …","ens":"什么都…，就是… everything but …","tc":"什麼都…，就是…","sc":"什么都…，就是…"},"d":{"es":"什麼都 A，就是 B = de todo A, pero no B.","en":"什麼都 A，就是 B = anything is fine, except B.","tc":"什麼都 A，就是 B：什麼都可以，只有 B 例外。","sc":"什么都 A，就是 B：什么都可以，只有 B 例外。"},"ex":[{"c":"我什麼都吃，就是不吃香菜。","s":"我什么都吃，就是不吃香菜。","es":"Como de todo, menos cilantro.","en":"I eat everything, except cilantro."}]},{"id":"3-6-4","b":3,"l":6,"k":"","t":{"es":"Preferir…: 寧可…也要","en":"寧可…也要… would rather…, in order to…","ens":"宁可…也要… would rather…, in order to…","tc":"寧可…也要…","sc":"宁可…也要…"},"d":{"es":"寧可 A 也要 B = preferir A antes que renunciar a B (sacrificio).","en":"寧可 A 也要 B = would rather give up A than not get B.","tc":"寧可 A 也要 B：願意犧牲 A，也一定要做到 B。","sc":"宁可 A 也要 B：愿意牺牲 A，也一定要做到 B。"},"ex":[{"c":"他寧可不睡覺也要把書看完。","s":"他宁可不睡觉也要把书看完。","es":"Prefiere no dormir con tal de terminar el libro.","en":"He'd rather not sleep than not finish the book."}]},{"id":"3-6-5","b":3,"l":6,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Como…: 像…的+N","en":"像…的+noun such (nouns) as","ens":"像…的+noun such (nouns) as","tc":"像…的＋名詞","sc":"像…的＋名词"},"d":{"es":"像 X 的 N = N como X (da ejemplos de una categoría).","en":"像 X 的 N = N such as X (X gives examples of the category).","tc":"像 X 的 N：用 X 當例子說明這一類東西。","sc":"像 X 的 N：用 X 当例子说明这一类东西。"},"ex":[{"c":"像芒果、西瓜的水果，我都喜歡。","s":"像芒果、西瓜的水果，我都喜欢。","es":"Frutas como el mango y la sandía, me gustan todas.","en":"I like fruits such as mango and watermelon."}]},{"id":"3-6-6","b":3,"l":6,"k":"","t":{"es":"Por un lado: 一方面…","en":"一方面…，一方面… on the one hand, …, on the other","ens":"一方面…，一方面… on the one hand, …, on the other","tc":"一方面…，一方面…","sc":"一方面…，一方面…"},"d":{"es":"一方面 A，一方面 B = por un lado A, por otro lado B.","en":"一方面 A，一方面 B = on the one hand A, on the other hand B.","tc":"一方面 A，一方面 B：同時有兩件事或兩個角度。","sc":"一方面 A，一方面 B：同时有两件事或两个角度。"},"ex":[{"c":"一方面要工作，一方面要念書，很累。","s":"一方面要工作，一方面要念书，很累。","es":"Por un lado trabajar y por otro estudiar, es agotador.","en":"On the one hand I have to work, on the other I have to study; it's tiring."}]},{"id":"3-6-7","b":3,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"A medida que: 隨著","en":"隨著 S1…，S2 也… as a consequence of…","ens":"随着 S1…，S2 也… as a consequence of…","tc":"隨著…，…也…","sc":"随着…，…也…"},"d":{"es":"隨著 X，Y 也… = a medida que X, Y también…","en":"隨著 X，Y 也… = as X changes, Y changes too.","tc":"隨著 X，Y 也…：X 改變時，Y 跟著改變。","sc":"随着 X，Y 也…：X 改变时，Y 跟着改变。"},"ex":[{"c":"隨著年紀增加，他的想法也不一樣了。","s":"随着年纪增加，他的想法也不一样了。","es":"A medida que crece, sus ideas también cambian.","en":"As he gets older, his way of thinking also changes."}]},{"id":"3-7-0","b":3,"l":7,"k":"","t":{"es":"Sin cuidado: 亂+V","en":"亂＋V to do something in an irresponsible manner,","ens":"乱＋V to do something in an irresponsible manner,","tc":"亂＋動詞","sc":"乱＋动词"},"d":{"es":"亂 + verbo = hacer algo sin orden ni cuidado.","en":"亂 + verb = do something carelessly or without order.","tc":"亂＋動詞：沒有規矩、沒有秩序地做某件事。","sc":"乱＋动词：没有规矩、没有秩序地做某件事。"},"ex":[{"c":"不要亂丟垃圾。","s":"不要乱丢垃圾。","es":"No tires basura por cualquier lado.","en":"Don't litter."}]},{"id":"3-7-1","b":3,"l":7,"k":"","t":{"es":"Cada uno: 各V各的","en":"各 V 各的 each doing her/his own…","ens":"各 V 各的 each doing her/his own…","tc":"各V各的","sc":"各V各的"},"d":{"es":"各 V 各的 = cada uno hace lo suyo.","en":"各 V 各的 = everyone does their own thing.","tc":"各 V 各的：大家各做各的事，互不相干。","sc":"各 V 各的：大家各做各的事，互不相干。"},"ex":[{"c":"吃飯的時候，大家各玩各的手機。","s":"吃饭的时候，大家各玩各的手机。","es":"Mientras comen, cada uno juega con su celular.","en":"During meals, everyone plays with their own phone."}]},{"id":"3-7-2","b":3,"l":7,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Aunque: 就算…也","en":"就算…，也… even if…(S1) …, would…(S2)…","ens":"就算…，也… even if…(S1) …, would…(S2)…","tc":"就算…，也…","sc":"就算…，也…"},"d":{"es":"就算 A，也 B = aunque A (hipótesis), igual B.","en":"就算 A，也 B = even if A happens, B still holds.","tc":"就算 A，也 B：假設 A 發生，結果還是 B。","sc":"就算 A，也 B：假设 A 发生，结果还是 B。"},"ex":[{"c":"就算下雨，我也要去。","s":"就算下雨，我也要去。","es":"Aunque llueva, voy a ir.","en":"Even if it rains, I'm going."}]},{"id":"3-7-3","b":3,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Debido a: 因為+N","en":"因為 NP，S… because of NP, S…","ens":"因为 NP，S… because of NP, S…","tc":"因為＋名詞","sc":"因为＋名词"},"d":{"es":"因為 + sustantivo，S… = debido a + sustantivo.","en":"因為 + noun, clause = because of a noun (not a full clause).","tc":"因為＋名詞，句子：說明原因是某個事物，不是一個句子。","sc":"因为＋名词，句子：说明原因是某个事物，不是一个句子。"},"ex":[{"c":"因為天氣，比賽取消了。","s":"因为天气，比赛取消了。","es":"Por el clima, se canceló el partido.","en":"Because of the weather, the game was canceled."}]},{"id":"3-7-4","b":3,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Primero…segundo: 一來…二來","en":"一來…，二來… on the one hand…, and on the other…; first…, second…","ens":"一来…，二来… on the one hand…, and on the other…; first…, second…","tc":"一來…，二來…","sc":"一来…，二来…"},"d":{"es":"一來 A，二來 B = primero A, segundo B (enumera razones).","en":"一來 A，二來 B = first A, second B (lists two reasons).","tc":"一來 A，二來 B：列出兩個理由。","sc":"一来 A，二来 B：列出两个理由。"},"ex":[{"c":"我不去，一來太遠，二來沒時間。","s":"我不去，一来太远，二来没时间。","es":"No voy: primero, está muy lejos; segundo, no tengo tiempo.","en":"I'm not going: first, it's too far; second, I have no time."}]},{"id":"3-7-5","b":3,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"De un lado a otro: V來V去","en":"Repetitively, Back and Forth with V 來 V 去","ens":"Repetitively, Back and Forth with V 来 V 去","tc":"V來V去","sc":"V来V去"},"d":{"es":"V 來 V 去 = hacer algo de aquí para allá o una y otra vez.","en":"V 來 V 去 = do the same action back and forth, or over and over.","tc":"V 來 V 去：同一個動作來回做，或一直重複。","sc":"V 来 V 去：同一个动作来回做，或一直重复。"},"ex":[{"c":"他走來走去。","s":"他走来走去。","es":"Camina de un lado a otro.","en":"He walks back and forth."},{"c":"我想來想去，還是不去。","s":"我想来想去，还是不去。","es":"Lo pensé y lo pensé, y al final decidí no ir.","en":"I thought it over and over, and still decided not to go."}]},{"id":"3-7-6","b":3,"l":7,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ya no: 不再…了","en":"不再…了 not…any more","ens":"不再…了 not…any more","tc":"不再…了","sc":"不再…了"},"d":{"es":"不再 + verbo + 了 = ya no (algo que antes sí se hacía).","en":"不再 + verb + 了 = no longer (used to, but not anymore).","tc":"不再＋動詞＋了：以前會做，現在不做了。","sc":"不再＋动词＋了：以前会做，现在不做了。"},"ex":[{"c":"他不再喝咖啡了。","s":"他不再喝咖啡了。","es":"Ya no toma café.","en":"He doesn't drink coffee anymore."}]},{"id":"3-8-0","b":3,"l":8,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"O…o: 不是…就是","en":"不是…就是… if it's not…, then it’s…","ens":"不是…就是… if it's not…, then it’s…","tc":"不是…就是…","sc":"不是…就是…"},"d":{"es":"不是 A 就是 B = o bien A o bien B.","en":"不是 A 就是 B = it's either A or B.","tc":"不是 A 就是 B：只有這兩種可能。","sc":"不是 A 就是 B：只有这两种可能。"},"ex":[{"c":"他週末不是看書就是睡覺。","s":"他周末不是看书就是睡觉。","es":"Los fines de semana o lee o duerme.","en":"On weekends he's either reading or sleeping."}]},{"id":"3-8-1","b":3,"l":8,"k":"","t":{"es":"Olvídalo: 算了","en":"算了 forget it, drop it","ens":"算了 forget it, drop it","tc":"算了","sc":"算了"},"d":{"es":"算了 = déjalo, olvídalo (dejar pasar o renunciar).","en":"算了 = forget it, drop it, let it go.","tc":"算了：不再想了、放棄、不計較。","sc":"算了：不再想了、放弃、不计较。"},"ex":[{"c":"太貴了，算了。","s":"太贵了，算了。","es":"Es muy caro, mejor olvídalo.","en":"It's too expensive, forget it."}]},{"id":"3-8-2","b":3,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Así que: 這樣一來","en":"這樣一來 that being the case, that way","ens":"这样一来 that being the case, that way","tc":"這樣一來","sc":"这样一来"},"d":{"es":"這樣一來 = de esta manera, en ese caso (introduce la consecuencia).","en":"這樣一來 = in that case, this way (introduces a consequence).","tc":"這樣一來：這樣的話，接著會出現某個結果。","sc":"这样一来：这样的话，接着会出现某个结果。"},"ex":[{"c":"這樣一來，我們就不用等了。","s":"这样一来，我们就不用等了。","es":"Así ya no tenemos que esperar.","en":"This way, we don't have to wait."}]},{"id":"3-8-3","b":3,"l":8,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ya hace tiempo: 早就…了","en":"早就…了 long since…","ens":"早就…了 long since…","tc":"早就…了","sc":"早就…了"},"d":{"es":"早就 + verbo + 了 = hace mucho que ya…","en":"早就 + verb + 了 = already a long time ago.","tc":"早就＋動詞＋了：很久以前就已經…。","sc":"早就＋动词＋了：很久以前就已经…。"},"ex":[{"c":"我早就知道了。","s":"我早就知道了。","es":"Hace tiempo que lo sé.","en":"I knew a long time ago."}]},{"id":"3-8-4","b":3,"l":8,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"A partir de: 從…起","en":"從…起 starting from…","ens":"从…起 starting from…","tc":"從…起","sc":"从…起"},"d":{"es":"從 + tiempo / lugar + 起 = a partir de.","en":"從 + time/place + 起 = starting from.","tc":"從＋時間或地點＋起：從那裡開始算。","sc":"从＋时间或地点＋起：从那里开始算。"},"ex":[{"c":"從明天起，我要早起。","s":"从明天起，我要早起。","es":"A partir de mañana voy a madrugar.","en":"Starting tomorrow, I'm going to get up early."}]},{"id":"3-8-5","b":3,"l":8,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Sin embargo: 卻","en":"卻 however","ens":"却 however","tc":"卻","sc":"却"},"d":{"es":"卻 = sin embargo, en cambio (contraste inesperado). Va antes del verbo.","en":"卻 = but, however (contrary to expectation), placed before the verb.","tc":"卻：前後意思相反，有「沒想到」的感覺，放在動詞前面。","sc":"却：前后意思相反，有「没想到」的感觉，放在动词前面。"},"ex":[{"c":"他很聰明，卻不愛念書。","s":"他很聪明，却不爱念书。","es":"Es muy inteligente, pero no le gusta estudiar.","en":"He's very smart but doesn't like studying."}]},{"id":"3-8-6","b":3,"l":8,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Por…: 因為…而…","en":"因為…而… therefore, consequently","ens":"因为…而… therefore, consequently","tc":"因為…而…","sc":"因为…而…"},"d":{"es":"因為 X 而 V = por X, (resulta) V. Es una forma más escrita.","en":"因為 X 而 V = because of X, V happens (more literary).","tc":"因為 X 而 V：因為 X，所以 V，比較書面。","sc":"因为 X 而 V：因为 X，所以 V，比较书面。"},"ex":[{"c":"他因為生病而沒來上課。","s":"他因为生病而没来上课。","es":"No vino a clase porque se enfermó.","en":"He didn't come to class because he got sick."}]},{"id":"3-8-7","b":3,"l":8,"k":"","t":{"es":"Tras: 經過","en":"經過 after","ens":"经过 after","tc":"經過","sc":"经过"},"d":{"es":"經過 = pasar por (un lugar) o tras (un proceso o tiempo).","en":"經過 = pass through a place, or after going through a process or period of time.","tc":"經過：走過某個地方，或是經歷一段過程、一段時間之後。","sc":"经过：走过某个地方，或是经历一段过程、一段时间之后。"},"ex":[{"c":"經過一年的努力，他通過了考試。","s":"经过一年的努力，他通过了考试。","es":"Tras un año de esfuerzo, aprobó el examen.","en":"After a year of hard work, he passed the exam."}]},{"id":"3-9-0","b":3,"l":9,"k":"","t":{"es":"Depender de: 靠","en":"靠 to rely on, by means of","ens":"靠 to rely on, by means of","tc":"靠","sc":"靠"},"d":{"es":"靠 = depender de, apoyarse en.","en":"靠 = rely on, depend on.","tc":"靠：依賴、憑著某個人或某件事。","sc":"靠：依赖、凭着某个人或某件事。"},"ex":[{"c":"他靠自己的努力考上大學。","s":"他靠自己的努力考上大学。","es":"Entró a la universidad gracias a su propio esfuerzo.","en":"He got into university through his own effort."}]},{"id":"3-9-1","b":3,"l":9,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Tanto…como: 既…又","en":"既…又… not merely…, but…as well","ens":"既…又… not merely…, but…as well","tc":"既…又…","sc":"既…又…"},"d":{"es":"既 A 又 B = tanto A como B (dos cualidades; más formal que 又…又…).","en":"既 A 又 B = both A and B (two qualities; more formal than 又…又…).","tc":"既 A 又 B：同時有兩個特點，比「又…又…」更書面。","sc":"既 A 又 B：同时有两个特点，比「又…又…」更书面。"},"ex":[{"c":"這裡既安靜又乾淨。","s":"这里既安静又干净。","es":"Este lugar es tranquilo y limpio.","en":"This place is both quiet and clean."}]},{"id":"3-9-2","b":3,"l":9,"k":"","t":{"es":"Dentro de: 以內","en":"…以內 within …","ens":"…以内 within …","tc":"以內","sc":"以内"},"d":{"es":"以內 = dentro de (un límite de cantidad, tiempo o espacio).","en":"以內 = within (a limit of quantity, time or space).","tc":"以內：不超過某個範圍（數量、時間、空間）。","sc":"以内：不超过某个范围（数量、时间、空间）。"},"ex":[{"c":"請在三天以內回覆。","s":"请在三天以内回复。","es":"Por favor responde en un plazo de tres días.","en":"Please reply within three days."}]},{"id":"3-9-3","b":3,"l":9,"k":"","t":{"es":"Representar: 占","en":"占 to constitute","ens":"占 to constitute","tc":"占","sc":"占"},"d":{"es":"占 = ocupar o representar (una parte o porcentaje).","en":"占 = to take up or make up (a proportion or space).","tc":"占：佔有某個比例或空間。","sc":"占：占有某个比例或空间。"},"ex":[{"c":"女生占全班的一半。","s":"女生占全班的一半。","es":"Las mujeres son la mitad de la clase.","en":"Girls make up half of the class."}]},{"id":"3-9-4","b":3,"l":9,"k":"","t":{"es":"En cuanto a: (在)…上","en":"（在） NP 上 regarding NP","ens":"（在） NP 上 regarding NP","tc":"（在）…上","sc":"（在）…上"},"d":{"es":"(在) N 上 = en el aspecto de N, en cuanto a N.","en":"(在) N 上 = in the area of N, regarding N.","tc":"（在）＋名詞＋上：在某方面、就某件事來說。","sc":"（在）＋名词＋上：在某方面、就某件事来说。"},"ex":[{"c":"在學習上，他很認真。","s":"在学习上，他很认真。","es":"En los estudios, él es muy aplicado.","en":"In his studies, he is very diligent."}]},{"id":"3-9-5","b":3,"l":9,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Traer a: 給…帶來","en":"給…帶來 to bring… to…","ens":"给…带来 to bring… to…","tc":"給…帶來…","sc":"给…带来…"},"d":{"es":"給 A 帶來 B = traerle B a A (efecto o consecuencia).","en":"給 A 帶來 B = bring B to A (an effect or consequence).","tc":"給 A 帶來 B：對 A 產生 B 這個影響。","sc":"给 A 带来 B：对 A 产生 B 这个影响。"},"ex":[{"c":"網路給我們帶來很多方便。","s":"网路给我们带来很多方便。","es":"Internet nos trae muchas comodidades.","en":"The internet has brought us a lot of convenience."}]},{"id":"3-9-6","b":3,"l":9,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Al final: 結果","en":"結果 consequently, in the end","ens":"结果 consequently, in the end","tc":"結果","sc":"结果"},"d":{"es":"結果 = el resultado fue…, al final (el desenlace de algo).","en":"結果 = in the end, the outcome (often unexpected).","tc":"結果：最後的結局，常和預期不同。","sc":"结果：最后的结局，常和预期不同。"},"ex":[{"c":"我等了很久，結果他沒來。","s":"我等了很久，结果他没来。","es":"Esperé mucho y al final no vino.","en":"I waited a long time, and in the end he didn't come."}]},{"id":"3-10-0","b":3,"l":10,"k":"","t":{"es":"En cuanto a: 至於","en":"Introducing a New Topic with 至於…, as to, as far","ens":"Introducing a New Topic with 至于…, as to, as far","tc":"至於","sc":"至于"},"d":{"es":"至於 = en cuanto a… (cambia a otro tema).","en":"至於 = as for (switches to another topic).","tc":"至於：換一個話題，意思是「說到…的話」。","sc":"至于：换一个话题，意思是「说到…的话」。"},"ex":[{"c":"我去，至於他去不去，我不知道。","s":"我去，至于他去不去，我不知道。","es":"Yo voy; en cuanto a si él va o no, no lo sé.","en":"I'm going; as for whether he's going, I don't know."}]},{"id":"3-10-1","b":3,"l":10,"k":"","t":{"es":"Depende de: A看B","en":"看 depends on","ens":"看 depends on","tc":"A 看 B","sc":"A 看 B"},"d":{"es":"A 看 B = A depende de B.","en":"A 看 B = A depends on B.","tc":"A 看 B：A 要看 B 的情況才能決定。","sc":"A 看 B：A 要看 B 的情况才能决定。"},"ex":[{"c":"去不去看天氣。","s":"去不去看天气。","es":"Ir o no depende del clima.","en":"Whether we go depends on the weather."}]},{"id":"3-10-2","b":3,"l":10,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Siempre: 一向","en":"一向 all along, has always…","ens":"一向 all along, has always…","tc":"一向","sc":"一向"},"d":{"es":"一向 = siempre (desde antes hasta ahora, como hábito).","en":"一向 = always, all along (from before until now, as a habit).","tc":"一向：從以前到現在都是這樣，已成習慣。","sc":"一向：从以前到现在都是这样，已成习惯。"},"ex":[{"c":"他一向早起。","s":"他一向早起。","es":"Siempre se ha levantado temprano.","en":"He has always gotten up early."}]},{"id":"3-10-3","b":3,"l":10,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Por ejemplo: 拿…來說","en":"拿…來說 take…as an example","ens":"拿…来说 take…as an example","tc":"拿…來說","sc":"拿…来说"},"d":{"es":"拿 X 來說 = tomando X como ejemplo.","en":"拿 X 來說 = take X as an example.","tc":"拿 X 來說：用 X 當例子來說明。","sc":"拿 X 来说：用 X 当例子来说明。"},"ex":[{"c":"拿我自己來說，我就不喜歡吃辣。","s":"拿我自己来说，我就不喜欢吃辣。","es":"Por ejemplo, yo no como picante.","en":"Take myself, for example: I don't like spicy food."}]},{"id":"3-10-4","b":3,"l":10,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Pasiva formal: 受","en":"Passive Sentences with 受","ens":"Passive Sentences with 受","tc":"被動句「受」","sc":"被动句「受」"},"d":{"es":"受 + sustantivo: 受到歡迎 (ser bien recibido), 受傷 (herirse), 受影響 (ser afectado). Pasiva de estilo más formal.","en":"受 + noun: 受到歡迎 (be welcomed), 受傷 (get hurt), 受影響 (be affected); a more formal passive.","tc":"受＋名詞：受到歡迎、受傷、受影響，比「被」更書面。","sc":"受＋名词：受到欢迎、受伤、受影响，比「被」更书面。"},"ex":[{"c":"這部電影很受歡迎。","s":"这部电影很受欢迎。","es":"Esta película es muy popular.","en":"This movie is very popular."}]},{"id":"3-10-5","b":3,"l":10,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por cualquier cosa: 動不動就","en":"動不動就… to do something impetuously","ens":"动不动就… to do something impetuously","tc":"動不動就","sc":"动不动就"},"d":{"es":"動不動就 + verbo = a la menor ocasión, por cualquier cosa (negativo).","en":"動不動就 + verb = at the slightest thing; usually negative behavior.","tc":"動不動就＋動詞：一點小事就會…，多用在不好的行為。","sc":"动不动就＋动词：一点小事就会…，多用在不好的行为。"},"ex":[{"c":"他動不動就生氣。","s":"他动不动就生气。","es":"Se enoja por cualquier cosa.","en":"He gets angry at the slightest thing."}]},{"id":"3-11-0","b":3,"l":11,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"En realidad: 到底","en":"到底 after all? how on earth…?","ens":"到底 after all? how on earth…?","tc":"到底","sc":"到底"},"d":{"es":"到底 = en realidad, ¿qué demonios…? Insiste en una pregunta.","en":"到底 = on earth, exactly (presses a question); also 'after all'.","tc":"到底：用在問句，想問出真正的答案；也有「畢竟」的意思。","sc":"到底：用在问句，想问出真正的答案；也有「毕竟」的意思。"},"ex":[{"c":"你到底想吃什麼？","s":"你到底想吃什么？","es":"¿Pero qué quieres comer en realidad?","en":"What on earth do you want to eat?"}]},{"id":"3-11-1","b":3,"l":11,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Incluso: 甚至","en":"甚至 even","ens":"甚至 even","tc":"甚至","sc":"甚至"},"d":{"es":"甚至 = incluso, hasta (el caso extremo).","en":"甚至 = even (points to an extreme case).","tc":"甚至：連…也，說到更極端的情況。","sc":"甚至：连…也，说到更极端的情况。"},"ex":[{"c":"他很忙，甚至沒有時間吃飯。","s":"他很忙，甚至没有时间吃饭。","es":"Está muy ocupado, incluso no tiene tiempo para comer.","en":"He is so busy that he doesn't even have time to eat."}]},{"id":"3-11-2","b":3,"l":11,"k":"","t":{"es":"Entonces: 這麼說","en":"這麼說 that being the case, in that case","ens":"这么说 that being the case, in that case","tc":"這麼說","sc":"这么说"},"d":{"es":"這麼說 = entonces, siendo así… (se concluye a partir de lo que dijo el otro).","en":"這麼說 = in that case, so (drawing a conclusion from what was just said).","tc":"這麼說：根據對方說的話，得出一個結論。","sc":"这么说：根据对方说的话，得出一个结论。"},"ex":[{"c":"這麼說，你已經知道了？","s":"这么说，你已经知道了？","es":"Entonces, ¿ya lo sabías?","en":"So, you already knew?"}]},{"id":"3-11-3","b":3,"l":11,"k":"","t":{"es":"Relacionado con: 跟B有關的A","en":"跟 B 有關的 A A is related to B","ens":"跟 B 有关的 A A is related to B","tc":"跟…有關的…","sc":"跟…有关的…"},"d":{"es":"跟 B 有關的 A = A relacionado con B.","en":"跟 B 有關的 A = A that is related to B.","tc":"跟 B 有關的 A：和 B 有關係的 A。","sc":"跟 B 有关的 A：和 B 有关系的 A。"},"ex":[{"c":"我想看跟台灣歷史有關的書。","s":"我想看跟台湾历史有关的书。","es":"Quiero leer libros sobre la historia de Taiwán.","en":"I want to read books about Taiwan's history."}]},{"id":"3-11-4","b":3,"l":11,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No hay remedio: 不得不","en":"不得不 have no choice but to","ens":"不得不 have no choice but to","tc":"不得不","sc":"不得不"},"d":{"es":"不得不 + verbo = no tener más remedio que, verse obligado a.","en":"不得不 + verb = have no choice but to, forced by circumstances.","tc":"不得不＋動詞：因為情況，沒有別的選擇。","sc":"不得不＋动词：因为情况，没有别的选择。"},"ex":[{"c":"太晚了，我不得不回家。","s":"太晚了，我不得不回家。","es":"Es muy tarde, no tengo más remedio que irme a casa.","en":"It's too late; I have no choice but to go home."}]},{"id":"3-11-5","b":3,"l":11,"k":"","t":{"es":"Así como: 以及","en":"以及 as well as","ens":"以及 as well as","tc":"以及","sc":"以及"},"d":{"es":"以及 = así como. Une sustantivos (más formal).","en":"以及 = as well as (a more formal 'and', linking nouns).","tc":"以及：「和」的書面說法，連接名詞。","sc":"以及：「和」的书面说法，连接名词。"},"ex":[{"c":"我買了蘋果、香蕉以及芒果。","s":"我买了苹果、香蕉以及芒果。","es":"Compré manzanas, plátanos y mangos.","en":"I bought apples, bananas and mangoes."}]},{"id":"3-12-0","b":3,"l":12,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Solo…: 只不過","en":"只不過… (而已) merely…; nothing more than…","ens":"只不过… (而已) merely…; nothing more than…","tc":"只不過…（而已）","sc":"只不过…（而已）"},"d":{"es":"只不過…(而已) = simplemente, no es más que…","en":"只不過…(而已) = merely, nothing more than.","tc":"只不過…（而已）：只是…，沒有那麼嚴重或特別。","sc":"只不过…（而已）：只是…，没有那么严重或特别。"},"ex":[{"c":"這只不過是一個小問題而已。","s":"这只不过是一个小问题而已。","es":"Esto no es más que un pequeño problema.","en":"This is just a small problem."}]},{"id":"3-12-1","b":3,"l":12,"k":"","t":{"es":"A cargo de: 由","en":"Introducing an Agent with 由","ens":"Introducing an Agent with 由","tc":"由","sc":"由"},"d":{"es":"由 + agente + verbo = a cargo de, por parte de (quien hace algo).","en":"由 + person/unit + verb = to be done by, in charge of.","tc":"由＋人或單位＋動詞：說明由誰負責做。","sc":"由＋人或单位＋动词：说明由谁负责做。"},"ex":[{"c":"這件事由我來做。","s":"这件事由我来做。","es":"De esto me encargo yo.","en":"I'll take care of this."}]},{"id":"3-12-2","b":3,"l":12,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Acaso…?: 難道","en":"難道… how could it possibly be true","ens":"难道… how could it possibly be true","tc":"難道…嗎？","sc":"难道…吗？"},"d":{"es":"難道…嗎？ = ¿acaso…? Pregunta retórica.","en":"難道…嗎？ = a rhetorical question: 'surely not?'.","tc":"難道…嗎？：反問句，意思是「不可能吧」。","sc":"难道…吗？：反问句，意思是「不可能吧」。"},"ex":[{"c":"難道你不知道嗎？","s":"难道你不知道吗？","es":"¿Acaso no lo sabías?","en":"Don't tell me you didn't know?"}]},{"id":"3-12-3","b":3,"l":12,"k":"","t":{"es":"Lleno: 滿","en":"To Reach a Ceiling with 滿","ens":"To Reach a Ceiling with 满","tc":"滿","sc":"满"},"d":{"es":"滿 = llegar al máximo, estar lleno: 客滿, 額滿, 坐滿.","en":"滿 = full to the maximum: 客滿, 額滿, 坐滿.","tc":"滿：到最多了，不能再多，例如客滿、額滿、坐滿。","sc":"满：到最多了，不能再多，例如客满、额满、坐满。"},"ex":[{"c":"今天餐廳客滿了。","s":"今天餐厅客满了。","es":"Hoy el restaurante está lleno.","en":"The restaurant is full today."}]},{"id":"3-12-4","b":3,"l":12,"k":"","t":{"es":"Por/para: 為","en":"Beneficiary marker 為","ens":"Beneficiary marker 为","tc":"為＋對象","sc":"为＋对象"},"d":{"es":"為 + beneficiario + verbo = por / para (a favor de).","en":"為 + beneficiary + verb = do something for someone.","tc":"為＋對象＋動詞：替誰、為了誰做某件事。","sc":"为＋对象＋动词：替谁、为了谁做某件事。"},"ex":[{"c":"他為家人工作。","s":"他为家人工作。","es":"Trabaja por su familia.","en":"He works for his family."}]},{"id":"3-12-5","b":3,"l":12,"k":"","t":{"es":"En el aspecto: (在)…方面","en":"（在）…方面 with respect to; regarding","ens":"（在）…方面 with respect to; regarding","tc":"（在）…方面","sc":"（在）…方面"},"d":{"es":"(在) X 方面 = en el aspecto de X, con respecto a X.","en":"(在) X 方面 = in terms of X, with respect to X.","tc":"（在）＋名詞＋方面：就某個方面來說。","sc":"（在）＋名词＋方面：就某个方面来说。"},"ex":[{"c":"在工作方面，他很努力。","s":"在工作方面，他很努力。","es":"En lo laboral, se esfuerza mucho.","en":"In terms of work, he works very hard."}]}]};
